    expect(() =>
      PasskeyModule.buildAuthenticationRequestFromServer({
        requestId: 'req_auth_1',
        publicKey: {
          challenge: 'SERVER_CHALLENGE',
          rpId: '',
        },
      } as any),
    ).toThrow('Authentication options are missing RP ID');
  });
});

