export class BackupModule {
  // ── Main import entry ──────────────────────────────────────
  static async importFromFile(
    filePath: string,
    source: ImportSource,
  ): Promise<ImportResult> {
    const result: ImportResult = {
      total: 0,
      imported: 0,
      skipped: 0,
      errors: [],
      source,
    };
    try {
      const content = await RNFS.readFile(filePath, 'utf8');
      if (!content.trim()) {
        result.errors.push('Dosya boş.');
        return result;
      }

      const ext = filePath.toLowerCase().split('.').pop() || '';
      let items: Partial<VaultItem>[] = [];

      switch (source) {
        case 'bitwarden':
          items =
            ext === 'csv'
              ? this.parseBitwardenCSV(content)
              : this.parseBitwardenJSON(content);
          break;
        case '1password':
          items = this.parse1Password(content, ext);
          break;
        case 'lastpass':
          items = this.parseLastPassCSV(content);
          break;
        case 'keepass':
          items =
            ext === 'xml'
              ? this.parseKeePassXML(content)
              : this.parseKeePassCSV(content);
          break;
        case 'chrome':
          items = this.parseChromeCSV(content);
          break;
        case 'dashlane':
          items =
            ext === 'csv'
              ? this.parseDashlaneCSV(content)
              : this.parseDashlaneJSON(content);
          break;
        case 'enpass':
          items =
            ext === 'csv'
              ? this.parseEnpassCSV(content)
              : this.parseEnpassJSON(content);
          break;
        case 'firefox':
          items = this.parseFirefoxCSV(content);
          break;
        case 'aegis_auth':
          items = this.parseAegisAuthJSON(content);
          break;
        case 'aegis_vault':
          items = this.parseAegisVaultJSON(content);
          break;
        case 'generic_csv':
          items = this.parseGenericCSV(content);
          break;
        case 'generic_json':
          items = this.parseGenericJSON(content);
          break;
      }

      result.total = items.length;

      for (const item of items) {
        try {
          if (!item.title || item.title.trim() === '') {
            item.title = item.url || item.username || 'İsimsiz Kayıt';
          }
          await SecurityModule.addItem(item);
          result.imported++;
        } catch (e: any) {
          result.skipped++;
          result.errors.push(
            `"${item.title}": ${e?.message || 'Bilinmeyen hata'}`,
          );
        }
      }

      if (source === 'aegis_vault' || source === 'generic_json') {
        try {
          const parsed = JSON.parse(content);
          if (Array.isArray(parsed?.sharedSpaces)) {
            for (const space of parsed.sharedSpaces) {
              await SecurityModule.saveSharedVaultSpace(space);
            }
          }
        } catch {}
      }

      await SecurityModule.logSecurityEvent('backup_import', 'success', {
        source,
        total: result.total,
        imported: result.imported,
        skipped: result.skipped,
      });
    } catch (e: any) {
      result.errors.push(`Dosya okunamadı: ${e?.message || 'Bilinmeyen hata'}`);
      await SecurityModule.logSecurityEvent('backup_import', 'failed', {
        source,
        reason: e?.message || 'read_failed',
      });
    }
    return result;
  }

  // ── Bitwarden CSV ──────────────────────────────────────────
  private static parseBitwardenCSV(content: string): Partial<VaultItem>[] {
    const rows = parseCSV(content);
    if (rows.length < 2) return [];
    const h = rows[0];
    const ci = {
      folder: findCol(h, ['folder']),
      fav: findCol(h, ['favorite']),
      type: findCol(h, ['type']),
      name: findCol(h, ['name']),
      notes: findCol(h, ['notes']),
      fields: findCol(h, ['fields']),
      reprompt: findCol(h, ['reprompt']),
      uri: findCol(h, ['login_uri']),
      user: findCol(h, ['login_username']),
      pass: findCol(h, ['login_password']),
      totp: findCol(h, ['login_totp']),
    };

    return rows.slice(1).map(r => {
      const type = getVal(r, ci.type);
      let category = 'login';
      if (type === 'card' || type === '3') category = 'card';
      else if (type === 'identity' || type === '4') category = 'identity';
      else if (type === 'note' || type === 'securenote' || type === '2')
        category = 'note';

      const data: any = {};
      if (getVal(r, ci.totp)) data.totp_secret = getVal(r, ci.totp);

      return {
        title: getVal(r, ci.name),
        username: getVal(r, ci.user),
        password: getVal(r, ci.pass),
        url: getVal(r, ci.uri),
        notes: getVal(r, ci.notes),
        category,
        favorite: getVal(r, ci.fav) === '1' ? 1 : 0,
        data: JSON.stringify(data),
      };
    });
  }

  // ── Bitwarden JSON ─────────────────────────────────────────
  private static parseBitwardenJSON(content: string): Partial<VaultItem>[] {
    const json = JSON.parse(content);
    if (json.encrypted) return [];

    return (json.items || []).map((item: any) => {
      let category = 'login';
      if (item.type === 3) category = 'card';
      else if (item.type === 4) category = 'identity';
      else if (item.type === 2) category = 'note';

      const login = item.login || {};
      const data: any = {};
      if (login.totp) data.totp_secret = login.totp;

      if (item.type === 3 && item.card) {
        data.cardholder = item.card.cardholderName || '';
        data.card_number = item.card.number || '';
        data.expiry = `${item.card.expMonth || ''}/${item.card.expYear || ''}`;
        data.cvv = item.card.code || '';
        data.brand = item.card.brand || '';
      }

      if (item.type === 4 && item.identity) {
        const id = item.identity;
        data.first_name = id.firstName || '';
        data.last_name = id.lastName || '';
        data.email = id.email || '';
        data.phone = id.phone || '';
        data.company = id.company || '';
        data.address = [
          id.address1,
          id.address2,
          id.city,
          id.state,
          id.postalCode,
          id.country,
        ]
          .filter(Boolean)
          .join(', ');
      }

      if (item.type === 2) {
        data.content = item.notes || '';
      }

      return {
        title: item.name || '',
        username: login.username || '',
        password: login.password || '',
        url: login.uris?.[0]?.uri || '',
        notes: item.type !== 2 ? item.notes || '' : '',
        category,
        favorite: item.favorite ? 1 : 0,
        data: JSON.stringify(data),
      };
    });
  }

  // ── 1Password ──────────────────────────────────────────────
  private static parse1Password(
    content: string,
    ext: string,
  ): Partial<VaultItem>[] {
    if (ext === 'csv') return this.parse1PasswordCSV(content);
    if (ext === '1pux' || ext === '1pif') {
      // 1pux is a zip; 1pif is line-delimited JSON — both are JSON-based
      try {
        return this.parse1PasswordJSON(content);
      } catch {
        return this.parseGenericJSON(content);
      }
    }
    return [];
  }

