  // ── Generic CSV ────────────────────────────────────────────
  private static parseGenericCSV(content: string): Partial<VaultItem>[] {
    const rows = parseCSV(content);
    if (rows.length < 2) return [];
    const h = rows[0];
    const ci = {
      title: findCol(h, [
        'title',
        'name',
        'site',
        'service',
        'account',
        'entry',
        'label',
      ]),
      user: findCol(h, [
        'username',
        'user',
        'login',
        'email',
        'e-mail',
        'mail',
        'account',
      ]),
      pass: findCol(h, ['password', 'pass', 'secret', 'pwd']),
      url: findCol(h, [
        'url',
        'website',
        'site',
        'domain',
        'uri',
        'web',
        'link',
        'address',
      ]),
      notes: findCol(h, [
        'notes',
        'note',
        'comments',
        'comment',
        'description',
        'extra',
        'memo',
      ]),
      cat: findCol(h, ['category', 'type', 'group', 'folder', 'tag']),
    };
    // If no recognizable columns, treat first cols as title,user,pass,url,notes
    if (ci.title < 0 && ci.user < 0 && ci.pass < 0) {
      ci.title = 0;
      ci.user = h.length > 1 ? 1 : -1;
      ci.pass = h.length > 2 ? 2 : -1;
      ci.url = h.length > 3 ? 3 : -1;
      ci.notes = h.length > 4 ? 4 : -1;
    }
    return rows.slice(1).map(r => ({
      title: getVal(r, ci.title) || getVal(r, ci.url) || 'İçe Aktarılan',
      username: getVal(r, ci.user),
      password: getVal(r, ci.pass),
      url: getVal(r, ci.url),
      notes: getVal(r, ci.notes),
      category: this.mapCategory(getVal(r, ci.cat)),
      favorite: 0,
      data: '{}',
    }));
  }

  // ── Generic JSON ───────────────────────────────────────────
  private static parseGenericJSON(content: string): Partial<VaultItem>[] {
    const json = JSON.parse(content);
    const items = Array.isArray(json)
      ? json
      : json.items ||
        json.entries ||
        json.passwords ||
        json.data ||
        json.logins ||
        [];
    return items.map((item: any) => ({
      title:
        item.title ||
        item.name ||
        item.site ||
        item.service ||
        item.label ||
        '',
      username: item.username || item.user || item.login || item.email || '',
      password: item.password || item.pass || item.secret || '',
      url: item.url || item.website || item.domain || item.uri || '',
      notes: item.notes || item.note || item.description || item.comments || '',
      category: this.mapCategory(
        item.category || item.type || item.group || '',
      ),
      favorite: item.favorite || item.fav ? 1 : 0,
      data: item.data || '{}',
    }));
  }

  private static mapCategory(cat: string): string {
    if (!cat) return 'login';
    const l = cat.toLowerCase();
    if (l.includes('card') || l.includes('payment') || l.includes('credit'))
      return 'card';
    if (l.includes('identity') || l.includes('id') || l.includes('personal'))
      return 'identity';
    if (l.includes('note') || l.includes('secure') || l.includes('memo'))
      return 'note';
    if (l.includes('wifi') || l.includes('wireless') || l.includes('network'))
      return 'wifi';
    return 'login';
  }

  // ═══════════════════════════════════════════════════════════════
  // IMPORT ENCRYPTED AEGIS (AES-256-GCM + KDF metadata)
  // ═══════════════════════════════════════════════════════════════
  static async importEncryptedAegis(
    filePath: string,
    password: string,
  ): Promise<ImportResult> {
    const result: ImportResult = {
      total: 0,
      imported: 0,
      skipped: 0,
      errors: [],
      source: 'aegis_vault',
    };
    try {
      const content = await RNFS.readFile(filePath, 'utf8');
      const json = JSON.parse(content);

      if (!json.encrypted || !json.data || !json.salt || !json.iv) {
        result.errors.push('Geçersiz şifreli Aegis Vault dosyası.');
        return result;
      }

      let plaintext: string;

      if (json.algorithm !== 'AES-256-GCM' || !json.authTag) {
        result.errors.push(
          'Eski veya guvensiz sifreleme formati desteklenmiyor.',
        );
        return result;
      }

      plaintext = await SecurityModule.decryptAES256GCM(
        json.data,
        password,
        json.salt,
        json.iv,
        json.authTag,
        {
          kdf: json.kdf,
          iterations: json.iterations,
          memory: json.memory,
          parallelism: json.parallelism,
          hashLength: json.hashLength,
        },
      );

      const parsedPlaintext = JSON.parse(plaintext);
      const items = Array.isArray(parsedPlaintext)
        ? parsedPlaintext
        : parsedPlaintext?.items || [];
      result.total = items.length;
      for (const item of items) {
        try {
          await SecurityModule.addItem(item);
          result.imported++;
        } catch (e: any) {
          result.skipped++;
          result.errors.push(`"${item.title}": ${e?.message || 'Error'}`);
        }
      }

      if (Array.isArray(parsedPlaintext?.sharedSpaces)) {
        for (const space of parsedPlaintext.sharedSpaces) {
          await SecurityModule.saveSharedVaultSpace(space);
        }
      }

      await SecurityModule.logSecurityEvent(
        'backup_import_encrypted',
        'success',
        {
          total: result.total,
          imported: result.imported,
          skipped: result.skipped,
        },
      );
    } catch (e: any) {
      result.errors.push(
        `Şifre çözme hatası: ${
          e?.message || 'Geçersiz şifre veya bozuk dosya'
        }`,
      );
      await SecurityModule.logSecurityEvent(
        'backup_import_encrypted',
        'failed',
        {
          reason: e?.message || 'decrypt_failed',
        },
      );
    }
    return result;
  }

  // ═══════════════════════════════════════════════════════════════
  // EXPORT LOGIC
  // ═══════════════════════════════════════════════════════════════

  static async exportToCSV(): Promise<string> {
    const items = await SecurityModule.getItems();
    const header = 'title,username,password,url,notes,category,favorite,data';
    const rows = items.map(item =>
      [
        item.title,
        item.username,
        item.password,
        item.url,
        item.notes,
        item.category,
        item.favorite,
        item.data,
      ]
        .map(v => escapeCSV(String(v ?? '')))
        .join(','),
    );
    const csv = [header, ...rows].join('\n');
    const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    const path = await writeExportFile(`aegis_vault_export_${ts}.csv`, csv);
    await SecurityModule.logSecurityEvent('backup_export_csv', 'success', {
      itemCount: items.length,
      output: path.split('/').pop(),
    });
    return path;
  }

  static async exportToJSON(): Promise<string> {
    const items = await SecurityModule.getItems();
    const sharedSpaces = await SecurityModule.getSharedVaultSpaces();
    const exportData = {
      version: '1.0.0',
      app: 'Aegis Vault Android',
      exported_at: new Date().toISOString(),
      count: items.length,
      sharedSpaces,
      items: items.map(({ id: _id, ...rest }) => rest),
    };
    const json = JSON.stringify(exportData, null, 2);
    const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    const path = await writeExportFile(`aegis_vault_export_${ts}.json`, json);
    await SecurityModule.logSecurityEvent('backup_export_json', 'success', {
      itemCount: items.length,
      output: path.split('/').pop(),
    });
    return path;
  }

  static async exportEncrypted(password: string): Promise<string> {
    const items = await SecurityModule.getItems();
    const sharedSpaces = await SecurityModule.getSharedVaultSpaces();
    const plainItems = items.map(({ id: _id, ...rest }) => rest);
    const plaintext = JSON.stringify({
      items: plainItems,
      sharedSpaces,
    });

    // AES-256-GCM encryption (authenticated encryption + Argon2id KDF)
    const {
      salt,
      iv,
      authTag,
      ciphertext,
      kdf,
      memory,
      iterations,
      parallelism,
      hashLength,
    } = await SecurityModule.encryptAES256GCM(plaintext, password);
    debugLog('[AEGIS-EXPORT] Encrypted export prepared with Argon2id');

    const exportData = {
      version: '2.0.0',
      app: 'Aegis Vault Android',
      encrypted: true,
      algorithm: 'AES-256-GCM',
      kdf,
      memory,
      iterations,
      parallelism,
      hashLength,
      salt,
      iv,
      authTag,
      exported_at: new Date().toISOString(),
      count: items.length,
      data: ciphertext,
    };
    const ts = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    const jsonStr = JSON.stringify(exportData, null, 2);
    const path = await writeExportFile(
      `aegis_vault_encrypted_${ts}.aegis`,
      jsonStr,
    );

    await SecurityModule.logSecurityEvent(
      'backup_export_encrypted',
      'success',
      {
        itemCount: items.length,
        kdf,
        output: path ? path.split('/').pop() : 'unknown',
      },
    );

    return path;
  }

  // ── Auto-detect source from file ───────────────────────────
  static detectSource(filename: string, content: string): ImportSource {
    const lower = filename.toLowerCase();
    const ext = lower.split('.').pop() || '';

    // Check content signatures
    try {
      if (ext === 'json') {
        const json = JSON.parse(content.substring(0, 5000));
        if (json.db?.entries && (json.header || json.version))
          return 'aegis_auth';
        if (json.app === 'Aegis Vault Android' || json.encrypted)
          return 'aegis_vault';
        if (json.items && json.folders !== undefined) return 'bitwarden';
        if (json.AUTHENTIFIANT || json.credentials) return 'dashlane';
        if (json.items?.[0]?.fields) return 'enpass';
        return 'generic_json';
      }
    } catch {}

    if (ext === 'aegis') return 'aegis_vault';
    if (ext === '1pux' || ext === '1pif') return '1password';
    if (ext === 'xml') return 'keepass';

    // CSV header detection
    if (ext === 'csv') {
      const firstLine = content.split('\n')[0].toLowerCase();
      if (
        firstLine.includes('login_uri') ||
        firstLine.includes('login_username')
      )
        return 'bitwarden';
      if (firstLine.includes('grouping') && firstLine.includes('fav'))
        return 'lastpass';
      if (
        firstLine.includes('origin_url') ||
        (firstLine.includes('name') &&
          firstLine.includes('url') &&
          firstLine.includes('password') &&
          !firstLine.includes('notes'))
      )
        return 'chrome';
      if (
        firstLine.includes('httprealm') ||
        firstLine.includes('formactionorigin')
      )
        return 'firefox';
      if (firstLine.includes('cardholder') || firstLine.includes('login_name'))
        return 'dashlane';
      // KeePass: "Account","Login Name","Password","Web Site","Comments"
      if (firstLine.includes('account') && firstLine.includes('web site'))
        return 'keepass';
      return 'generic_csv';
    }

    return 'generic_csv';
  }
}

// @ts-nocheck
import RNFS from 'react-native-fs';
import { NativeModules, Platform } from 'react-native';
import { BackupModule } from './BackupModule';
import { SecurityModule } from './SecurityModule';

const { CloudSyncSecure } = NativeModules;

interface CloudSyncSecureBridge {
  uploadFile: (
    apiUrl: string,
    filePath: string,
    authHeader: string,
    certificatePin: string,
  ) => Promise<number>;
  downloadFile: (
    apiUrl: string,
    filePath: string,
    authHeader: string,
    certificatePin: string,
  ) => Promise<number>;
}

/**
 * Encrypted Cloud Sync (Optional)
 * Uploads/Downloads the AES-256-GCM encrypted `.aegis` vault backup
 * to a standard WebDAV or custom HTTP endpoint.
 */
export class CloudSyncModule {
  private static assertHttpsUrl(rawUrl: string): string {
    let parsed: URL;
    try {
      parsed = new URL((rawUrl || '').trim());
    } catch {
      throw new Error('Invalid Cloud Sync URL');
    }
    if (parsed.protocol !== 'https:') {
      throw new Error('Cloud Sync requires HTTPS URLs only');
    }
    return parsed.toString();
  }

  private static assertCertificatePin(rawPin: string): string {
    const pin = (rawPin || '').trim();
    if (!pin) throw new Error('Certificate pin is required');

    const normalized = pin.startsWith('sha256/') ? pin : `sha256/${pin}`;
    const isValid = /^sha256\/[A-Za-z0-9+/]{43}=$/.test(normalized);
    if (!isValid) {
      throw new Error('Invalid certificate pin format. Use sha256/<base64>');
    }

    return normalized;
  }

  private static getSecureBridge(): CloudSyncSecureBridge {
    if (Platform.OS !== 'android' || !CloudSyncSecure) {
      throw new Error(
        'CloudSyncSecure native module is unavailable on this device',
      );
    }

    return CloudSyncSecure as CloudSyncSecureBridge;
  }

  static getAuthHeader(token: string, type: 'Bearer' | 'Basic'): string {
    return `${type} ${token}`;
  }

  /**
   * Upload encrypted vault to cloud endpoint via PUT request (standard WebDAV)
   * We orchestrate: Export AES Vault -> Upload -> Delete temporary local backup
   */
  static async syncToCloud(
    apiUrl: string,
    token: string,
    authType: 'Bearer' | 'Basic',
    password: string,
    certificatePin: string,
  ): Promise<boolean> {
    const safeUrl = this.assertHttpsUrl(apiUrl);
    const safePin = this.assertCertificatePin(certificatePin);
    const bridge = this.getSecureBridge();

    // 1. Generate encrypted backup in a temporary file
    const tempExportPath = await BackupModule.exportEncrypted(password);

    try {
      // 2. Upload using RNFS to support large binary payloads without memory bloat
      const statusCode = await bridge.uploadFile(
        safeUrl,
        tempExportPath,
        this.getAuthHeader(token, authType),
        safePin,
      );

      if (statusCode >= 200 && statusCode < 300) {
        console.log('[CloudSync] Successfully uploaded encrypted vault');
        await SecurityModule.logSecurityEvent('cloud_sync_upload', 'success', {
          statusCode,
          endpoint: safeUrl,
        });
        return true;
      } else {
        await SecurityModule.logSecurityEvent('cloud_sync_upload', 'failed', {
          statusCode,
          endpoint: safeUrl,
        });
        throw new Error(
          `Cloud server rejected upload: ${statusCode} HTTP error`,
        );
      }
    } catch (e) {
      await SecurityModule.logSecurityEvent('cloud_sync_upload', 'failed', {
        endpoint: safeUrl,
        reason: e instanceof Error ? e.message : String(e),
      });
      throw e;
    } finally {
      // 3. Clean up the local temporary backup to preserve zero-footprint pledge
      await RNFS.unlink(tempExportPath).catch(() => {});
    }
  }

  /**
   * Download encrypted vault from cloud endpoint and import it.
   */
  static async syncFromCloud(
    apiUrl: string,
    token: string,
    authType: 'Bearer' | 'Basic',
    password: string,
    certificatePin: string,
  ): Promise<any> {
    const safeUrl = this.assertHttpsUrl(apiUrl);
    const safePin = this.assertCertificatePin(certificatePin);
    const bridge = this.getSecureBridge();

    const tempImportPath = `${RNFS.DocumentDirectoryPath}/aegis_cloud_import_temp.aegis`;

    try {
      // 1. Download file via streaming
      const statusCode = await bridge.downloadFile(
        safeUrl,
        tempImportPath,
        this.getAuthHeader(token, authType),
        safePin,
      );

      if (statusCode >= 200 && statusCode < 300) {
        // 2. Import downloaded AES-256-GCM file
        const importResult = await BackupModule.importEncryptedAegis(
          tempImportPath,
          password,
        );
        await SecurityModule.logSecurityEvent(
          'cloud_sync_download',
          'success',
          {
            statusCode,
            endpoint: safeUrl,
            imported: importResult?.imported || 0,
            skipped: importResult?.skipped || 0,
          },
        );
        console.log(
          '[CloudSync] Sync down completed:',
          importResult.imported,
          'imported',
        );
        return importResult;
      } else {
        await SecurityModule.logSecurityEvent('cloud_sync_download', 'failed', {
          statusCode,
          endpoint: safeUrl,
        });
        throw new Error(`Failed to download from cloud: ${statusCode}`);
      }
    } catch (e) {
      await SecurityModule.logSecurityEvent('cloud_sync_download', 'failed', {
        endpoint: safeUrl,
        reason: e instanceof Error ? e.message : String(e),
      });
      throw e;
    } finally {
      // 3. Clean up generic downloaded file
      await RNFS.unlink(tempImportPath).catch(() => {});
    }
  }
}

