  { id: 'card', label: t('vault.categories.card'), icon: '💳' },
  { id: 'identity', label: t('vault.categories.identity'), icon: '🪪' },
  { id: 'note', label: t('vault.categories.note'), icon: '📝' },
  { id: 'wifi', label: t('vault.categories.wifi'), icon: '📶' },
];
type Tab = 'vault' | 'generator' | 'settings';

// ═══════════════════════════════════════════════════
export const Dashboard = () => {
  const { t, i18n } = useTranslation();
  const insets = useSafeAreaInsets();
  const [unlocked, setUnlocked] = useState(false);
  const [authStatus, setAuthStatus] = useState(t('lock_screen.prompt'));
  const [tab, setTab] = useState<Tab>('vault');
  const [items, setItems] = useState<VaultItem[]>([]);
  const [search, setSearch] = useState('');
  const [selCat, setSelCat] = useState('all');
  const [settings, setSettings] = useState<VaultSettings>({
    autoLockSeconds: 60,
    biometricEnabled: true,
    clipboardClearSeconds: 30,
    passwordLength: 20,
    darkMode: false,
  });
  const palette = settings.darkMode ? CD : C;
  const [showAdd, setShowAdd] = useState(false);
  const [showDetail, setShowDetail] = useState(false);
  const [editItem, setEditItem] = useState<VaultItem | null>(null);
  const [count, setCount] = useState(0);
  const [showBackup, setShowBackup] = useState(false);
  const [showCloud, setShowCloud] = useState(false);
  const [showSecurityReport, setShowSecurityReport] = useState(false);
  const [showSharedVaults, setShowSharedVaults] = useState(false);
  const [showDonation, setShowDonation] = useState(false);
  const [showTrash, setShowTrash] = useState(false);
  const [sharedSpaces, setSharedSpaces] = useState<SharedVaultSpace[]>([]);
  const [legalType, setLegalType] = useState<'terms' | 'privacy' | null>(null);
  const [integrity, setIntegrity] = useState<IntegritySignals | null>(null);
  const [integrityLoading, setIntegrityLoading] = useState(true);
  const glow = useRef(new Animated.Value(0.4)).current;

  const [_isPickingFile, _setIsPickingFile] = useState(false);
  const backgroundTimeRef = useRef<number | null>(null);
  const settingsRef = useRef(settings);
  const unlockedRef = useRef(unlocked);

  // Keep refs in sync with state for use in AppState listener
  useEffect(() => {
    settingsRef.current = settings;
  }, [settings]);
  useEffect(() => {
    unlockedRef.current = unlocked;
  }, [unlocked]);

  useEffect(() => {
    Animated.loop(
      Animated.sequence([
        Animated.timing(glow, {
          toValue: 1,
          duration: 2000,
          useNativeDriver: true,
        }),
        Animated.timing(glow, {
          toValue: 0.4,
          duration: 2000,
          useNativeDriver: true,
        }),
      ]),
    ).start();

    const sub = AppState.addEventListener(
      'change',
      (nextState: AppStateStatus) => {
        // Skip if picking a file (file picker briefly backgrounds the app)
        if (SecurityModule.isPickingFileFlag) return;

        if (!unlockedRef.current) return; // already locked, no action needed

        if (nextState === 'background' || nextState === 'inactive') {
          // App going to background → record timestamp
          backgroundTimeRef.current = Date.now();

          // If auto-lock is disabled (0), don't lock at all on background
          // The vault stays open until manual lock
          if (settingsRef.current.autoLockSeconds === 0) return;

          // Start a background timeout: if the user doesn't return within the
          // configured duration, lock the vault. This handles cases where
          // setTimeout continues to run briefly after backgrounding.
          SecurityModule.startAutoLockTimer(
            settingsRef.current.autoLockSeconds,
            () => {
              SecurityModule.lockVault();
              setUnlocked(false);
              setAuthStatus(t('lock_screen.auto_locked'));
            },
          );
        } else if (nextState === 'active') {
          // App coming back to foreground → check elapsed time
          if (backgroundTimeRef.current !== null) {
            const elapsedSeconds =
              (Date.now() - backgroundTimeRef.current) / 1000;
            backgroundTimeRef.current = null;

            const lockSeconds = settingsRef.current.autoLockSeconds;

            if (lockSeconds > 0 && elapsedSeconds >= lockSeconds) {
              // Elapsed time exceeded auto-lock duration → lock now
              SecurityModule.lockVault();
              setUnlocked(false);
              setAuthStatus(t('lock_screen.auto_locked'));
            } else {
              // Still within time limit → stay unlocked, reset foreground timer
              if (lockSeconds > 0) {
                SecurityModule.resetAutoLockTimer(lockSeconds, () => {
                  SecurityModule.lockVault();
                  setUnlocked(false);
                  setAuthStatus(t('lock_screen.auto_locked'));
                });
              }
            }
          }
        }
      },
    );
    return () => sub.remove();
  }, [glow, t]);

  const load = useCallback(async () => {
    setItems(await SecurityModule.getItems(search, selCat));
    setCount(await SecurityModule.getItemCount());
  }, [search, selCat]);
  const openItemById = useCallback(async (itemId: number) => {
    const allItems = await SecurityModule.getItems();
    const target = allItems.find(item => item.id === itemId);
    if (!target) {
      return;
    }
    setTab('vault');
    setEditItem(target);
    setShowDetail(true);
  }, []);
  const loadSettings = useCallback(
    async () => setSettings(await SecurityModule.getAllSettings()),
    [],
  );
  const loadSharedSpaces = useCallback(
    async () => setSharedSpaces(await SecurityModule.getSharedVaultSpaces()),
    [],
  );

  useEffect(() => {
    if (unlocked) {
      load();
      loadSettings();
      loadSharedSpaces();
    }
  }, [unlocked, load, loadSettings, loadSharedSpaces]);

  useEffect(() => {
    (async () => {
      setIntegrityLoading(true);
      const signals = await IntegrityModule.getIntegritySignals();
      setIntegrity(signals);
      setIntegrityLoading(false);
    })();
  }, []);

  const lock = () => {
    SecurityModule.lockVault();
    setUnlocked(false);
    setAuthStatus(t('lock_screen.locked'));
  };
  const autoLockCb = useCallback(() => {
    SecurityModule.lockVault();
    setUnlocked(false);
    setAuthStatus(t('lock_screen.auto_locked'));
  }, [t]);
  useEffect(() => {
    if (unlocked && settings.autoLockSeconds > 0)
      SecurityModule.startAutoLockTimer(settings.autoLockSeconds, autoLockCb);
    return () => SecurityModule.clearAutoLockTimer();
  }, [unlocked, settings.autoLockSeconds, autoLockCb]);
  const resetTimer = () => {
    if (unlocked && settings.autoLockSeconds > 0)
      SecurityModule.resetAutoLockTimer(settings.autoLockSeconds, autoLockCb);
  };

  const [lockoutRemaining, setLockoutRemaining] = useState(0);
  const [failCount, setFailCount] = useState(0);

  const auth = async () => {
    try {
      // Check brute force lockout
      const remaining = await SecurityModule.getRemainingLockout();
      if (remaining > 0) {
        setLockoutRemaining(remaining);
        setAuthStatus(t('lock_screen.locked_out', { seconds: remaining }));
        return;
      }

      const { available } = await rnBiometrics.isSensorAvailable();
      if (!available) {
        setAuthStatus(t('lock_screen.bio_not_found'));
        return;
      }
      setAuthStatus(t('lock_screen.verifying'));

      // Biometric gate + stable unlock secret derivation
      const unlockSecret = await SecurityModule.deriveKeyFromBiometric();

      if (!unlockSecret) {
        setAuthStatus(t('lock_screen.cancelled'));
        return;
      }

      if (await SecurityModule.unlockVault(unlockSecret)) {
        setUnlocked(true);
        setAuthStatus(t('lock_screen.unlocked'));
        setFailCount(0);
        setLockoutRemaining(0);
        // Automatic cleanup of old trash items (>30 days)
        SecurityModule.cleanupOldTrash();
      } else {
        const fails = await SecurityModule.getFailedAttempts();
        setFailCount(fails);
        const newRemaining = await SecurityModule.getRemainingLockout();
        setLockoutRemaining(newRemaining);
        if (newRemaining > 0) {
          setAuthStatus(
            t('lock_screen.failed_attempts', {
              count: fails,
              seconds: newRemaining,
            }),
          );
        } else {
          setAuthStatus(t('lock_screen.failed', { count: fails }));
        }
      }
    } catch {
      setAuthStatus(t('lock_screen.error'));
    }
  };

  // Lockout countdown timer
  useEffect(() => {
    if (lockoutRemaining <= 0) return;
    const interval = setInterval(() => {
      setLockoutRemaining(prev => {
        if (prev <= 1) {
          setAuthStatus(t('lock_screen.retry'));
          clearInterval(interval);
          return 0;
        }
        setAuthStatus(t('lock_screen.locked_out', { seconds: prev - 1 }));
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [lockoutRemaining, t]);

  // Check lockout on mount
  useEffect(() => {
    (async () => {
      // Sync native autofill state on startup: if app starts locked, ensure service is locked
      if (!unlockedRef.current) {
        AutofillService.setUnlocked(false);
        AutofillService.clearEntries();
      }

      const remaining = await SecurityModule.getRemainingLockout();
      const fails = await SecurityModule.getFailedAttempts();
      if (remaining > 0) {
        setLockoutRemaining(remaining);
        setFailCount(fails);
        setAuthStatus(t('lock_screen.locked_out', { seconds: remaining }));
      }
    })();
  }, [t]);

  // Lock screen
  if (!unlocked)
    return (
      <View style={[s.loginBox, { backgroundColor: palette.bg }]}>
        <Text style={{ fontSize: 52, marginBottom: 12 }}>🛡️</Text>
        <Text style={[s.title, { color: palette.navy }]}>
          {t('lock_screen.title')}
        </Text>
        <Text style={[s.subtitle, { color: palette.muted }]}>{authStatus}</Text>
        {lockoutRemaining > 0 && (
          <View
            style={{
              backgroundColor: 'rgba(239,68,68,0.08)',
              borderRadius: 14,
              padding: 14,
              marginBottom: 16,
            }}
          >
            <Text
              style={{
                color: '#ef4444',
                fontWeight: '700',
                fontSize: 13,
                textAlign: 'center',
              }}
            >
              {t('lock_screen.brute_force_active')}
            </Text>
            <Text
              style={{
                color: '#ef4444',
                fontSize: 12,
                textAlign: 'center',
                marginTop: 4,
              }}
            >
              {t('lock_screen.brute_force_desc', {
                fails: failCount,
                seconds: lockoutRemaining,
              })}
            </Text>
          </View>
        )}
        {!!integrity && integrity.riskLevel !== 'low' && (
          <View
            style={{
              backgroundColor:
                integrity.riskLevel === 'critical'
                  ? 'rgba(239,68,68,0.12)'
                  : integrity.riskLevel === 'high'
                  ? 'rgba(245,158,11,0.14)'
                  : 'rgba(234,179,8,0.12)',
              borderRadius: 14,
              padding: 14,
              marginBottom: 16,
              borderWidth: 1,
              borderColor:
                integrity.riskLevel === 'critical'
                  ? 'rgba(239,68,68,0.35)'
                  : integrity.riskLevel === 'high'
                  ? 'rgba(245,158,11,0.38)'
                  : 'rgba(234,179,8,0.35)',
            }}
          >
            <Text
              style={{
                color:
                  integrity.riskLevel === 'critical'
                    ? '#ef4444'
                    : integrity.riskLevel === 'high'
                    ? '#f59e0b'
                    : '#eab308',
                fontWeight: '700',
                fontSize: 13,
                textAlign: 'center',
              }}
            >
              {t('lock_screen.integrity_warning_title')}
            </Text>
            <Text
              style={{
                color:
                  integrity.riskLevel === 'critical'
                    ? '#ef4444'
                    : integrity.riskLevel === 'high'
                    ? '#f59e0b'
                    : '#eab308',
                fontSize: 12,
                textAlign: 'center',
                marginTop: 4,
              }}
            >
              {t('lock_screen.integrity_warning_desc', {
                level: t(`settings.integrity.level_${integrity.riskLevel}`),
                score: integrity.score,
              })}
            </Text>
          </View>
        )}
        <TouchableOpacity
          style={[
            s.bioBtn,
            {
              backgroundColor: palette.card,
              borderColor: palette.cardBorder,
            },
            lockoutRemaining > 0 && { opacity: 0.4 },
          ]}
          onPress={auth}
          activeOpacity={0.75}
          disabled={lockoutRemaining > 0}
        >
          <Animated.View
            style={[
              s.glow,
              {
                opacity: lockoutRemaining > 0 ? 0 : glow,
                backgroundColor: settings.darkMode
                  ? 'rgba(34,211,238,0.12)'
                  : 'rgba(114,136,111,0.1)',
              },
            ]}
          />
          <Text style={[s.bioBtnText, { color: palette.navy }]}>
            {t('lock_screen.bio_btn')}
          </Text>
        </TouchableOpacity>

        <View style={{ flexDirection: 'row', gap: 12, marginTop: 40 }}>
          <TouchableOpacity
            onPress={() => switchLanguage('tr')}
            style={{
              paddingHorizontal: 16,
              paddingVertical: 8,
              backgroundColor:
                i18n.language === 'tr' ? palette.sage : palette.card,
              borderRadius: 20,
              borderWidth: 1,
              borderColor: palette.cardBorder,
            }}
          >
            <Text
              style={{
                color: i18n.language === 'tr' ? '#fff' : palette.navy,
                fontWeight: '600',
              }}
            >
              🇹🇷 Türkçe
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => switchLanguage('en')}
            style={{
              paddingHorizontal: 16,
              paddingVertical: 8,
              backgroundColor:
                i18n.language === 'en' ? palette.sage : palette.card,
              borderRadius: 20,
              borderWidth: 1,
              borderColor: palette.cardBorder,
            }}
          >
            <Text
              style={{
                color: i18n.language === 'en' ? '#fff' : palette.navy,
                fontWeight: '600',
              }}
            >
              🇬🇧 English
            </Text>
          </TouchableOpacity>
        </View>

        <Text style={[s.info, { marginTop: 20, color: palette.navy }]}>
          AES-256-GCM • Android Keystore • Argon2id
        </Text>

        <View
          style={{
            flexDirection: 'row',
            flexWrap: 'wrap',
            justifyContent: 'center',
            marginTop: 16,
            paddingHorizontal: 20,
          }}
        >
          <Text style={{ fontSize: 11, color: palette.muted, lineHeight: 18 }}>
            {t('legal.disclaimer').split('{{terms}}')[0]}
          </Text>
          <TouchableOpacity
            onPress={() => setLegalType('terms')}
            activeOpacity={0.6}
          >
            <Text
              style={{
                fontSize: 11,
                color: palette.muted,
                fontWeight: '700',
                textDecorationLine: 'underline',
                lineHeight: 18,
              }}
            >
              {t('legal.terms')}
            </Text>
          </TouchableOpacity>
          <Text style={{ fontSize: 11, color: palette.muted, lineHeight: 18 }}>
            {
              t('legal.disclaimer')
                .split('{{terms}}')[1]
                .split('{{privacy}}')[0]
            }
          </Text>
          <TouchableOpacity
            onPress={() => setLegalType('privacy')}
            activeOpacity={0.6}
          >
            <Text
              style={{
                fontSize: 11,
                color: palette.muted,
                fontWeight: '700',
                textDecorationLine: 'underline',
                lineHeight: 18,
              }}
            >
              {t('legal.privacy')}
            </Text>
          </TouchableOpacity>
          <Text style={{ fontSize: 11, color: palette.muted, lineHeight: 18 }}>
            {t('legal.disclaimer').split('{{privacy}}')[1] || ''}
          </Text>
        </View>

        <LegalModal
          visible={!!legalType}
          type={legalType}
          onClose={() => setLegalType(null)}
        />
      </View>
    );

  return (
    <View
      style={[s.root, { backgroundColor: palette.bg }]}
      onTouchStart={resetTimer}
    >
      {tab === 'vault' && (
        <VaultView
          theme={palette}
          items={items}
          search={search}
          setSearch={setSearch}
          selCat={selCat}
          setSelCat={setSelCat}
          onRefresh={load}
          count={count}
          onAdd={() => {
            setEditItem(null);
            setShowAdd(true);
          }}
          onDetail={(i: VaultItem) => {
            setEditItem(i);
            setShowDetail(true);
          }}
          onLock={lock}
          onDonation={() => setShowDonation(true)}
          onTrash={() => setShowTrash(true)}
          insets={insets}
        />
      )}
      {tab === 'generator' && (
        <GenView theme={palette} settings={settings} insets={insets} />
      )}
      {tab === 'settings' && (
        <SettView
          theme={palette}
          integrity={integrity}
          integrityLoading={integrityLoading}
          settings={settings}
          setSettings={setSettings}
          onLock={lock}
          onBackup={() => setShowBackup(true)}
          onCloud={() => setShowCloud(true)}
          onSecurityReport={() => setShowSecurityReport(true)}
          onSharedVaults={() => setShowSharedVaults(true)}
          openLegal={(type: any) => setLegalType(type)}
          onDonation={() => setShowDonation(true)}
          onTrash={() => setShowTrash(true)}
          insets={insets}
          onRefresh={load}
        />
      )}
      {showSecurityReport && (
        <SecurityReportModal
          visible={showSecurityReport}
          onClose={() => setShowSecurityReport(false)}
          theme={palette}
          onOpenItem={openItemById}
        />
      )}

      <View
        style={[
          s.nav,
          {
            paddingBottom: Math.max(20, insets.bottom + 10),
            backgroundColor: palette.card,
            borderTopColor: palette.divider,
          },
        ]}
      >
        {(
          [
            ['vault', t('nav.vault'), '🔒'],
            ['generator', t('nav.generator'), '⚡'],
            ['settings', t('nav.settings'), '⚙️'],
          ] as const
        ).map(([id, lbl, ic]) => (
          <TouchableOpacity
            key={id}
            style={s.navItem}
            onPress={() => setTab(id as Tab)}
            activeOpacity={0.6}
          >
            <Text style={[s.navIc, tab === id && s.navAct]}>{ic}</Text>
            <Text
              style={[
                s.navLbl,
                { color: palette.muted },
                tab === id && s.navLblAct,
                tab === id && { color: palette.sage },
              ]}
            >
              {lbl}
            </Text>
          </TouchableOpacity>
        ))}
      </View>

      <AddModal
        visible={showAdd}
        item={editItem}
        onClose={() => setShowAdd(false)}
        settings={settings}
        theme={palette}
        sharedSpaces={sharedSpaces}
        onSave={async (item: any, pending: any[]) => {
          let id = editItem?.id ?? null;
          if (id) await SecurityModule.updateItem(id, item);
          else id = await SecurityModule.addItem(item);
          if (id && pending.length) {
            for (const f of pending) {
              if (f.base64) {
                // Use pre-cached base64 data (from pending files)
                await SecurityModule.addAttachmentFromBase64(
                  id,
                  f.name,
                  f.type,
                  f.base64,
                  f.size,
                );
              } else {
                // Fallback: try reading from URI directly
                await SecurityModule.addAttachment(id, f.name, f.type, f.uri);
              }
            }
          }
          setShowAdd(false);
          load();
          loadSharedSpaces();
        }}
      />

      <DetailModal
          visible={showDetail}
          item={editItem}
          theme={palette}
          settings={settings}
          sharedSpaces={sharedSpaces}
          onRefresh={load}
          onClose={() => setShowDetail(false)}
        onEdit={() => {
          setShowDetail(false);
          setShowAdd(true);
        }}
        onDelete={async () => {
          if (editItem?.id) {
            await SecurityModule.deleteItem(editItem.id);
            setShowDetail(false);
            load();
          }
        }}
        onFav={async () => {
          if (editItem?.id) {
            await SecurityModule.toggleFavorite(editItem.id, editItem.favorite);
            setShowDetail(false);
            load();
          }
        }}
        clipClear={settings.clipboardClearSeconds}
      />

      <SharedVaultsModal
        visible={showSharedVaults}
        onClose={() => setShowSharedVaults(false)}
        onUpdated={() => {
          load();
          loadSharedSpaces();
        }}
        theme={palette}
      />
      {showBackup && (
        <BackupModal
          visible={showBackup}
          onClose={() => setShowBackup(false)}
          onImportDone={load}
          theme={palette}
        />
      )}
      {showCloud && (
        <CloudSyncModal
          visible={showCloud}
          onClose={() => setShowCloud(false)}
          onRefresh={load}
          theme={palette}
        />
      )}
      {showDonation && (
        <DonationModal
          visible={showDonation}
          onClose={() => setShowDonation(false)}
          theme={palette}
        />
      )}
      {showTrash && (
        <TrashModal
          visible={showTrash}
          onClose={() => setShowTrash(false)}
          onRefreshParent={load}
          theme={palette}
        />
      )}
      {unlocked && (
        <LegalModal
          visible={!!legalType}
          type={legalType}
          onClose={() => setLegalType(null)}
          theme={palette}
        />
      )}
    </View>
  );
};

// ── Vault ──
const VaultView = ({
  theme,
  items,
  search,
  setSearch,
  selCat,
  setSelCat,
  onRefresh,
  count,
  onAdd,
  onDetail,
  onLock,
  onDonation,
  onTrash,
  insets,
}: any) => {
  const { t } = useTranslation();
  return (
    <View style={{ flex: 1 }}>
      <ScrollView
        style={{ flex: 1 }}
        contentContainerStyle={{
          padding: 20,
          paddingBottom: 100 + (insets?.bottom || 0),
        }}
      >
        <View style={s.hdr}>
          <View>
            <Text style={[s.hdrT, { color: theme.navy }]}>
              {t('lock_screen.title')}
            </Text>
            <Text style={[s.hdrS, { color: theme.sage }]}>
              {count} {t('vault.items_count')} • AES-256
            </Text>
          </View>
          <View style={{ flexDirection: 'row', gap: 10 }}>
            <TouchableOpacity
              onPress={onTrash}
              style={[
                s.lockIc,
                { backgroundColor: theme.card, borderColor: theme.cardBorder },
              ]}
            >
              <Text style={{ fontSize: 20 }}>🗑️</Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={onDonation}
              style={[
                s.lockIc,
                { backgroundColor: theme.card, borderColor: theme.cardBorder },
              ]}
            >
              <Text style={{ fontSize: 20 }}>❤️</Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={onLock}
              style={[
                s.lockIc,
                { backgroundColor: theme.card, borderColor: theme.cardBorder },
              ]}
            >
              <Text style={{ fontSize: 20 }}>🔒</Text>
            </TouchableOpacity>
          </View>
        </View>
        <View
          style={[
            s.srch,
            { backgroundColor: theme.inputBg, borderColor: theme.cardBorder },
          ]}
        >
          <Text style={{ fontSize: 16, marginRight: 8 }}>🔍</Text>
          <TextInput
            style={s.srchIn}
            placeholder={t('vault.search')}
            placeholderTextColor={theme.muted}
            value={search}
            onChangeText={setSearch}
            returnKeyType="search"
            onSubmitEditing={onRefresh}
          />
          {search ? (
            <TouchableOpacity
              onPress={() => {
                setSearch('');
              }}
            >
              <Text style={{ fontSize: 16, color: theme.muted, padding: 4 }}>
                ✕
              </Text>
            </TouchableOpacity>
          ) : null}
        </View>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          style={{ marginBottom: 16, flexGrow: 0 }}
        >
          {getCats(t).map(c => (
            <TouchableOpacity
              key={c.id}
              style={[
                s.cat,
                { backgroundColor: theme.card, borderColor: theme.cardBorder },
                selCat === c.id && {
                  backgroundColor: theme.sage,
                  borderColor: theme.sage,
                },
              ]}
              onPress={() => setSelCat(c.id)}
              activeOpacity={0.7}
            >
              <Text style={{ fontSize: 14, marginRight: 5 }}>{c.icon}</Text>
              <Text
                style={[
                  s.catLbl,
                  { color: theme.navy },
                  selCat === c.id && { color: '#fff' },
                ]}
              >
                {c.label}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
        {items.length === 0 ? (
          <View style={{ alignItems: 'center', paddingVertical: 60 }}>
            <Text style={{ fontSize: 48, marginBottom: 16 }}>🔐</Text>
            <Text
              style={{
                fontSize: 18,
                fontWeight: '700',
                color: theme.navy,
                marginBottom: 6,
              }}
            >
              {t('vault.search')}
            </Text>
          </View>
        ) : (
          items.map((i: VaultItem) => (
            <TouchableOpacity
              key={i.id}
              style={[
                s.item,
                { backgroundColor: theme.card, borderColor: theme.cardBorder },
              ]}
              onPress={() => onDetail(i)}
              activeOpacity={0.7}
            >
              <View
                style={[s.avatar, { backgroundColor: getCatColor(i.category) }]}
              >
                <Text style={{ fontSize: 20 }}>{getCatIcon(i.category)}</Text>
              </View>
              <View style={{ flex: 1 }}>
                <View
                  style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}
                >
                  <Text
                    style={[s.itemT, { color: theme.navy }]}
                    numberOfLines={1}
                  >
                    {i.title}
                  </Text>
                  {i.favorite === 1 && <Text style={{ fontSize: 12 }}>⭐</Text>}
                  {SecurityModule.parseSharedAssignment(i) ? (
                    <Text
                      style={{ fontSize: 11, color: theme.sage, fontWeight: '700' }}
                    >
                      {t('shared.list_badge')}
                    </Text>
                  ) : null}
                </View>
                <Text
                  style={[s.itemS, { color: theme.muted }]}
                  numberOfLines={1}
                >
                  {i.username ||
                    i.url ||
                    getCats(t).find(x => x.id === i.category)?.label}
                </Text>
              </View>
              <Text
                style={{ fontSize: 22, color: theme.muted, fontWeight: '300' }}
              >
                ›
              </Text>
            </TouchableOpacity>
          ))
        )}
      </ScrollView>
      <TouchableOpacity
        style={[
          s.fab,
          { bottom: 90 + (insets?.bottom || 0), backgroundColor: theme.sage },
        ]}
        onPress={onAdd}
        activeOpacity={0.8}
      >
        <Text style={s.fabT}>+</Text>
      </TouchableOpacity>
    </View>
  );
};

// ── Generator ──
const GenView = ({ theme, settings, insets }: any) => {
  const { t } = useTranslation();
  const [pw, setPw] = useState('');
  const [len, setLen] = useState(settings.passwordLength);
  const [up, setUp] = useState(true);
  const [lo, setLo] = useState(true);
  const [num, setNum] = useState(true);
  const [sym, setSym] = useState(true);
  const [copied, setCopied] = useState(false);
  const gen = useCallback(() => {
    setPw(
      SecurityModule.generatePassword(len, {
        uppercase: up,
        lowercase: lo,
        numbers: num,
        symbols: sym,
      }),
    );
    setCopied(false);
  }, [len, up, lo, num, sym]);
  useEffect(() => {
    gen();
  }, [gen]);
  const str = SecurityModule.getPasswordStrength(pw);
  return (
    <ScrollView
      style={{ flex: 1 }}
      contentContainerStyle={{
        padding: 20,
        paddingBottom: 100 + (insets?.bottom || 0),
      }}
    >
      <Text style={[s.hdrT, { color: theme.navy }]}>
        {t('generator.title')}
      </Text>
      <Text style={[s.hdrS, { color: theme.sage }]}>
        {t('generator.subtitle')}
      </Text>
      <View
        style={[
          s.genBox,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
      >
        <Text style={[s.genPw, { color: theme.navy }]} selectable>
          {pw}
        </Text>
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            marginTop: 16,
            gap: 10,
          }}
        >
          <View style={[s.bar, { flex: 1 }]}>
            <View
              style={[
                s.barFill,
                {
                  width: `${(str.score / 7) * 100}%`,
                  backgroundColor: str.color,
                },
              ]}
            />
          </View>
          <Text style={{ fontSize: 12, fontWeight: '700', color: str.color }}>
            {t(`generator.strength.${str.score > 3 ? 'strong' : 'weak'}`)}
          </Text>
        </View>
      </View>
      <View style={{ flexDirection: 'row', gap: 10, marginBottom: 20 }}>
        <TouchableOpacity
          style={[s.genBtn, { backgroundColor: theme.sage }]}
          onPress={gen}
          activeOpacity={0.7}
        >
          <Text style={{ color: '#fff', fontWeight: '700' }}>
            🔄 {t('generator.generate')}
          </Text>
        </TouchableOpacity>
        <TouchableOpacity
          style={[
            s.genBtn,
            copied
              ? { backgroundColor: 'rgba(34,197,94,0.12)' }
              : {
                  backgroundColor: theme.card,
                  borderWidth: 1,
                  borderColor: theme.cardBorder,
                },
          ]}
          onPress={() => {
            Clipboard.setString(pw);
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
            if (settings.clipboardClearSeconds > 0) {
              setTimeout(
                () => Clipboard.setString(''),
                settings.clipboardClearSeconds * 1000,
              );
            }
          }}
          activeOpacity={0.7}
        >
          <Text
            style={{
              color: copied ? theme.green : theme.navy,
              fontWeight: '700',
            }}
          >
            {copied ? `✓ ${t('fields.copied')}` : `📋 ${t('generator.copy')}`}
          </Text>
        </TouchableOpacity>
      </View>
      <View
        style={[
          s.optBox,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
      >
        <Text style={[s.sLbl, { color: theme.navy }]}>
          {t('generator.length')}: {len}
        </Text>
        <View style={s.sliderR}>
          <TouchableOpacity
            onPress={() => setLen(Math.max(6, len - 1))}
            style={[s.sliderB, { backgroundColor: theme.sageLight }]}
          >
            <Text style={[s.sliderBT, { color: theme.sage }]}>−</Text>
          </TouchableOpacity>
          <View style={[s.sliderTr, { backgroundColor: theme.divider }]}>
            <View
              style={[
                s.sliderFl,
                {
                  width: `${((len - 6) / 58) * 100}%`,
                  backgroundColor: theme.sage,
                },
              ]}
            />
          </View>
          <TouchableOpacity
            onPress={() => setLen(Math.min(64, len + 1))}
            style={[s.sliderB, { backgroundColor: theme.sageLight }]}
          >
            <Text style={[s.sliderBT, { color: theme.sage }]}>+</Text>
          </TouchableOpacity>
        </View>
        <ToggleRow
          label={t('generator.uppercase')}
          value={up}
          onToggle={setUp}
          theme={theme}
        />
        <ToggleRow
          label={t('generator.lowercase')}
          value={lo}
          onToggle={setLo}
          theme={theme}
        />
        <ToggleRow
          label={t('generator.numbers')}
          value={num}
          onToggle={setNum}
          theme={theme}
        />
        <ToggleRow
          label={t('generator.symbols')}
          value={sym}
          onToggle={setSym}
          theme={theme}
        />
      </View>
    </ScrollView>
  );
};

// ── Settings ──
const SettView = ({
  theme,
  integrity,
  integrityLoading,
  settings: st2,
  setSettings,
  onLock,
  onBackup,
  onCloud,
  onSecurityReport,
  onSharedVaults,
  openLegal,
  onDonation,
  onTrash,
  insets,
  onRefresh,
}: any) => {
  const { t, i18n } = useTranslation();
  const [auditEvents, setAuditEvents] = useState<any[]>([]);
  const [auditLoading, setAuditLoading] = useState(false);
  const [crashReports, setCrashReports] = useState<CrashReport[]>([]);
  const [crashLoading, setCrashLoading] = useState(false);

  const boolLabel = (value: boolean) =>
    value ? t('settings.integrity.yes') : t('settings.integrity.no');
  const adbLabel = (value: boolean) =>
    value ? t('settings.integrity.on') : t('settings.integrity.off');

  const integrityReasonLabel = (reason: string) => {
    const key = `settings.integrity.reason_${reason}`;
    return i18n.exists(key) ? t(key) : reason;
  };

  const auditEventLabel = (eventType: string) => {
    const key = `settings.audit.events.${eventType}`;
    return i18n.exists(key) ? t(key) : eventType;
  };

  const auditStatusLabel = (status: string) => {
    const key = `settings.audit.status.${status}`;
    return i18n.exists(key) ? t(key) : status;
  };

  const loadAudit = async () => {
    setAuditLoading(true);
    const events = await SecurityModule.getAuditEvents(30);
    setAuditEvents(events);
    setAuditLoading(false);
  };

  const loadCrashReports = async () => {
    setCrashLoading(true);
    const reports = await AppMonitoring.getCrashReports(20);
    setCrashReports(reports);
    setCrashLoading(false);
  };

  useEffect(() => {
    loadAudit();
    loadCrashReports();
  }, []);

  const upd = async (k: string, v: any) => {
    const n = { ...st2, [k]: v };
    setSettings(n);
    await SecurityModule.setSetting(k, String(v));
    await loadAudit();
  };
  const ALO = [
    { l: t('settings.off'), v: 0 },
    { l: `30 ${t('settings.sec')}`, v: 30 },
    { l: `1 ${t('settings.min')}`, v: 60 },
    { l: `2 ${t('settings.min')}`, v: 120 },
    { l: `5 ${t('settings.min')}`, v: 300 },
    { l: `15 ${t('settings.min')}`, v: 900 },
  ];
  const CLO = [
    { l: t('settings.off'), v: 0 },
    { l: `15 ${t('settings.sec')}`, v: 15 },
    { l: `30 ${t('settings.sec')}`, v: 30 },
    { l: `1 ${t('settings.min')}`, v: 60 },
  ];
  return (
    <ScrollView
      style={{ flex: 1 }}
      contentContainerStyle={{
        padding: 20,
        paddingBottom: 100 + (insets?.bottom || 0),
      }}
    >
      <Text style={[s.hdrT, { color: theme.navy }]}>{t('settings.title')}</Text>
      <Text style={[s.hdrS, { color: theme.sage }]}>
        {t('settings.subtitle')}
      </Text>

      <Text style={[s.sec, { color: theme.navy }]}>🌐 Language / Dil</Text>
      <View
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
      >
        <View style={s.chipR}>
          <TouchableOpacity
            onPress={() => switchLanguage('tr')}
            style={[
              s.oChip,
              { backgroundColor: theme.inputBg, borderColor: theme.cardBorder },
              i18n.language === 'tr' && {
                backgroundColor: theme.sage,
                borderColor: theme.sage,
              },
            ]}
          >
            <Text
              style={[
                s.oChipT,
                { color: theme.navy },
                i18n.language === 'tr' && { color: '#fff' },
              ]}
            >
              🇹🇷 Türkçe
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => switchLanguage('en')}
            style={[
              s.oChip,
              { backgroundColor: theme.inputBg, borderColor: theme.cardBorder },
              i18n.language === 'en' && {
                backgroundColor: theme.sage,
                borderColor: theme.sage,
              },
            ]}
          >
            <Text
              style={[
                s.oChipT,
                { color: theme.navy },
                i18n.language === 'en' && { color: '#fff' },
              ]}
            >
              🇬🇧 English
            </Text>
          </TouchableOpacity>
        </View>
      </View>

      {/* ── Autofill Section ── */}
      <Text style={[s.sec, { color: theme.navy }]}>
        {t('settings.autofill.title')}
      </Text>
        <TouchableOpacity
          style={[
            s.sCard,
            { backgroundColor: theme.card, borderColor: theme.cardBorder },
          ]}
        onPress={() => AutofillService.openSettings()}
        activeOpacity={0.7}
      >
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <View style={{ flex: 1 }}>
            <Text
              style={{ fontSize: 14, fontWeight: '700', color: theme.navy }}
            >
              {t('settings.autofill.enable')}
            </Text>
            <Text
              style={{
                fontSize: 12,
                color: theme.muted,
                marginTop: 4,
                lineHeight: 17,
              }}
            >
              {t('settings.autofill.enable_desc')}
            </Text>
            <View
              style={{
                flexDirection: 'row',
                alignItems: 'center',
                marginTop: 8,
                gap: 6,
              }}
            >
              <View
                style={{
                  width: 8,
                  height: 8,
                  borderRadius: 4,
                  backgroundColor: theme.sage,
                }}
              />
              <Text
                style={{ fontSize: 11, color: theme.sage, fontWeight: '700' }}
              >
                {t('settings.autofill.support')}
              </Text>
            </View>
          </View>
          <Text
            style={{
              fontSize: 22,
              color: theme.muted,
              fontWeight: '300',
              marginLeft: 12,
            }}
          >
            ›
          </Text>
        </View>
      </TouchableOpacity>

      <View
        style={[
          s.sCard,
          {
            backgroundColor: theme.sageLight,
            borderColor: theme.sageMid,
          },
        ]}
      >
        <Text
          style={{
            fontSize: 12,
            fontWeight: '700',
            color: theme.navy,
            marginBottom: 8,
          }}
        >
          {t('settings.autofill.how_to')}
        </Text>
        <Text style={{ fontSize: 12, color: theme.navy, lineHeight: 19 }}>
          {t('settings.autofill.steps')}
        </Text>
      </View>

      <Text style={[s.sec, { color: theme.navy }]}>
        {t('settings.security')}
      </Text>
      <TouchableOpacity
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
        onPress={onSecurityReport}
        activeOpacity={0.7}
      >
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <View style={{ flex: 1 }}>
            <Text style={{ fontSize: 14, fontWeight: '700', color: theme.navy }}>
              {t('settings.security_report.title')}
            </Text>
            <Text
              style={{
                fontSize: 12,
                color: theme.muted,
                marginTop: 4,
                lineHeight: 17,
              }}
            >
              {t('settings.security_report.entrypoint_desc')}
            </Text>
          </View>
          <Text
            style={{
              fontSize: 22,
              color: theme.muted,
              fontWeight: '300',
              marginLeft: 12,
            }}
          >
            ›
          </Text>
        </View>
      </TouchableOpacity>
      <TouchableOpacity
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
        onPress={onSharedVaults}
        activeOpacity={0.7}
      >
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <View style={{ flex: 1 }}>
            <Text style={{ fontSize: 14, fontWeight: '700', color: theme.navy }}>
              {t('settings.shared_vaults.title')}
            </Text>
            <Text
              style={{
                fontSize: 12,
                color: theme.muted,
                marginTop: 4,
                lineHeight: 17,
              }}
            >
              {t('settings.shared_vaults.desc')}
            </Text>
          </View>
          <Text
            style={{
              fontSize: 22,
              color: theme.muted,
              fontWeight: '300',
              marginLeft: 12,
            }}
          >
            â€º
          </Text>
        </View>
      </TouchableOpacity>
      <View
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
      >
        <Text style={[s.sLbl, { color: theme.navy, marginBottom: 6 }]}>
          {t('settings.integrity.title')}
        </Text>
        <Text style={[s.sLbl, { color: theme.muted, marginBottom: 10 }]}>
          {integrityLoading
            ? t('settings.integrity.checking')
            : t('settings.integrity.status', {
                level: t(
                  `settings.integrity.level_${integrity?.riskLevel || 'low'}`,
                ),
                score: integrity?.score ?? 100,
              })}
        </Text>
        {!!integrity && !integrityLoading && (
          <>
            <Text style={[s.sLbl, { color: theme.navy }]}>
              • {t('settings.integrity.rooted')}: {boolLabel(integrity.rooted)}
            </Text>
            <Text style={[s.sLbl, { color: theme.navy }]}>
              • {t('settings.integrity.test_keys')}:{' '}
              {boolLabel(integrity.testKeys)}
            </Text>
            <Text style={[s.sLbl, { color: theme.navy }]}>
              • {t('settings.integrity.adb')}: {adbLabel(integrity.adbEnabled)}
            </Text>
            <Text style={[s.sLbl, { color: theme.navy }]}>
              • {t('settings.integrity.debug')}:{' '}
              {boolLabel(integrity.debugBuild)}
            </Text>
            <Text style={[s.sLbl, { color: theme.navy }]}>
              • {t('settings.integrity.emulator')}:{' '}
              {boolLabel(integrity.emulator)}
            </Text>
            {integrity.reasons?.length > 0 && (
              <Text style={[s.sLbl, { color: theme.muted, marginTop: 8 }]}>
                {t('settings.integrity.reasons')}:{' '}
                {integrity.reasons.map(integrityReasonLabel).join(', ')}
              </Text>
            )}
          </>
        )}
      </View>

      <Text style={[s.sec, { color: theme.navy }]}>
        {t('settings.audit.title')}
      </Text>
      <View
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
      >
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'space-between',
            marginBottom: 8,
          }}
        >
          <Text style={[s.sLbl, { color: theme.muted }]}>
            {auditLoading
              ? t('settings.audit.loading')
              : t('settings.audit.count', { count: auditEvents.length })}
          </Text>
          <View style={{ flexDirection: 'row', gap: 8 }}>
            <TouchableOpacity
              style={[
                s.oChip,
                {
                  backgroundColor: theme.inputBg,
                  borderColor: theme.cardBorder,
                },
              ]}
              onPress={loadAudit}
            >
              <Text style={[s.oChipT, { color: theme.navy }]}>↻</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[
                s.oChip,
                {
                  backgroundColor: theme.inputBg,
                  borderColor: theme.cardBorder,
                },
              ]}
              onPress={() =>
                Alert.alert(
                  t('settings.audit.clear_title'),
                  t('settings.audit.clear_confirm'),
                  [
                    { text: t('vault.cancel'), style: 'cancel' },
                    {
                      text: t('settings.audit.clear_btn'),
                      style: 'destructive',
                      onPress: async () => {
                        await SecurityModule.clearAuditEvents();
                        await loadAudit();
                      },
                    },
                  ],
                )
              }
            >
              <Text style={[s.oChipT, { color: theme.navy }]}>🗑️</Text>
            </TouchableOpacity>
          </View>
        </View>

        {auditEvents.length === 0 ? (
          <Text style={[s.sLbl, { color: theme.muted }]}>
            {t('settings.audit.empty')}
          </Text>
        ) : (
          auditEvents.slice(0, 12).map(ev => {
            let detailsText = '';
            try {
              const d = ev.details ? JSON.parse(ev.details) : {};
              detailsText = Object.entries(d)
                .slice(0, 2)
                .map(([k, v]) => `${k}:${String(v)}`)
                .join(' • ');
            } catch {
              detailsText = '';
            }

            const statusColor =
              ev.event_status === 'success'
                ? '#16a34a'
                : ev.event_status === 'failed'
                ? '#dc2626'
                : ev.event_status === 'blocked'
                ? '#d97706'
                : '#64748b';

            return (
              <View
                key={ev.id}
                style={{
                  borderTopWidth: 1,
                  borderTopColor: theme.cardBorder,
                  paddingTop: 8,
                  marginTop: 8,
                }}
              >
                <View
                  style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}
                >
                  <View
                    style={{
                      width: 8,
                      height: 8,
                      borderRadius: 999,
                      backgroundColor: statusColor,
                    }}
                  />
                  <Text
                    style={[s.sLbl, { color: theme.navy, fontWeight: '700' }]}
                  >
                    {auditEventLabel(ev.event_type)}
                  </Text>
                  <Text
                    style={[s.sLbl, { color: statusColor, fontWeight: '700' }]}
                  >
                    {auditStatusLabel(ev.event_status)}
                  </Text>
                  <Text style={[s.sLbl, { color: theme.muted }]}>
                    {new Date(ev.created_at).toLocaleString()}
                  </Text>
                </View>
                {detailsText ? (
                  <Text
                    style={[
                      s.sLbl,
                      { color: theme.muted, marginTop: 4, lineHeight: 17 },
                    ]}
                  >
                    {detailsText}
                  </Text>
                ) : null}
              </View>
            );
          })
        )}
      </View>

      <Text style={[s.sec, { color: theme.navy }]}>
        {t('settings.crash_monitoring.title')}
      </Text>
      <View
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
      >
        <View
          style={{
            flexDirection: 'row',
            alignItems: 'center',
            justifyContent: 'space-between',
            marginBottom: 8,
          }}
        >
          <Text style={[s.sLbl, { color: theme.muted }]}>
            {crashLoading
              ? t('settings.crash_monitoring.loading')
              : t('settings.crash_monitoring.count', {
                  count: crashReports.length,
                })}
          </Text>
          <View style={{ flexDirection: 'row', gap: 8 }}>
            <TouchableOpacity
              style={[
                s.oChip,
                {
                  backgroundColor: theme.inputBg,
                  borderColor: theme.cardBorder,
                },
              ]}
              onPress={loadCrashReports}
            >
              <Text style={[s.oChipT, { color: theme.navy }]}>↻</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[
                s.oChip,
                {
                  backgroundColor: theme.inputBg,
                  borderColor: theme.cardBorder,
                },
              ]}
              onPress={() =>
                Alert.alert(
                  t('settings.crash_monitoring.clear_title'),
                  t('settings.crash_monitoring.clear_confirm'),
                  [
                    { text: t('vault.cancel'), style: 'cancel' },
                    {
                      text: t('settings.crash_monitoring.clear_btn'),
                      style: 'destructive',
                      onPress: async () => {
                        await AppMonitoring.clearCrashReports();
                        await loadCrashReports();
                      },
                    },
                  ],
                )
              }
            >
              <Text style={[s.oChipT, { color: theme.navy }]}>🗑️</Text>
            </TouchableOpacity>
          </View>
        </View>

        {crashReports.length === 0 ? (
          <Text style={[s.sLbl, { color: theme.muted }]}>
            {t('settings.crash_monitoring.empty')}
          </Text>
        ) : (
          crashReports.slice(0, 8).map(report => (
            <View
              key={report.id}
              style={{
                borderTopWidth: 1,
                borderTopColor: theme.cardBorder,
                paddingTop: 8,
                marginTop: 8,
              }}
            >
              <View
                style={{
                  flexDirection: 'row',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 8,
                }}
              >
                <Text
                  style={[s.sLbl, { color: theme.navy, fontWeight: '700', flex: 1 }]}
                >
                  {report.name}
                </Text>
                <Text
                  style={[
                    s.sLbl,
                    {
                      color: report.isFatal ? '#dc2626' : '#d97706',
                      fontWeight: '700',
                    },
                  ]}
                >
                  {report.isFatal
                    ? t('settings.crash_monitoring.fatal')
                    : t('settings.crash_monitoring.nonfatal')}
                </Text>
              </View>
              <Text style={[s.sLbl, { color: theme.muted }]}>
                {report.source} • {new Date(report.createdAt).toLocaleString()}
              </Text>
              <Text
                style={[
                  s.sLbl,
                  { color: theme.navy, marginBottom: 0, lineHeight: 17 },
                ]}
                numberOfLines={3}
              >
                {report.message}
              </Text>
            </View>
          ))
        )}
      </View>
      <View
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
        >
          <ToggleRow
            label={t('settings.breach_check.title')}
            value={Boolean(st2.breachCheckEnabled)}
            onToggle={(v: boolean) => upd('breachCheckEnabled', v)}
            theme={theme}
          />
          <Text style={[s.sLbl, { color: theme.muted, marginBottom: 0 }]}>
            {t('settings.breach_check.desc')}
          </Text>
        </View>
        <View
          style={[
            s.sCard,
            { backgroundColor: theme.card, borderColor: theme.cardBorder },
          ]}
        >
          <ToggleRow
            label={t('settings.bio_login')}
            value={st2.biometricEnabled}
            onToggle={(v: boolean) => upd('biometricEnabled', v)}
            theme={theme}
          />
      </View>
      <View
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
      >
        <ToggleRow
          label={t('settings.dark_mode')}
          value={st2.darkMode}
          onToggle={(v: boolean) => upd('darkMode', v)}
          theme={theme}
        />
      </View>
      <Text style={[s.sec, { color: theme.navy }]}>
        {t('settings.auto_lock')}
      </Text>
      <View
        style={[
          s.sCard,
          { backgroundColor: theme.card, borderColor: theme.cardBorder },
        ]}
      >
        <Text style={[s.sLbl, { color: theme.navy }]}>
          {t('settings.auto_lock_desc')}
        </Text>
        <View style={s.chipR}>
          {ALO.map(o => (
            <TouchableOpacity
              key={o.v}
              style={[
                s.oChip,
                {
                  backgroundColor: theme.inputBg,
                  borderColor: theme.cardBorder,
                },
                st2.autoLockSeconds === o.v && {
                  backgroundColor: theme.sage,
                  borderColor: theme.sage,
                },
              ]}
              onPress={() => upd('autoLockSeconds', o.v)}
              activeOpacity={0.7}
            >
              <Text
