// ── Passkey Form ──
export const PasskeyForm = ({ form, setForm, t, theme }: any) => {
  const [importJson, setImportJson] = useState('');
  const [working, setWorking] = useState(false);
  const [nativeAvailable, setNativeAvailable] = useState<boolean | null>(null);
  const cc = {
    navy: theme?.navy || '#101828',
    sage: theme?.sage || '#72886f',
    sageLight: theme?.sageLight || 'rgba(114,136,111,0.12)',
    muted: theme?.muted || 'rgba(16,24,40,0.45)',
    inputBg: theme?.inputBg || 'rgba(255,255,255,0.7)',
    cardBorder: theme?.cardBorder || 'rgba(255,255,255,0.55)',
  };

  useEffect(() => {
    let mounted = true;

    PasskeyModule.isAvailable()
      .then((available) => {
        if (mounted) {
          setNativeAvailable(available);
        }
      })
      .catch(() => {
        if (mounted) {
          setNativeAvailable(false);
        }
      });

    return () => {
      mounted = false;
    };
  }, []);

  const updatePasskey = (patch: any) =>
    setForm({ ...form, data: { ...form.data, ...patch } });

  const getPasskeyStatusText = () => {
    const mode =
      form.data?.mode === 'rp_connected'
        ? t('passkey.mode_rp_connected')
        : t('passkey.mode_local_helper');
    const challengeSource =
      form.data?.challenge_source === 'server'
        ? t('passkey.challenge_server')
        : t('passkey.challenge_local_helper');
    const verified = form.data?.server_verified
      ? t('passkey.verified_yes')
      : t('passkey.verified_no');

    return [
      `${t('passkey.mode_label')}: ${mode}`,
      `${t('passkey.challenge_source_label')}: ${challengeSource}`,
      `${t('passkey.server_verified_label')}: ${verified}`,
    ].join('\n');
  };

  const autofillRpId = () => {
    const rpId = SecurityModule.normalizePasskeyRpId(form.url, form.data?.rp_id);
    updatePasskey({
      rp_id: rpId,
      display_name:
        form.data?.display_name || form.username || rpId || 'Device passkey',
    });
  };

  const generateIds = () => {
    const generated = SecurityModule.generatePasskeyData({
      username: form.username,
      url: form.url,
      rpId: form.data?.rp_id,
      displayName: form.data?.display_name,
    });
    updatePasskey({
      ...generated,
      mode: 'local_helper',
      challenge_source: 'local_helper',
      server_verified: false,
    });
  };

  const importPayload = () => {
    const parsed = SecurityModule.parsePasskeyPayload(importJson, {
      url: form.url,
      rpId: form.data?.rp_id,
      username: form.username,
    });
    if (!parsed.valid) {
      Alert.alert(t('passkey.import_title'), parsed.errors.join('\n'));
      return;
    }
    setForm({
      ...form,
      data: {
        ...form.data,
        ...parsed.normalized,
        mode: parsed.normalized.mode || 'local_helper',
        challenge_source: parsed.normalized.challenge_source || 'local_helper',
        server_verified: Boolean(parsed.normalized.server_verified),
      },
      url: form.url || !parsed.normalized.rp_id
        ? form.url
        : `https://${parsed.normalized.rp_id}`,
    });
    setImportJson('');
    Alert.alert(t('backup.success'), t('passkey.import_success'));
  };

  const ensureNativeAvailable = () => {
    if (nativeAvailable) {
      return true;
    }

    Alert.alert(
      t('passkey.native_unavailable_title'),
      t('passkey.native_unavailable_message'),
    );
    return false;
  };

  const createOnDevice = async () => {
    if (!ensureNativeAvailable()) {
      return;
    }
    if (!form.username || !(form.url || form.data?.rp_id)) {
      Alert.alert(
        t('passkey.native_create_title'),
        t('passkey.create_prereq'),
      );
      return;
    }

    try {
      setWorking(true);
      const requestJson = PasskeyModule.buildRegistrationRequest({
        title: form.title,
        username: form.username,
        url: form.url,
        rpId: form.data?.rp_id,
        displayName: form.data?.display_name,
        userHandle: form.data?.user_handle,
      });
      const result = await PasskeyModule.createPasskey(requestJson);
      const parsed = SecurityModule.parsePasskeyPayload(
        result.registrationResponseJson,
        {
          url: form.url,
          rpId: form.data?.rp_id,
          username: form.username,
        },
      );
      if (!parsed.normalized.credential_id) {
        Alert.alert(
          t('passkey.native_create_title'),
          t('passkey.native_create_failed'),
        );
        return;
      }

      const validation = SecurityModule.validatePasskeyItem({
        ...form,
        category: 'passkey',
        data: {
          ...form.data,
          ...parsed.normalized,
        },
      });
      if (!validation.valid) {
        Alert.alert(
          t('passkey.validation_title'),
          validation.errors.join('\n'),
        );
        return;
      }
      setForm({
        ...form,
        data: {
          ...form.data,
          ...validation.normalized,
          registration_response_json: result.registrationResponseJson,
          mode: 'local_helper',
          challenge_source: 'local_helper',
          server_verified: false,
          last_registration_at: new Date().toISOString(),
        },
      });
      Alert.alert(t('backup.success'), t('passkey.native_create_success'));
    } catch (error: any) {
      Alert.alert(
        t('passkey.native_create_title'),
        error?.message || t('passkey.native_create_failed'),
      );
    } finally {
      setWorking(false);
    }
  };

  const authenticateOnDevice = async () => {
    if (!ensureNativeAvailable()) {
      return;
    }
    if (!form.data?.credential_id) {
      Alert.alert(t('passkey.native_auth_title'), t('passkey.auth_prereq'));
      return;
    }

    try {
      setWorking(true);
      const requestJson = PasskeyModule.buildAuthenticationRequest({
        url: form.url,
        rpId: form.data?.rp_id,
        credentialId: form.data?.credential_id,
        transport: form.data?.transport,
      });
      const result = await PasskeyModule.authenticatePasskey(requestJson);
      updatePasskey({
        authentication_response_json: result.authenticationResponseJson,
        mode: form.data?.mode === 'rp_connected' ? 'rp_connected' : 'local_helper',
        challenge_source:
          form.data?.challenge_source === 'server' ? 'server' : 'local_helper',
        server_verified: Boolean(form.data?.server_verified),
        last_auth_at: new Date().toISOString(),
      });
      Alert.alert(t('backup.success'), t('passkey.native_auth_success'));
    } catch (error: any) {
      Alert.alert(
        t('passkey.native_auth_title'),
        error?.message || t('passkey.native_auth_failed'),
      );
    } finally {
      setWorking(false);
    }
  };

  return (
    <View>
      <Field
        label={t('fields.username')}
        value={form.username}
        onChange={(v: string) => setForm({ ...form, username: v })}
        placeholder="user@example.com"
        keyboardType="email-address"
        theme={theme}
      />
      <Field
        label={t('fields.url')}
        value={form.url}
        onChange={(v: string) => setForm({ ...form, url: v })}
        placeholder="https://example.com"
        keyboardType="url"
        theme={theme}
      />

      <View
        style={{
          backgroundColor: cc.sageLight,
          borderWidth: 1,
          borderColor: cc.cardBorder,
          borderRadius: 14,
          padding: 12,
          marginBottom: 12,
        }}
      >
        <Text
          style={{
            color: cc.navy,
            fontSize: 12,
            fontWeight: '700',
            marginBottom: 4,
          }}
        >
          {nativeAvailable === false
            ? t('passkey.native_unavailable')
            : t('passkey.native_ready')}
        </Text>
        <Text style={{ color: cc.muted, fontSize: 12, lineHeight: 18 }}>
          {t('passkey.native_hint')}
        </Text>
        <Text
          style={{
            color: cc.muted,
            fontSize: 11,
            lineHeight: 17,
            marginTop: 6,
          }}
        >
          {t('passkey.scope_notice')}
        </Text>
        <Text
          style={{
            color: cc.muted,
            fontSize: 11,
            lineHeight: 17,
            marginTop: 8,
          }}
        >
          {getPasskeyStatusText()}
        </Text>
      </View>

      <View style={{ flexDirection: 'row', gap: 8, marginBottom: 12 }}>
        <TouchableOpacity
          onPress={autofillRpId}
          style={{
            flex: 1,
            backgroundColor: cc.sageLight,
            borderWidth: 1,
            borderColor: cc.cardBorder,
            borderRadius: 12,
            paddingVertical: 10,
            alignItems: 'center',
          }}
        >
          <Text style={{ color: cc.sage, fontSize: 12, fontWeight: '700' }}>
            {t('passkey.fill_rp_id')}
          </Text>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={generateIds}
          style={{
            flex: 1,
            backgroundColor: cc.sageLight,
            borderWidth: 1,
            borderColor: cc.cardBorder,
            borderRadius: 12,
            paddingVertical: 10,
            alignItems: 'center',
          }}
        >
          <Text style={{ color: cc.sage, fontSize: 12, fontWeight: '700' }}>
            {t('passkey.generate_ids')}
          </Text>
        </TouchableOpacity>
      </View>

      <View style={{ flexDirection: 'row', gap: 8, marginBottom: 12 }}>
        <TouchableOpacity
          onPress={createOnDevice}
          disabled={working}
          style={{
            flex: 1,
            backgroundColor: cc.sage,
            borderWidth: 1,
            borderColor: cc.sage,
            borderRadius: 12,
            paddingVertical: 10,
            alignItems: 'center',
            opacity: working ? 0.6 : 1,
          }}
        >
          <Text style={{ color: '#fff', fontSize: 12, fontWeight: '700' }}>
            {working ? t('passkey.native_working') : t('passkey.native_create')}
          </Text>
        </TouchableOpacity>
        <TouchableOpacity
          onPress={authenticateOnDevice}
          disabled={working || !form.data?.credential_id}
          style={{
            flex: 1,
            backgroundColor: cc.inputBg,
            borderWidth: 1,
            borderColor: cc.cardBorder,
            borderRadius: 12,
            paddingVertical: 10,
            alignItems: 'center',
            opacity: working || !form.data?.credential_id ? 0.6 : 1,
          }}
        >
          <Text style={{ color: cc.navy, fontSize: 12, fontWeight: '700' }}>
            {working ? t('passkey.native_working') : t('passkey.native_auth')}
          </Text>
        </TouchableOpacity>
      </View>

      <Field
        label={t('fields.passkey_rp_id')}
        value={form.data?.rp_id}
        onChange={(v: string) => updatePasskey({ rp_id: v })}
        placeholder="example.com"
        theme={theme}
      />
      <Field
        label={t('fields.passkey_credential_id')}
        value={form.data?.credential_id}
        onChange={(v: string) =>
          updatePasskey({ credential_id: SecurityModule.sanitizeBase64Url(v) })
        }
        placeholder="Base64URL credential id"
        theme={theme}
      />
      <Field
        label={t('fields.passkey_user_handle')}
        value={form.data?.user_handle}
        onChange={(v: string) =>
          updatePasskey({ user_handle: SecurityModule.sanitizeBase64Url(v) })
        }
        placeholder="Base64URL user handle"
        theme={theme}
      />
      <Field
        label={t('fields.passkey_display_name')}
        value={form.data?.display_name}
        onChange={(v: string) => updatePasskey({ display_name: v })}
        placeholder="Device passkey"
        theme={theme}
      />
      <SelectChips
        label={t('fields.passkey_transport')}
        options={PASSKEY_TRANSPORTS}
        value={form.data?.transport || 'internal'}
        onChange={(v: string) => updatePasskey({ transport: v })}
        theme={theme}
      />
      <Field
        label={t('passkey.import_json')}
        value={importJson}
        onChange={setImportJson}
        placeholder={t('passkey.import_placeholder')}
        multiline
        lines={5}
        theme={theme}
      />
      <TouchableOpacity
        onPress={importPayload}
        style={{
          backgroundColor: cc.inputBg,
          borderWidth: 1,
          borderColor: cc.cardBorder,
          borderRadius: 12,
          paddingVertical: 10,
          alignItems: 'center',
          marginBottom: 12,
        }}
      >
        <Text style={{ color: cc.navy, fontSize: 12, fontWeight: '700' }}>
          {t('passkey.import_apply')}
        </Text>
      </TouchableOpacity>
      <Field
        label={t('vault.notes')}
        value={form.notes}
        onChange={(v: string) => setForm({ ...form, notes: v })}
        placeholder="..."
        multiline
        lines={3}
        theme={theme}
      />
    </View>
  );
};

// ── Form Router ──
export const CategoryForm = ({
  category,
  form,
  setForm,
  showPw,
  setShowPw,
  pwLen,
  t,
  theme,
}: any) => {
  switch (category) {
    case 'card':
      return (
        <CardForm
          form={form}
          setForm={setForm}
          showPw={showPw}
          setShowPw={setShowPw}
          t={t}
          theme={theme}
        />
      );
    case 'identity':
      return <IdentityForm form={form} setForm={setForm} t={t} theme={theme} />;
    case 'note':
      return <NoteForm form={form} setForm={setForm} t={t} theme={theme} />;
    case 'wifi':
      return (
        <WifiForm
          form={form}
          setForm={setForm}
          showPw={showPw}
          setShowPw={setShowPw}
          t={t}
          theme={theme}
        />
      );
    case 'passkey':
      return <PasskeyForm form={form} setForm={setForm} t={t} theme={theme} />;
    default:
      return (
        <LoginForm
          form={form}
          setForm={setForm}
          showPw={showPw}
          setShowPw={setShowPw}
          pwLen={pwLen}
          t={t}
          theme={theme}
        />
      );
  }
};

// @ts-nocheck
import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  Modal,
  TextInput,
  ActivityIndicator,
  Alert,
} from 'react-native';
import { CloudSyncModule } from '../CloudSyncModule';
import { useTranslation } from 'react-i18next';

const C = {
  bg: '#F0EEE9',
  navy: '#101828',
  sage: '#72886f',
  sageLight: 'rgba(114,136,111,0.12)',
  muted: 'rgba(16,24,40,0.45)',
  card: 'rgba(255,255,255,0.98)',
  inputBg: 'rgba(255,255,255,0.95)',
  cardBorder: 'rgba(16,24,40,0.12)',
  green: '#22c55e',
  red: '#ef4444',
};

export const CloudSyncModal = ({ visible, onClose, onRefresh, theme }: any) => {
  const { t } = useTranslation();
  const cc = { ...C, ...(theme || {}) };
  const isDark = String(cc.bg || '').toLowerCase() === '#0b1220';
  const [url, setUrl] = useState('');
  const [token, setToken] = useState('');
  const [authType, setAuthType] = useState<'Bearer' | 'Basic'>('Bearer');
  const [password, setPassword] = useState(''); // Encrypt/Decrypt password
  const [certificatePin, setCertificatePin] = useState('');
  const [loading, setLoading] = useState(false);
  const tokenRowStyle = {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginTop: 14,
  } as const;
  const loadingStyle = { marginVertical: 20 } as const;
  const downloadButtonStyle = {
    backgroundColor: isDark ? '#1f2937' : cc.navy,
  } as const;

  const handleSync = async (direction: 'up' | 'down') => {
    const safeUrl = url.trim();
    if (!safeUrl.startsWith('https://')) {
      Alert.alert(t('cloud.error'), t('cloud.err_url'));
      return;
    }
    if (password.length < 6) {
      Alert.alert(t('cloud.error'), t('cloud.err_len'));
      return;
    }
    const safePin = certificatePin.trim();
    const validPin = /^sha256\/[A-Za-z0-9+/]{43}=$/.test(safePin);
    if (!validPin) {
      Alert.alert(
        t('cloud.error'),
        `${t('cloud.pin_required')} ${t('cloud.pin_format')}`,
      );
      return;
    }

    setLoading(true);
    try {
      if (direction === 'up') {
        await CloudSyncModule.syncToCloud(
          safeUrl,
          token,
          authType,
          password,
          safePin,
        );
        Alert.alert(t('cloud.success'), t('cloud.success_up'));
      } else {
        const res = await CloudSyncModule.syncFromCloud(
          safeUrl,
          token,
          authType,
          password,
          safePin,
        );
        if (onRefresh) onRefresh();
        Alert.alert(
          t('cloud.success'),
          t('cloud.success_down', {
            imported: res.imported,
            skipped: res.skipped,
          }),
        );
      }
      onClose();
    } catch (e: any) {
      Alert.alert(t('cloud.err_sync'), e.message || 'Error occurred.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal visible={visible} animationType="fade" transparent>
      <View style={st.overlay}>
        <View style={[st.container, { backgroundColor: cc.bg || '#0b1220' }]}>
          <View style={st.header}>
            <Text style={[st.title, { color: cc.navy }]}>
              {t('cloud.title')}
            </Text>
            <TouchableOpacity onPress={onClose} disabled={loading}>
              <Text style={[st.closeBtn, { color: cc.muted }]}>✕</Text>
            </TouchableOpacity>
          </View>

          <View style={st.content}>
            <Text style={[st.label, { color: cc.muted }]}>
              {t('cloud.url_label')}
            </Text>
            <TextInput
              style={[
                st.input,
                {
                  backgroundColor: cc.inputBg,
                  borderColor: cc.cardBorder || 'rgba(148,163,184,0.25)',
                  color: cc.navy,
                },
              ]}
              value={url}
              onChangeText={setUrl}
              placeholder="https://nextcloud.example.com/remote.php/webdav/aegis.aegis"
              placeholderTextColor={cc.muted}
              autoCapitalize="none"
            />

            <View style={tokenRowStyle}>
              <Text style={[st.label, { color: cc.muted }]}>
                {t('cloud.token_label')}
              </Text>
              <TouchableOpacity
                onPress={() =>
                  setAuthType(authType === 'Bearer' ? 'Basic' : 'Bearer')
                }
              >
                <Text style={[st.toggleText, { color: cc.sage }]}>
                  {authType} 🔄
                </Text>
              </TouchableOpacity>
            </View>
            <TextInput
              style={[
                st.input,
                {
                  backgroundColor: cc.inputBg,
                  borderColor: cc.cardBorder || 'rgba(148,163,184,0.25)',
                  color: cc.navy,
                },
              ]}
              value={token}
              onChangeText={setToken}
              placeholder={
                authType === 'Bearer'
                  ? 'API Token'
                  : 'username:password (base64 optional)'
              }
              placeholderTextColor={cc.muted}
              secureTextEntry
              autoCapitalize="none"
            />

            <Text style={[st.label, { color: cc.muted }]}>
              {t('cloud.pw_label')}
            </Text>
            <TextInput
              style={[
                st.input,
                {
                  backgroundColor: cc.inputBg,
                  borderColor: cc.cardBorder || 'rgba(148,163,184,0.25)',
                  color: cc.navy,
                },
              ]}
              value={password}
              onChangeText={setPassword}
              placeholder={t('cloud.pw_ph')}
              placeholderTextColor={cc.muted}
              secureTextEntry
            />

            <Text style={[st.label, { color: cc.muted }]}>
              {t('cloud.pin_label')}
            </Text>
            <TextInput
              style={[
                st.input,
                {
                  backgroundColor: cc.inputBg,
                  borderColor: cc.cardBorder || 'rgba(148,163,184,0.25)',
                  color: cc.navy,
                },
              ]}
              value={certificatePin}
              onChangeText={setCertificatePin}
              placeholder="sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="
              placeholderTextColor={cc.muted}
              autoCapitalize="none"
              autoCorrect={false}
            />

            <View style={[st.infoBox, { backgroundColor: cc.sageLight }]}>
              <Text style={[st.infoText, { color: cc.navy }]}>
                {t('cloud.info')}
              </Text>
            </View>

            {loading ? (
              <ActivityIndicator
                size="large"
                color={cc.sage}
                style={loadingStyle}
              />
            ) : (
              <View style={st.buttonRow}>
                <TouchableOpacity
                  style={[st.btn, { backgroundColor: cc.sage }]}
                  onPress={() => handleSync('up')}
                >
                  <Text style={st.btnText}>{t('cloud.btn_up')}</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[st.btn, downloadButtonStyle]}
                  onPress={() => handleSync('down')}
                >
                  <Text style={st.btnText}>{t('cloud.btn_down')}</Text>
                </TouchableOpacity>
              </View>
            )}
          </View>
        </View>
      </View>
    </Modal>
  );
};

const st = StyleSheet.create({
  overlay: {
    flex: 1,
    backgroundColor: 'rgba(0,0,0,0.5)',
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  container: {
    backgroundColor: '#F0EEE9',
    width: '100%',
    borderRadius: 24,
    overflow: 'hidden',
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 20,
    paddingBottom: 10,
  },
  title: { fontSize: 18, fontWeight: '800', color: C.navy },
  closeBtn: { fontSize: 24, color: C.muted, padding: 4 },
  content: { padding: 20, paddingTop: 10 },
  label: {
    fontSize: 13,
    fontWeight: '700',
    color: C.muted,
