          >
            {/* Entry Form */}
            {isAdding && (
              <Suspense fallback={<div className="p-8 text-center opacity-50">Loading...</div>}><EntryForm initialEntry={editEntry || undefined} onClose={handleCloseForm} /></Suspense>
            )}

            {/* Shimmer Skeleton / Entries / Empty State */}
            {isDecrypting ? (
