            >
              {text.reload}
            </button>
            <button
              type="button"
              onClick={handleQuit}
              className="rounded-xl bg-slate-700 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-600"
            >
              {text.quit}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

class AppErrorBoundary extends Component<
  { children: ReactNode; onError: (error: Error) => void },
  { error: Error | null }
> {
  constructor(props: { children: ReactNode; onError: (error: Error) => void }) {
    super(props);
    this.state = { error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  componentDidCatch(error: Error, _info: ErrorInfo) {
    this.props.onError(error);
  }

  render() {
    if (this.state.error) {
      return <DiagnosticScreen error={this.state.error} />;
    }

    return this.props.children;
  }
}

export function ElectronFailSafe({ children }: { children: ReactNode }) {
  const [fatalError, setFatalError] = useState<Error | null>(null);

  useEffect(() => {
    const onError = (event: ErrorEvent) => {
      setFatalError(event.error instanceof Error ? event.error : new Error(event.message || "WINDOW_ERROR"));
    };
    const onUnhandledRejection = (event: PromiseRejectionEvent) => {
      const reason = event.reason;
      setFatalError(reason instanceof Error ? reason : new Error(typeof reason === "string" ? reason : "UNHANDLED_REJECTION"));
    };

    window.addEventListener("error", onError);
    window.addEventListener("unhandledrejection", onUnhandledRejection);
    return () => {
      window.removeEventListener("error", onError);
      window.removeEventListener("unhandledrejection", onUnhandledRejection);
    };
  }, []);

  if (fatalError) {
    return <DiagnosticScreen error={fatalError} />;
  }

  return <AppErrorBoundary onError={setFatalError}>{children}</AppErrorBoundary>;
}

