  const { videoRef, startScanning, stopScanning, isScanning, progress, receivedChunks, totalChunks, error } = useQRScanner(onScanSuccess);
  const completed = progress === 100;

  useEffect(() => {
    void startScanning();
    return () => stopScanning();
