          autoCapitalize="characters"
          autoCorrect="off"
          spellCheck={false}
        />
        <p className="mt-2 text-xs opacity-70">{t('qrSyncTransferCodeImportHint', 'The QR frames stay encrypted until you enter the matching transfer code.')}</p>
      </div>

