                {t('qrSyncReceivingProgress', { received: receivedChunks, total: totalChunks, defaultValue: 'Receiving chunk {{received}}/{{total}}...' })}
              </p>
            </div>
          )}
        </div>
      )}

      <button onClick={onCancel} className="mt-4 px-8 py-2.5 rounded-xl border toolbar-control transition-all text-sm font-semibold shadow-sm z-10 active:scale-95">
        {t('cancel', 'Cancel')}
      </button>
