                        </button>
                      </div>
                      <div className="mt-3 flex flex-wrap gap-2">
                        {member.status === "pending" ? (
                          <button
                            onClick={() => updateMemberStatus(member.id, "active")}
                            className="inline-flex items-center gap-2 rounded-xl border border-[var(--color-sage-green)]/30 px-3 py-2 text-xs font-semibold text-[var(--color-sage-green)] transition-colors hover:bg-[var(--color-sage-green)]/10"
                          >
                            <Check className="h-3.5 w-3.5" />
                            {t("sharedSpacesApproveMemberBtn")}
                          </button>
                        ) : null}
                        {member.status !== "emergency_only" ? (
                          <button
                            onClick={() => updateMemberStatus(member.id, "emergency_only")}
                            className="inline-flex items-center gap-2 rounded-xl border border-amber-500/30 px-3 py-2 text-xs font-semibold text-amber-600 transition-colors hover:bg-amber-500/10"
                          >
                            <ShieldAlert className="h-3.5 w-3.5" />
                            {t("sharedSpacesEmergencyOnlyBtn")}
                          </button>
                        ) : (
                          <button
                            onClick={() => updateMemberStatus(member.id, "active")}
                            className="inline-flex items-center gap-2 rounded-xl border border-[var(--color-sage-green)]/30 px-3 py-2 text-xs font-semibold text-[var(--color-sage-green)] transition-colors hover:bg-[var(--color-sage-green)]/10"
                          >
                            <Check className="h-3.5 w-3.5" />
                            {t("sharedSpacesRestoreActiveBtn")}
                          </button>
                        )}
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
            </div>
          </div>

          <div className="border-t border-white/8 bg-[var(--color-cloud-dancer)]/92 px-5 py-4 backdrop-blur-sm dark:bg-[#182132]/92 lg:px-6">
            <div className="flex flex-col gap-3 md:flex-row md:justify-between">
              <button
                onClick={() => (editingSpaceId ? deleteSpace(editingSpaceId) : beginEdit())}
                className="inline-flex items-center justify-center gap-2 rounded-2xl border border-red-500/20 px-4 py-3 text-sm font-semibold text-red-600 transition-colors hover:bg-red-500/10 disabled:opacity-50"
                disabled={!editingSpaceId}
              >
                <Trash2 className="h-4 w-4" />
                {t("sharedSpacesDeleteBtn")}
              </button>

              <div className="flex gap-3">
                <button
                  onClick={onClose}
                  className="settings-pill-secondary rounded-2xl px-5 py-3 text-sm font-semibold"
                >
                  {t("close")}
                </button>
                <button
                  onClick={saveSpace}
                  className="settings-action-btn-primary rounded-2xl px-5 py-3 text-sm font-semibold shadow-md transition-transform active:scale-95"
                >
                  {t("sharedSpacesSaveBtn")}
                </button>
              </div>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

// @ts-nocheck
import { History } from "lucide-react";
import { useTranslation } from "react-i18next";
import type { SharingAuditEvent } from "../../lib/SecureAppSettings";
import { SharingAuditService, type SharingAuditFilter } from "../../lib/SharingAuditService";

interface SharingAuditPanelProps {
  events: SharingAuditEvent[];
  activeFilter: SharingAuditFilter;
  onFilterChange: (filter: SharingAuditFilter) => void;
  highlightedEventIds?: string[];
  focusLabel?: string | null;
  onOpenEventTarget?: (event: SharingAuditEvent) => void;
  onFocusEventTarget?: (event: SharingAuditEvent) => void;
}

const mapAuditLabelKey = (type: SharingAuditEvent["type"]) => {
  if (type === "space_saved") return "sharingAuditType.space_saved";
  if (type === "space_deleted") return "sharingAuditType.space_deleted";
  if (type === "assignment_saved") return "sharingAuditType.assignment_saved";
  if (type === "assignment_cleared") return "sharingAuditType.assignment_cleared";
  return "sharingAuditType.assignment_reviewed";
};

export function SharingAuditPanel({
  events,
  activeFilter,
  onFilterChange,
  highlightedEventIds = [],
  focusLabel,
  onOpenEventTarget,
  onFocusEventTarget,
}: SharingAuditPanelProps) {
  const { t } = useTranslation();
  const filters: SharingAuditFilter[] = ["all", "spaces", "assignments", "reviews"];
  const highlighted = new Set(highlightedEventIds);

  return (
    <div className="settings-subpanel rounded-2xl border p-5 shadow-inner">
      <div className="sr-only" aria-live="polite">
        {focusLabel ? t("sharingAuditLiveFocus", { target: focusLabel }) : ""}
      </div>
      <div className="mb-3 flex items-center gap-2">
        <History className="h-4 w-4 text-[var(--color-sage-green)]" />
        <h4 className="text-sm font-semibold text-[var(--color-deep-navy)] dark:text-white">
          {t("sharingAuditTitle")}
        </h4>
      </div>

      <div className="mb-3 flex flex-wrap gap-2">
        {filters.map((filter) => (
          <button
            key={filter}
            onClick={() => onFilterChange(filter)}
            className={`rounded-full px-3 py-1 text-[10px] font-bold uppercase tracking-[0.16em] ${
              activeFilter === filter
                ? "settings-filter-chip settings-filter-chip-active"
                : "settings-filter-chip"
            }`}
          >
            {t(`sharingAuditFilter.${filter}`)}
          </button>
        ))}
      </div>

      {focusLabel ? (
        <div className="mb-3 rounded-2xl border border-[var(--color-sage-green)]/20 bg-[var(--color-sage-green)]/8 px-4 py-3 text-xs text-[var(--color-deep-navy)]/75 dark:text-white/75">
          {t("sharingAuditFocusLabel", { target: focusLabel })}
        </div>
      ) : null}

      <div className="space-y-2">
        {events.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-black/10 px-4 py-3 text-sm text-[var(--color-deep-navy)]/60 dark:border-white/10 dark:text-white/60">
            {t("sharingAuditEmpty")}
          </div>
        ) : (
          events.slice().reverse().slice(0, 5).map((event) => {
            const navigationTarget = SharingAuditService.getNavigationTarget(event);
            return (
              <div
                key={event.id}
                className={`rounded-2xl border px-4 py-3 ${
                  highlighted.has(event.id)
                    ? "border-[var(--color-sage-green)]/30 bg-[var(--color-sage-green)]/10 dark:border-[var(--color-sage-green)]/25 dark:bg-[var(--color-sage-green)]/10"
                    : "border-black/5 bg-white/70 dark:border-white/10 dark:bg-white/5"
                }`}
              >
                <div className="flex items-center justify-between gap-3">
                  <div>
                    <div className="text-sm font-semibold text-[var(--color-deep-navy)] dark:text-white">
                      {t(mapAuditLabelKey(event.type))}
                    </div>
                    <div className="mt-1 text-xs text-[var(--color-deep-navy)]/65 dark:text-white/65">
                      {event.detail || event.spaceId || event.entryId || t("sharingAuditUnknown")}
                    </div>
                  </div>
                  <div className="text-[11px] text-[var(--color-deep-navy)]/50 dark:text-white/50">
                    {new Date(event.at).toLocaleString()}
                  </div>
                </div>
                {navigationTarget ? (
                  <div className="mt-3 flex justify-end gap-2">
                    <button
                      onClick={() => onFocusEventTarget?.(event)}
                      aria-label={t("sharingAuditFocusAria", {
                        target: event.detail || event.spaceId || event.entryId || t("sharingAuditUnknown"),
                      })}
                      className="rounded-full border border-black/10 bg-black/5 px-3 py-1 text-[10px] font-bold uppercase tracking-[0.16em] text-[var(--color-deep-navy)]/70 transition-colors hover:bg-black/10 dark:border-white/10 dark:bg-white/5 dark:text-white/75 dark:hover:bg-white/10"
                    >
                      {t("sharingAuditFocusTarget")}
                    </button>
                    <button
                      onClick={() => onOpenEventTarget?.(event)}
                      aria-label={t("sharingAuditOpenAria", {
                        target: event.detail || event.spaceId || event.entryId || t("sharingAuditUnknown"),
                      })}
                      className="rounded-full border border-[var(--color-sage-green)]/20 bg-[var(--color-sage-green)]/10 px-3 py-1 text-[10px] font-bold uppercase tracking-[0.16em] text-[var(--color-sage-green)] transition-colors hover:bg-[var(--color-sage-green)]/20"
                    >
                      {navigationTarget.kind === "entry"
                        ? t("sharingAuditOpenEntry")
                        : t("sharingAuditOpenSpace")}
                    </button>
                  </div>
                ) : null}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

// @ts-nocheck
import { AlertTriangle, ShieldCheck, ShieldX, Users } from "lucide-react";
import { useTranslation } from "react-i18next";
import type { SharingOverviewIssue, SharingOverviewReport } from "../../lib/SharingOverviewService";

interface SharingOverviewPanelProps {
  report: SharingOverviewReport;
  onManageSpaces: () => void;
  onOpenIssueItem: (issue: SharingOverviewIssue) => void;
  onResolveIssue: (issue: SharingOverviewIssue) => void;
  onOpenSpace: (spaceId: string) => void;
  activeIssueKey?: string | null;
  activeSpaceId?: string | null;
}

const getRiskBadgeClassName = (riskLevel: SharingOverviewReport["riskLevel"]) => {
  if (riskLevel === "critical") {
    return "bg-red-500/15 text-red-700 dark:bg-red-500/20 dark:text-red-200";
  }
  if (riskLevel === "high") {
    return "bg-orange-500/15 text-orange-700 dark:bg-orange-500/20 dark:text-orange-200";
  }
  if (riskLevel === "medium") {
    return "bg-amber-500/15 text-amber-700 dark:bg-amber-500/20 dark:text-amber-100";
  }
  return "bg-emerald-500/15 text-emerald-700 dark:bg-emerald-500/20 dark:text-emerald-100";
};

const getIssueBadgeClassName = (severity: "high" | "medium") =>
  severity === "high"
    ? "bg-red-500/15 text-red-700 dark:bg-red-500/20 dark:text-red-200"
    : "bg-amber-500/15 text-amber-700 dark:bg-amber-500/20 dark:text-amber-100";

export function SharingOverviewPanel({
  report,
  onManageSpaces,
  onOpenIssueItem,
  onResolveIssue,
  onOpenSpace,
  activeIssueKey = null,
  activeSpaceId = null,
}: SharingOverviewPanelProps) {
  const { t } = useTranslation();
  const activeIssue = activeIssueKey
    ? report.issues.find((issue) => `${issue.type}-${issue.itemId}` === activeIssueKey) || null
    : null;
  const activeSpace = activeSpaceId
    ? report.spaces.find((space) => space.id === activeSpaceId) || null
    : null;

  return (
    <div className="settings-panel rounded-3xl p-6 shadow-sm">
      <div className="sr-only" aria-live="polite">
        {activeIssue
          ? t("sharingOverviewLiveIssue", { target: activeIssue.title })
          : activeSpace
            ? t("sharingOverviewLiveSpace", { target: activeSpace.name })
            : ""}
      </div>
      <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
        <div className="space-y-2">
          <div className="flex items-center gap-2">
            <Users className="h-5 w-5 text-[var(--color-sage-green)]" />
            <h3 className="text-lg font-semibold tracking-tight text-[var(--color-deep-navy)] dark:text-white">
              {t("sharingOverviewTitle")}
            </h3>
          </div>
          <p className="max-w-2xl text-xs leading-relaxed text-[var(--color-deep-navy)]/70 dark:text-white/70">
            {t("sharingOverviewDesc")}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={onManageSpaces}
            className="rounded-2xl border border-[var(--color-sage-green)]/25 bg-[var(--color-sage-green)]/10 px-4 py-3 text-sm font-semibold text-[var(--color-sage-green)] transition-colors hover:bg-[var(--color-sage-green)]/15 dark:border-[var(--color-sage-green)]/20 dark:text-emerald-100"
          >
            {t("sharingOverviewManageBtn")}
          </button>
          <div className="rounded-2xl bg-[var(--color-sage-green)]/10 px-4 py-3 text-center dark:bg-[var(--color-sage-green)]/15">
            <div className="text-[10px] font-semibold uppercase tracking-[0.2em] text-[var(--color-deep-navy)]/60 dark:text-white/60">
              {t("sharingOverviewScore")}
            </div>
            <div className="mt-1 text-2xl font-bold tracking-tight text-[var(--color-deep-navy)] dark:text-white">
              {report.score}
            </div>
          </div>
          <span
            className={`rounded-full px-3 py-1 text-[11px] font-bold uppercase tracking-[0.18em] ${getRiskBadgeClassName(
              report.riskLevel
            )}`}
          >
            {t(`sharingOverviewRisk.${report.riskLevel}`)}
          </span>
        </div>
      </div>

      <div className="mt-5 grid grid-cols-2 gap-3 md:grid-cols-4">
        <div className="settings-subpanel rounded-2xl border p-4 shadow-inner">
          <div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[var(--color-deep-navy)]/60 dark:text-white/60">
            {t("sharingOverviewMetricSharedItems")}
          </div>
          <div className="mt-2 text-2xl font-bold text-[var(--color-deep-navy)] dark:text-white">
            {report.summary.sharedItems}
          </div>
        </div>
        <div className="settings-subpanel rounded-2xl border p-4 shadow-inner">
          <div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[var(--color-deep-navy)]/60 dark:text-white/60">
            {t("sharingOverviewMetricSpaces")}
          </div>
          <div className="mt-2 text-2xl font-bold text-[var(--color-deep-navy)] dark:text-white">
            {report.summary.spaces}
          </div>
        </div>
        <div className="settings-subpanel rounded-2xl border p-4 shadow-inner">
          <div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[var(--color-deep-navy)]/60 dark:text-white/60">
            {t("sharingOverviewMetricPendingMembers")}
          </div>
          <div className="mt-2 text-2xl font-bold text-[var(--color-deep-navy)] dark:text-white">
            {report.summary.pendingMembers}
          </div>
        </div>
        <div className="settings-subpanel rounded-2xl border p-4 shadow-inner">
          <div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-[var(--color-deep-navy)]/60 dark:text-white/60">
            {t("sharingOverviewMetricReviewRequired")}
          </div>
          <div className="mt-2 text-2xl font-bold text-[var(--color-deep-navy)] dark:text-white">
            {report.summary.reviewRequiredItems}
          </div>
        </div>
      </div>

      <div className="mt-5 grid gap-4 lg:grid-cols-[1.1fr_0.9fr]">
        <div className="settings-subpanel rounded-2xl border p-5 shadow-inner">
          <div className="mb-3 flex items-center gap-2">
            {report.issues.length > 0 ? (
              <ShieldX className="h-4 w-4 text-red-500" />
            ) : (
              <ShieldCheck className="h-4 w-4 text-[var(--color-sage-green)]" />
