import { TOTPWidget } from "./TOTPWidget";
import { getCategoryIcon } from "../../lib/getCategoryIcon";
import { useVault } from "../../contexts/VaultContext";
import { vaultService, type VaultEntry } from "../../vaultService";
import { useTranslation } from "react-i18next";
import { toast } from "react-toastify";
import { SharedSpaceService } from "../../lib/SharedSpaceService";

interface VaultEntryCardProps {
  entry: VaultEntry;
  onEdit: (entry: VaultEntry) => void;
}

/**
 * VaultEntryCard — Tek bir kasa girişini gösteren kart bileşeni.
 * Parola göster/gizle, kopyala, düzenle, sil/geri yükle ve ek dosya indirme aksiyonlarını içerir.
 */
export function VaultEntryCard({ entry: p, onEdit }: VaultEntryCardProps) {
  const { t } = useTranslation();
  const {
    copiedId,
    handleCopyItem,
    visiblePasswords,
    toggleVisibility,
    categoryFilter,
    loadPasswords,
    handleDeleteEntry,
    handleRestoreEntry,
    viewDensity,
  } = useVault();

  const isCopied = copiedId === p.id;

  const handleDownloadAttachment = async (attachmentId: string, name: string) => {
    try {
      toast.info(t("decryptingAttachment", { name }));
      const blob = await vaultService.getDecryptedAttachment(attachmentId);
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err: unknown) {
      console.error(err);
      toast.error(t("decryptFailed"));
    }
  };

  const isVulnerable =
    !p.pass ||
    p.pass.length < 8 ||
    (p.pwned_count || 0) > 0;
  const sharedSpaceName = p.sharing?.[0]?.space_id
    ? SharedSpaceService.listSpaces().find((space) => space.id === p.sharing?.[0]?.space_id)?.name
    : null;
  const isSitePasskeyRecord = p.category === "Passkeys" || Boolean(p.passkeyMetadata);

  const compact = viewDensity === "compact";

  return (
    <article className={`vault-entry-card grid grid-cols-1 xl:grid-cols-[minmax(0,1fr)_auto] ${compact ? "gap-3 p-4" : "gap-4 p-5 md:p-6"} rounded-[1.25rem] transition-all relative group/item`}>
      <div className="flex items-start gap-5 relative z-10 min-w-0">
        <div className={`vault-entry-icon ${compact ? "w-12 h-12" : "w-14 h-14 md:w-16 md:h-16"} shrink-0 rounded-[1.25rem] flex items-center justify-center shadow-sm`}>
          <div className={compact ? "scale-100" : "scale-110 md:scale-125"}>{getCategoryIcon(p.category)}</div>
        </div>
        <div className="flex-1 min-w-0 flex flex-col gap-3">
          <div className="min-h-7 flex items-center">
          <h3 className={`${compact ? "text-base" : "text-lg"} font-bold text-[var(--color-deep-navy)] truncate flex items-center gap-2 min-w-0`}>
            {p.title}
            {sharedSpaceName && (
              <span className="rounded-full bg-[var(--color-sage-green)]/15 px-2 py-0.5 text-[10px] font-bold uppercase tracking-widest text-[var(--color-sage-green)]">
                {sharedSpaceName}
              </span>
            )}
            {isSitePasskeyRecord && (
              <span className="rounded-full bg-sky-500/12 px-2 py-0.5 text-[10px] font-bold uppercase tracking-widest text-sky-700 dark:text-sky-300">
                {t("passkeys")}
              </span>
            )}
            {(p.pwned_count || 0) > 0 && (
              <span
                className="bg-red-500 text-white text-[10px] px-2 py-0.5 rounded-full uppercase tracking-widest font-black"
                title={t("pwnedWarning")}
              >
                {t("pwned")}
              </span>
            )}
          </h3>
          </div>
          <div className={`flex flex-col md:flex-row md:items-center gap-2 md:gap-3 mt-1 ${compact ? "text-xs" : "text-sm"}`}>
            <p className="opacity-60 font-[var(--font-geist-mono)] tracking-tight truncate flex items-center gap-2">
              {isSitePasskeyRecord ? (p.passkeyMetadata?.rp_id || p.username) : p.username}
              {p.tags && p.tags.length > 0 && (
                <span className="hidden xl:flex items-center gap-1 opacity-70 border border-black/10 px-1.5 py-0.5 rounded text-[10px] ml-2">
                  <Tag className="w-2.5 h-2.5" /> {p.tags[0]} {p.tags.length > 1 && `+${p.tags.length - 1}`}
                </span>
              )}
            </p>
            <span className="hidden md:block w-1.5 h-1.5 rounded-full entry-divider shrink-0" />
            <div className="flex items-center gap-2">
              <span
                className={`pass-font ${compact ? "text-xs" : "text-sm"} rounded-md select-all transition-all duration-300 ${
                  visiblePasswords.has(p.id)
                    ? "password-reveal-chip backdrop-blur-[20px] px-2 py-1"
                    : "tracking-[0.25em] opacity-40 select-none mt-1"
                }`}
              >
                {visiblePasswords.has(p.id) ? p.pass : "••••••••"}
              </span>
              <button
                onClick={() => toggleVisibility(p.id)}
                className="p-1.5 rounded-md entry-action-btn-muted transition-all"
                title={visiblePasswords.has(p.id) ? "Hide Password" : "Show liquid password"}
              >
                {visiblePasswords.has(p.id) ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
              </button>
            </div>
          </div>

          <div className="space-y-2">
            {/* Attachments */}
            {p.attachments && p.attachments.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {p.attachments.map((att) => (
                  <button
                    key={att.id}
                    onClick={() => handleDownloadAttachment(att.id, att.name)}
                    className="group flex items-center gap-1.5 bg-[var(--color-sage-green)]/10 text-[var(--color-sage-green)] border border-[var(--color-sage-green)]/30 hover:bg-[var(--color-sage-green)]/20 px-2.5 py-1 rounded-md text-[11px] font-bold shadow-sm transition-all relative overflow-hidden"
                    title={`Download ${att.name} (${(att.size / (1024 * 1024)).toFixed(2)}MB)`}
                  >
                    <Paperclip className="w-3 h-3 group-hover:scale-110 transition-transform" />
                    <span className="max-w-[150px] truncate">{att.name}</span>
                    <DownloadCloud className="w-3 h-3 ml-1 opacity-0 group-hover:opacity-100 transition-opacity absolute right-2" />
                  </button>
                ))}
              </div>
            )}

            {/* TOTP 2FA Widget */}
            {p.totpSecret && (
              <div>
                <TOTPWidget
                  totpSecret={p.totpSecret}
                  issuer={p.totp_issuer}
                  algorithm={p.totp_algorithm}
                  digits={p.totp_digits}
                  period={p.totp_period}
                />
              </div>
            )}

            {/* Secure Notes Preview */}
            {p.notes && p.category !== "Notes" && (
              <div className="vault-entry-notes-box flex items-start gap-1.5 px-2.5 py-1.5 rounded-lg">
                <FileText className="w-3 h-3 text-amber-500 mt-0.5 shrink-0" />
                <p className="text-[11px] text-[var(--color-deep-navy)]/70 line-clamp-2 leading-relaxed">
                  {p.notes.length > 120 ? p.notes.slice(0, 120) + "..." : p.notes}
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Actions */}
      <div className="flex items-stretch xl:items-start justify-end relative z-10 shrink-0 xl:min-w-[238px]">
        <div className="flex flex-col-reverse xl:flex-col justify-between gap-3 w-full xl:w-auto">
        <div className="hidden lg:flex items-center justify-end gap-3 xl:min-h-7">
          <div className="w-24 h-2 entry-divider rounded-full overflow-hidden">
            <div 
              className="h-full" 
              style={{ 
                width: `${p.strength || 0}%`,
                backgroundColor: (p.strength || 0) > 80 ? 'var(--color-sage-green)' : (p.strength || 0) > 40 ? '#f59e0b' : '#ef4444'
              }} 
            />
          </div>
          <span 
            className="text-[11px] uppercase font-bold opacity-80"
            style={{ color: (p.strength || 0) > 80 ? 'var(--color-sage-green)' : (p.strength || 0) > 40 ? '#f59e0b' : '#ef4444' }}
          >
            {(p.strength || 0) > 80 ? t("strong") : (p.strength || 0) > 40 ? t("average") : t("weak")}
          </span>
        </div>

        <div className="flex items-center justify-end gap-2 xl:ml-4 flex-wrap">
          <div className="relative flex items-center gap-2">
            {isVulnerable && (
              <button
                onClick={() => {
                  onEdit({ ...p });
                  toast.info(t("updateNow"));
                }}
                className="px-3 py-1.5 rounded-lg bg-red-500/10 text-red-600 text-[10px] font-black uppercase tracking-tighter hover:bg-red-500 hover:text-white transition-all animate-pulse"
              >
                {t("updateNow")}
              </button>
            )}
            <button
              onClick={() => onEdit({ ...p, pass: p.pass || "" })}
              className="vault-action-btn p-3 rounded-xl transition-all flex items-center justify-center"
              title={t("editEntry", "Edit")}
            >
              <Edit2 className="w-5 h-5" />
            </button>
            <div className="relative">
              <button
                onClick={() => handleCopyItem(p.id, p.pass || "")}
                className={`relative z-10 p-3 rounded-xl transition-all flex items-center justify-center ${
                  isCopied
                    ? "bg-[var(--color-sage-green)] text-[var(--color-deep-navy)] shadow-[0_0_15px_rgba(135,159,132,0.4)] scale-110"
                    : "vault-action-btn hover:shadow-md"
                }`}
              >
                {isCopied ? (
                  <Check className="w-5 h-5 text-[var(--color-sage-green)] drop-shadow-[0_0_8px_rgba(135,159,132,0.8)]" />
                ) : (
                  <Copy className="w-5 h-5 opacity-70" />
                )}
              </button>
              {isCopied && (
                <div className="absolute inset-0 pointer-events-none flex justify-center items-center">
                  {[...Array(6)].map((_, i) => (
                    <div
                      key={i}
                      className="absolute w-2 h-2 bg-[var(--color-sage-green)] rounded-full animate-float opacity-0"
                      style={{ transform: `rotate(${i * 60}deg)`, animationDelay: `${i * 0.05}s` }}
                    />
                  ))}
                </div>
              )}
            </div>

            {categoryFilter === "Trash" ? (
              <>
                <button
                  onClick={() => handleRestoreEntry(p.id)}
                  className="p-3 rounded-xl bg-[var(--color-sage-green)]/10 text-[var(--color-sage-green)] hover:bg-[var(--color-sage-green)] hover:text-white transition-all shadow-sm"
                  title={t("restore")}
                >
                  <FileUp className="w-5 h-5" />
                </button>
                <button
                  onClick={async () => {
                    if (confirm(t("confirmDeleteCard"))) {
                      await vaultService.deletePermanently(p.id);
                      toast.success(t("itemDeleted"));
                      loadPasswords();
                    }
                  }}
                  className="p-3 rounded-xl bg-red-500/10 text-red-600 hover:bg-red-500 hover:text-white transition-all shadow-sm"
                  title={t("deletePermanently")}
                >
                  <X className="w-5 h-5" />
                </button>
              </>
            ) : (
              <button
                onClick={() => handleDeleteEntry(p.id)}
                className="vault-action-btn p-3 rounded-xl hover:bg-red-500/10 hover:text-red-500 transition-all flex items-center justify-center"
                title={t("moveToTrash")}
              >
                <Trash2 className="w-5 h-5" />
              </button>
            )}
          </div>
        </div>
        </div>
      </div>
    </article>
  );
}

// @ts-nocheck
import { ShieldAlert, AlertTriangle, KeyRound, Clock4, Globe } from "lucide-react";
import { GlowCard } from "../ui/GlowCard";
import { useVault } from "../../contexts/VaultContext";
import { useTranslation } from "react-i18next";

/**
 * WatchtowerPanel — Güvenlik denetimi widget'ı (sağ sidebar).
 * Zayıf, tekrarlanan, eski ve sızdırılmış şifre sayılarını gösterir.
 * HIBP (Have I Been Pwned) tarama butonunu içerir.
 */
export function WatchtowerPanel() {
  const { t } = useTranslation();
  const {
    watchtower,
    isPwnedScanning,
    pwnedScanProgress,
    handleScanPwned,
    passwords,
    hibpEnabled,
    setHibpEnabled,
    hibpLastResult,
    securityModeProfile,
  } = useVault();
  const hibpPolicyLocked = securityModeProfile === "maximum";

  return (
    <GlowCard className="watchtower-surface rounded-3xl p-6 relative">
      <div className="absolute -right-4 -top-4 w-24 h-24 bg-red-500/5 rounded-full blur-xl pointer-events-none" />
      <div className="flex items-center gap-2 mb-4">
        <ShieldAlert className="w-4 h-4 text-[var(--color-deep-navy)]/60" />
        <h3 className="text-sm font-semibold opacity-60 uppercase tracking-widest">{t("watchtowerTitle")}</h3>
      </div>

      <div className="flex flex-col gap-3">
        <div className="watchtower-item flex justify-between items-center p-3 rounded-xl">
          <div className="flex items-center gap-2">
            <AlertTriangle className={`w-4 h-4 ${watchtower.weak > 0 ? "text-red-500" : "text-[var(--color-sage-green)]"}`} />
            <span className="text-sm font-semibold">{t("weakPasswords")}</span>
          </div>
          <span className={`font-bold ${watchtower.weak > 0 ? "text-red-500" : "text-black/50"}`}>{watchtower.weak}</span>
        </div>

        <div className="watchtower-item flex justify-between items-center p-3 rounded-xl">
          <div className="flex items-center gap-2">
            <KeyRound className={`w-4 h-4 ${watchtower.reused > 0 ? "text-amber-500" : "text-[var(--color-sage-green)]"}`} />
            <span className="text-sm font-semibold">{t("reusedPasswords")}</span>
          </div>
          <span className={`font-bold ${watchtower.reused > 0 ? "text-amber-500" : "text-black/50"}`}>{watchtower.reused}</span>
        </div>

        <div className="watchtower-item flex justify-between items-center p-3 rounded-xl">
          <div className="flex items-center gap-2">
            <Clock4 className={`w-4 h-4 ${watchtower.old > 0 ? "text-blue-500" : "text-[var(--color-sage-green)]"}`} />
            <span className="text-sm font-semibold">{t("oldPasswords")}</span>
          </div>
          <span className={`font-bold ${watchtower.old > 0 ? "text-blue-500" : "text-black/50"}`}>{watchtower.old}</span>
        </div>

        <div className="watchtower-item flex justify-between items-center p-3 rounded-xl">
          <div className="flex items-center gap-2">
            <ShieldAlert className={`w-4 h-4 ${watchtower.pwned > 0 ? "text-red-500" : "text-[var(--color-sage-green)]"}`} />
            <span className="text-sm font-semibold">{t("pwnedPasswords")}</span>
          </div>
          <span className={`font-bold ${watchtower.pwned > 0 ? "text-red-500" : "text-black/50"}`}>{watchtower.pwned}</span>
        </div>
      </div>

      <button
        onClick={handleScanPwned}
        disabled={isPwnedScanning || passwords.length === 0 || !hibpEnabled || hibpPolicyLocked}
        className="mt-4 w-full flex items-center justify-center gap-2 bg-gradient-to-r from-red-500/10 to-amber-500/10 hover:from-red-500/20 hover:to-amber-500/20 border border-red-500/20 text-red-600 py-2.5 rounded-xl text-xs font-bold shadow-sm transition-all relative overflow-hidden disabled:opacity-50"
      >
        {isPwnedScanning ? (
          <>
            <div
              className="absolute left-0 top-0 bottom-0 bg-red-500/20 transition-all duration-300"
              style={{ width: `${pwnedScanProgress}%` }}
            />
            <span className="relative z-10 animate-pulse">{t("scanningProgress", { progress: pwnedScanProgress })}</span>
          </>
        ) : (
          <>
            <Globe className="w-4 h-4" /> {t("hibpScan")}
          </>
        )}
      </button>

      <label className="watchtower-status-box mt-3 flex items-center justify-between rounded-xl px-3 py-2 text-[11px] font-semibold">
        <span>{t('hibpPrivacyToggle')}</span>
        <input
          type="checkbox"
          checked={hibpEnabled}
          onChange={(e) => setHibpEnabled(e.target.checked)}
          disabled={hibpPolicyLocked}
          className="h-4 w-4 rounded border-gray-300 text-[var(--color-sage-green)] focus:ring-[var(--color-sage-green)]/40"
        />
      </label>

      {hibpPolicyLocked && (
        <div className="mt-2 rounded-xl border border-amber-300/40 bg-amber-50/60 px-3 py-2 text-[11px] font-medium text-amber-700">
          {t('securityModeProfileLockedHibpHint')}
        </div>
      )}

      {hibpLastResult === 'unknown' && (
        <div className="mt-2 rounded-xl border border-amber-300/40 bg-amber-50/60 px-3 py-2 text-[11px] font-medium text-amber-700">
          {t('hibpResultUnknown')}
        </div>
      )}
    </GlowCard>
  );
}

