import { useState } from "react";

/**
 * GlowCard — Premium glassmorphism kartı, fare takibi ile radyal ışıma efekti.
 * Dashboard, Settings, Sidebar ve diğer card tabanlı UI elementleri tarafından kullanılır.
 */
export function GlowCard({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [opacity, setOpacity] = useState(0);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setPosition({ x: e.clientX - rect.left, y: e.clientY - rect.top });
  };

  return (
    <div
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setOpacity(1)}
      onMouseLeave={() => setOpacity(0)}
      className={`relative overflow-hidden group/glow transition-transform duration-500 hover:scale-[1.01] ${className}`}
    >
      <div
        className="pointer-events-none absolute -inset-px transition-opacity duration-500 z-0"
        style={{
          opacity,
          background: `radial-gradient(600px circle at ${position.x}px ${position.y}px, rgba(135,159,132,0.18), transparent 40%)`,
        }}
      />
      <div className="relative z-10 w-full h-full flex flex-col">{children}</div>
    </div>
  );
}

/**
 * SecurityScoreGauge — SVG dairesel güvenlik skoru göstergesi.
 * Watchtower skorunu görselleştirir: yeşil (>80), amber (>50), kırmızı (≤50).
 */
// @ts-nocheck

export function SecurityScoreGauge({ score, onClick }: { score: number; onClick: () => void }) {
  const dashArray = 2 * Math.PI * 45;
  const dashOffset = dashArray - (dashArray * score) / 100;

  return (
    <button
      onClick={onClick}
      className="group relative flex items-center justify-center w-24 h-24 transition-transform hover:scale-110 active:scale-95"
      aria-label={`Security score: ${score}`}
    >
      <svg className="w-full h-full -rotate-90 transform">
        <circle cx="48" cy="48" r="45" fill="transparent" stroke="currentColor" strokeWidth="6" className="entry-divider" />
        <circle
          cx="48"
          cy="48"
          r="45"
          fill="transparent"
          stroke="currentColor"
          strokeWidth="6"
          strokeDasharray={dashArray}
          style={{ strokeDashoffset: dashOffset }}
          strokeLinecap="round"
          className={`transition-all duration-1000 ease-out ${
            score > 80 ? "text-[var(--color-sage-green)]" : score > 50 ? "text-amber-500" : "text-red-500"
          }`}
        />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <span className="text-xl font-bold tracking-tighter text-[var(--color-deep-navy)]">{score}</span>
        <span className="text-[8px] uppercase font-black opacity-40">Score</span>
      </div>
      <div
        className={`absolute inset-0 rounded-full animate-ping opacity-20 pointer-events-none ${
          score > 80 ? "bg-[var(--color-sage-green)]" : "bg-red-500"
        }`}
        style={{ animationDuration: "3s" }}
      />
    </button>
  );
}

/**
 * Aegis Vault Encryption Profiles
 * 
 * Defines how much metadata is encrypted at rest to balance 
 * privacy vs performance (especially for searching).
 */
// @ts-nocheck


export type EncryptionProfile = 'maximum' | 'balanced' | 'performance';

export const ENCRYPTION_PROFILES: Record<EncryptionProfile, string[]> = {
  // En yüksek gizlilik, yavaş tam metin arama
  'maximum': [
    'title', 'username', 'website', 'category', 'tags',
    'notes', 'attachments'
  ],
  // Dengeli (ön tanımlı), isim ve kategori düz okunabilir, kullanıcı adları/url'ler gizli
  'balanced': [
    'username', 'website', 'notes', 'attachments'
  ],
  // Performans odaklı, sadece kritik şeyler şifrelenir
  'performance': [
    'notes', 'attachments'
  ]
};

export function isFieldEncrypted(profile: EncryptionProfile, field: string): boolean {
  if (profile === 'maximum') return true; 
  return ENCRYPTION_PROFILES[profile].includes(field);
}

