import { useState, useEffect, useCallback } from 'react';

export function useClipboard(timeoutSeconds = 30) {
  const [copiedId, setCopiedId] = useState<number | null>(null);
  const [timeLeft, setTimeLeft] = useState(0);

  const copy = useCallback((id: number, text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeLeft(timeoutSeconds);
  }, [timeoutSeconds]);

  useEffect(() => {
    if (timeLeft > 0) {
      const timer = setInterval(() => {
        setTimeLeft((prev) => {
          if (prev <= 1) {
            // Memory sanitization for clipboard
            navigator.clipboard.writeText('');
            setCopiedId(null);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
      return () => clearInterval(timer);
    }
  }, [timeLeft]);

  return { copiedId, timeLeft, copy, timeoutSeconds };
}

// @ts-nocheck
import { useEffect } from 'react';

interface ShortcutConfigs {
    onSearch?: () => void;
    onLock?: () => void;
    onNewEntry?: () => void;
    onEscape?: () => void;
}

export const useKeyboardShortcuts = (configs: ShortcutConfigs) => {
    useEffect(() => {
        const handleKeyDown = (event: KeyboardEvent) => {
            const isMod = event.ctrlKey || event.metaKey;

            // Ctrl + F: Search
            if (isMod && event.key === 'f') {
                if (configs.onSearch) {
                    event.preventDefault();
                    configs.onSearch();
                }
            }

            // Ctrl + L: Lock
            if (isMod && event.key === 'l') {
                if (configs.onLock) {
                    event.preventDefault();
                    configs.onLock();
                }
            }

            // Ctrl + N: New Entry
            if (isMod && event.key === 'n') {
                if (configs.onNewEntry) {
                    event.preventDefault();
                    configs.onNewEntry();
                }
            }

            // Escape: Close/Clear
            if (event.key === 'Escape') {
                if (configs.onEscape) {
                    configs.onEscape();
                }
            }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [configs]);
};

