    const bitwardenCsv =
      "folder,favorite,type,name,notes,fields,reprompt,login_uri,login_username,login_password,login_totp\n" +
      "Work,0,login,Netflix,,,0,https://netflix.com,user@example.com,secretPass123,\n";

