  };
};

const hasHeader = (headers: string[], ...candidates: string[]): boolean =>
  candidates.some((candidate) => headers.includes(candidate));

const findHeaderIndex = (headers: string[], ...candidates: string[]): number =>
  headers.findIndex((value) => candidates.includes(value));

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0;

const normalizeCategory = (value: string | undefined): string =>
  value && value.trim() ? value.trim() : "General";

const normalizeUrl = (value: string | undefined): string =>
  String(value || "").trim();

const buildEntry = (candidate: {
  title?: string;
  username?: string;
  pass?: string;
  website?: string;
  category?: string;
  tags?: string[];
}): Partial<VaultEntry> | null => {
  const title = String(candidate.title || "").trim();
  const username = String(candidate.username || "").trim();
  const pass = String(candidate.pass || "").trim();
  const website = String(candidate.website || "").trim();

  if (!pass) return null;

  return {
    title: title || website || username || "Imported Entry",
    username,
    pass,
    website,
    category: normalizeCategory(candidate.category),
    tags: candidate.tags?.filter(Boolean) || [],
  };
};

const toCanonicalRecord = (candidate: {
  title?: string;
  username?: string;
  pass?: string;
  website?: string;
  category?: string;
  tags?: string[];
  notes?: string;
}): CanonicalVaultRecord | null => {
  const password = String(candidate.pass || "").trim();
  if (!password) return null;

  const title = String(candidate.title || "").trim();
  const username = String(candidate.username || "").trim();
  const url = normalizeUrl(candidate.website);
  const tags = candidate.tags?.filter(Boolean) || [];
  const notes = String(candidate.notes || "").trim();

  return {
    id: `import-${Math.random().toString(36).slice(2, 10)}`,
    title: title || url || username || "Imported Entry",
    username,
    url,
    category: normalizeCanonicalCategory(candidate.category),
    favorite: false,
    tags,
    deleted_at: null,
    secret: {
      password,
      ...(notes ? { notes } : {}),
    },
    attachments: [],
  };
};

const createEmptyReport = (sourceFormat: "csv" | "json"): ImportAnalysisReport => ({
  sourceFormat,
  totalRows: 0,
  validEntries: 0,
  skippedRows: 0,
  weakPasswords: 0,
  missingCriticalFields: 0,
  duplicateCandidates: 0,
  warnings: [],
});

const finalizeReport = (
  entries: Partial<VaultEntry>[],
  report: ImportAnalysisReport
): ImportAnalysisReport => {
  const seen = new Set<string>();

  for (const entry of entries) {
    if (!entry.title || !entry.username || !entry.website) {
      report.missingCriticalFields += 1;
    }
    if (!entry.pass || entry.pass.length < 8) {
      report.weakPasswords += 1;
    }

    const signature = `${entry.title || ""}::${entry.username || ""}::${entry.website || ""}`.toLowerCase();
    if (seen.has(signature)) {
      report.duplicateCandidates += 1;
    } else {
      seen.add(signature);
    }
  }

  report.validEntries = entries.length;
  return report;
};

const parseDelimitedRows = (text: string, separator: string): string[][] => {
  const rows: string[][] = [];
  let row: string[] = [];
  let cell = "";
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const next = text[i + 1];

    if (char === '"') {
      if (inQuotes && next === '"') {
        cell += '"';
        i += 1;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }

    if (char === separator && !inQuotes) {
      row.push(cell.trim());
      cell = "";
      continue;
    }

    if ((char === "\n" || char === "\r") && !inQuotes) {
      if (char === "\r" && next === "\n") {
        i += 1;
      }
      row.push(cell.trim());
      if (row.some((value) => value.length > 0)) {
        rows.push(row.map((value) => value.replace(/^"|"$/g, "").trim()));
      }
      row = [];
      cell = "";
      continue;
    }

    cell += char;
  }

  row.push(cell.trim());
  if (row.some((value) => value.length > 0)) {
    rows.push(row.map((value) => value.replace(/^"|"$/g, "").trim()));
  }

  return rows;
};

export class ImportService {
  static async parseFile(file: File, onProgress: ProgressCallback): Promise<ImportParseResult> {
    return new Promise((resolve, reject) => {
      onProgress({ totalAnalyzed: 0, processed: 0, status: "parsing" });

      const reader = new FileReader();

      reader.onload = (event) => {
        try {
          const text = String(event.target?.result || "");
          if (!text.trim()) {
            throw new Error("File is empty or corrupted.");
          }

          const result = file.name.toLowerCase().endsWith(".json")
            ? this.parseJson(text)
            : this.parseCsv(text);

          onProgress({
            totalAnalyzed: result.entries.length,
            processed: 0,
            status: "importing",
          });

          resolve(result);
        } catch (error) {
          onProgress({
            totalAnalyzed: 0,
            processed: 0,
            status: "error",
            error: String(error),
          });
          reject(error);
        }
      };

      reader.onerror = () => {
        onProgress({
          totalAnalyzed: 0,
          processed: 0,
          status: "error",
          error: "Failed to read file.",
        });
        reject(new Error("Failed to read file."));
      };

      reader.readAsText(file);
    });
  }

  private static parseJson(text: string): ImportParseResult {
    const entries: Partial<VaultEntry>[] = [];
    const report = createEmptyReport("json");

    try {
      const parsed = JSON.parse(text);
      const arr = Array.isArray(parsed) ? parsed : parsed.items || parsed.entries || [];
      if (!Array.isArray(arr)) {
        throw new Error("Invalid JSON format. File may be corrupted.");
      }

      report.totalRows = arr.length;

      for (const item of arr) {
        if (!item || typeof item !== "object") {
          report.skippedRows += 1;
          continue;
        }

        const candidate = item as JsonImportCandidate;
        const tags = Array.isArray(candidate.tags)
          ? candidate.tags.filter(isNonEmptyString)
          : isNonEmptyString(candidate.tags)
            ? candidate.tags.split(/[;,]/).map((value) => value.trim()).filter(Boolean)
            : [];

        const entry = buildEntry({
          title: candidate.title || candidate.name || "Imported Entry",
          username: candidate.username || candidate.login?.username || "",
          pass: candidate.password || candidate.pass || candidate.login?.password || "",
          website: candidate.website || candidate.url || candidate.uri || candidate.login?.uris?.[0]?.uri || "",
          category: candidate.category,
          tags,
        });

        if (entry) {
          entries.push(entry);
        } else {
          report.skippedRows += 1;
        }
      }
    } catch (error) {
      if (error instanceof Error && error.message) {
        throw error;
      }
      throw new Error("Invalid JSON format. File may be corrupted.");
    }

    if (entries.length === 0) {
      throw new Error("No valid passwords could be imported from the JSON file.");
    }

    return { entries, report: finalizeReport(entries, report) };
  }

  private static parseCsv(text: string): ImportParseResult {
    const entries: Partial<VaultEntry>[] = [];
    const report = createEmptyReport("csv");
    const firstLine = text.split(/\r?\n/, 1)[0] || "";

    if (!firstLine.trim()) {
      throw new Error("CSV file is empty or lacks headers.");
    }

    const commaCount = (firstLine.match(/,/g) || []).length;
    const semicolonCount = (firstLine.match(/;/g) || []).length;
    const separator = semicolonCount > commaCount ? ";" : ",";
    const rows = parseDelimitedRows(text, separator);

    if (rows.length < 2) {
      throw new Error("CSV file is empty or lacks headers.");
    }

    const headers = rows[0].map((header) => header.toLowerCase().trim());
    report.totalRows = rows.length - 1;

    const titleIdx = findHeaderIndex(headers, "name", "title", "website name", "item name");
    const urlIdx = findHeaderIndex(headers, "url", "website", "login_uri", "uri", "website url");
    const userIdx = findHeaderIndex(headers, "username", "login_username", "login", "email", "user name");
    const passIdx = findHeaderIndex(headers, "password", "login_password", "pass");
    const categoryIdx = findHeaderIndex(headers, "category", "folder", "group", "vault");
    const tagsIdx = findHeaderIndex(headers, "tags", "tag");

    if (hasHeader(headers, "login_uri", "login_totp")) report.warnings.push("BITWARDEN_CSV_DETECTED");
    if (hasHeader(headers, "otpauth", "website name")) report.warnings.push("ONEPASSWORD_CSV_DETECTED");
    if (hasHeader(headers, "group", "last modified", "totp")) report.warnings.push("KEEPASSXC_CSV_DETECTED");
    if (hasHeader(headers, "createtime", "modifytime", "note", "vault")) report.warnings.push("PROTON_PASS_CSV_DETECTED");

    for (let i = 1; i < rows.length; i++) {
      const cols = rows[i];
      try {
        let title = titleIdx !== -1 ? cols[titleIdx] || "" : "";
        let website = urlIdx !== -1 ? cols[urlIdx] || "" : "";
        let username = userIdx !== -1 ? cols[userIdx] || "" : "";
        let pass = passIdx !== -1 ? cols[passIdx] || "" : "";

        if (titleIdx === -1 && headers.length >= 3) {
          if (passIdx === -1) pass = cols[headers.length - 1] || "";
          if (userIdx === -1) username = cols[headers.length - 2] || "";
          if (urlIdx === -1 && !website) website = cols[0] || "";
          title = website || username || "Imported Entry";
        } else if (!title) {
          title = website || username || "Imported Entry";
        }

        const tags = tagsIdx !== -1
          ? String(cols[tagsIdx] || "").split(/[;,]/).map((value) => value.trim()).filter(Boolean)
          : [];

        const entry = buildEntry({
          title,
          username,
          pass,
          website,
          category: categoryIdx !== -1 ? cols[categoryIdx] : "General",
          tags,
        });

        if (entry) {
          entries.push(entry);
        } else {
          report.skippedRows += 1;
        }
      } catch {
        report.skippedRows += 1;
      }
    }

    if (entries.length === 0) {
      throw new Error("Could not extract any valid passwords from the CSV.");
    }

    return { entries, report: finalizeReport(entries, report) };
  }

  static parseJsonCanonical(text: string): CanonicalImportParseResult {
    const result = this.parseJson(text);
    const records = result.entries
      .map((entry) =>
        toCanonicalRecord({
          title: typeof entry.title === "string" ? entry.title : "",
          username: typeof entry.username === "string" ? entry.username : "",
          pass: typeof entry.pass === "string" ? entry.pass : "",
          website: typeof entry.website === "string" ? entry.website : "",
          category: typeof entry.category === "string" ? entry.category : "",
          tags: Array.isArray(entry.tags) ? entry.tags.filter((tag): tag is string => typeof tag === "string") : [],
        })
      )
      .filter((record): record is CanonicalVaultRecord => Boolean(record));

    return {
      records,
      report: result.report,
    };
  }

  static parseCsvCanonical(text: string): CanonicalImportParseResult {
    const result = this.parseCsv(text);
    const records = result.entries
      .map((entry) =>
        toCanonicalRecord({
          title: typeof entry.title === "string" ? entry.title : "",
          username: typeof entry.username === "string" ? entry.username : "",
          pass: typeof entry.pass === "string" ? entry.pass : "",
          website: typeof entry.website === "string" ? entry.website : "",
          category: typeof entry.category === "string" ? entry.category : "",
          tags: Array.isArray(entry.tags) ? entry.tags.filter((tag): tag is string => typeof tag === "string") : [],
        })
      )
      .filter((record): record is CanonicalVaultRecord => Boolean(record));

    return {
      records,
      report: result.report,
    };
  }
}

// @ts-nocheck
import { BackupService } from './BackupService';
import type { VaultEntry } from '../vaultService';

export interface PasskeyBindingMeta {
  createdAt: string;
  lastUsedAt: string;
  version: number;
  profileId?: string | null;
  dbName?: string;
  deviceLabel?: string;
  deviceFingerprint?: string;
  rotatedAt?: string;
  rotatedFromCredentialId?: string;
  recoveryLastExportedAt?: string;
}

export interface PasskeyEventRecord {
  at: string;
  type: string;
  profileId?: string | null;
  dbName?: string;
  credentialId?: string;
  deviceFingerprint?: string;
  detail?: string;
}

export interface PasskeyRevocationRecord {
  credentialId: string;
  revokedAt: string;
  reason: string;
  profileId?: string | null;
  dbName?: string;
  deviceFingerprint?: string;
}

export interface PasskeyPolicy {
  maxBindingAgeDays: number;
  requireRecoveryExportBeforeRotation: boolean;
  blockRevokedCredentials: boolean;
}

export interface PasskeyBindingRecord {
  credentialId: string;
  encryptedPayload: string;
  prfSalt: string;
  meta: PasskeyBindingMeta;
  eventLog?: PasskeyEventRecord[];
}

interface RecoveryPackage {
  kind: 'aegis-passkey-recovery-v2';
  binding: PasskeyBindingRecord;
  revocations: PasskeyRevocationRecord[];
  policy: PasskeyPolicy;
}

const BINDINGS_KEY = 'aegis_passkey_bindings_v1';
const LEGACY_ID_KEY = 'aegis_passkey_id';
const LEGACY_DATA_KEY = 'aegis_passkey_data';
const LEGACY_SALT_KEY = 'aegis_prf_salt';
const LEGACY_META_KEY = 'aegis_passkey_meta';
const PASSKEY_AUDIT_KEY = 'aegis_passkey_audit_v1';
const PASSKEY_REVOCATIONS_KEY = 'aegis_passkey_revocations_v1';
const PASSKEY_POLICY_KEY = 'aegis_passkey_policy_v1';
const PASSKEY_EVENT_LIMIT = 24;
const SECURE_DB_NAME = 'aegis-secure-meta-v1';
const SECURE_DB_STORE = 'secure_kv';
const SECURE_DB_KEY = 'passkey_state_v2';
const DEFAULT_POLICY: PasskeyPolicy = {
  maxBindingAgeDays: 90,
  requireRecoveryExportBeforeRotation: false,
  blockRevokedCredentials: true,
};

interface PasskeySecureState {
  bindings: Record<string, PasskeyBindingRecord>;
  auditLog: PasskeyEventRecord[];
  revocations: PasskeyRevocationRecord[];
  policy: PasskeyPolicy;
}

const profileKey = (profileId?: string | null, dbName?: string) => {
  return `${profileId || 'default'}::${dbName || 'aegis_opfs_vault'}`;
};

const safeParse = <T>(raw: string | null): T | null => {
  if (!raw) return null;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
};

const cloneState = (state: PasskeySecureState): PasskeySecureState => ({
  bindings: JSON.parse(JSON.stringify(state.bindings || {})),
  auditLog: [...(state.auditLog || [])],
  revocations: [...(state.revocations || [])],
  policy: { ...DEFAULT_POLICY, ...(state.policy || {}) },
});

const createDefaultState = (): PasskeySecureState => ({
  bindings: {},
  auditLog: [],
  revocations: [],
  policy: { ...DEFAULT_POLICY },
});

let secureStateCache: PasskeySecureState = createDefaultState();
let secureStateInitialized = false;
let secureStateInitPromise: Promise<void> | null = null;
let secureStatePersistPromise: Promise<void> = Promise.resolve();

const hasIndexedDb = () => typeof indexedDB !== 'undefined';

const openSecureDb = async (): Promise<IDBDatabase | null> => {
  if (!hasIndexedDb()) return null;
  return await new Promise((resolve, reject) => {
    const request = indexedDB.open(SECURE_DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(SECURE_DB_STORE)) {
        db.createObjectStore(SECURE_DB_STORE);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('SECURE_DB_OPEN_FAILED'));
  });
};

const readStateFromIndexedDb = async (): Promise<PasskeySecureState | null> => {
  const db = await openSecureDb();
  if (!db) return null;
  return await new Promise((resolve, reject) => {
    const tx = db.transaction(SECURE_DB_STORE, 'readonly');
    const store = tx.objectStore(SECURE_DB_STORE);
    const request = store.get(SECURE_DB_KEY);
    request.onsuccess = () => {
      resolve(request.result ? normalizePersistedState(request.result) : null);
    };
    request.onerror = () => reject(request.error || new Error('SECURE_DB_READ_FAILED'));
    tx.oncomplete = () => db.close();
    tx.onerror = () => reject(tx.error || new Error('SECURE_DB_READ_FAILED'));
  });
};

const writeStateToIndexedDb = async (state: PasskeySecureState): Promise<void> => {
  const db = await openSecureDb();
  if (!db) return;
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(SECURE_DB_STORE, 'readwrite');
    const store = tx.objectStore(SECURE_DB_STORE);
    store.put(cloneState(state), SECURE_DB_KEY);
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => reject(tx.error || new Error('SECURE_DB_WRITE_FAILED'));
  });
};

const clearStateInIndexedDb = async (): Promise<void> => {
  const db = await openSecureDb();
  if (!db) return;
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(SECURE_DB_STORE, 'readwrite');
    tx.objectStore(SECURE_DB_STORE).delete(SECURE_DB_KEY);
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => reject(tx.error || new Error('SECURE_DB_CLEAR_FAILED'));
  });
};

const normalizePersistedState = (state: unknown): PasskeySecureState => {
  const candidate = (state && typeof state === 'object') ? state as Partial<PasskeySecureState> : {};
  return {
    bindings: candidate.bindings && typeof candidate.bindings === 'object' ? candidate.bindings as Record<string, PasskeyBindingRecord> : {},
    auditLog: Array.isArray(candidate.auditLog) ? candidate.auditLog : [],
    revocations: Array.isArray(candidate.revocations) ? candidate.revocations : [],
    policy: {
      maxBindingAgeDays: typeof candidate.policy?.maxBindingAgeDays === 'number' ? candidate.policy.maxBindingAgeDays : DEFAULT_POLICY.maxBindingAgeDays,
      requireRecoveryExportBeforeRotation: typeof candidate.policy?.requireRecoveryExportBeforeRotation === 'boolean' ? candidate.policy.requireRecoveryExportBeforeRotation : DEFAULT_POLICY.requireRecoveryExportBeforeRotation,
      blockRevokedCredentials: typeof candidate.policy?.blockRevokedCredentials === 'boolean' ? candidate.policy.blockRevokedCredentials : DEFAULT_POLICY.blockRevokedCredentials,
    },
  };
};

const clearLegacyStorageKeys = () => {
  localStorage.removeItem(BINDINGS_KEY);
  localStorage.removeItem(LEGACY_ID_KEY);
  localStorage.removeItem(LEGACY_DATA_KEY);
  localStorage.removeItem(LEGACY_SALT_KEY);
  localStorage.removeItem(LEGACY_META_KEY);
  localStorage.removeItem(PASSKEY_AUDIT_KEY);
  localStorage.removeItem(PASSKEY_REVOCATIONS_KEY);
  localStorage.removeItem(PASSKEY_POLICY_KEY);
};

const loadLegacyState = (): PasskeySecureState => {
  const bindings = safeParse<Record<string, PasskeyBindingRecord>>(localStorage.getItem(BINDINGS_KEY));
  const auditLog = safeParse<PasskeyEventRecord[]>(localStorage.getItem(PASSKEY_AUDIT_KEY));
  const revocations = safeParse<PasskeyRevocationRecord[]>(localStorage.getItem(PASSKEY_REVOCATIONS_KEY));
  const policyRaw = safeParse<PasskeyPolicy>(localStorage.getItem(PASSKEY_POLICY_KEY));
  return normalizePersistedState({
    bindings: bindings && typeof bindings === 'object' ? bindings : {},
    auditLog: Array.isArray(auditLog) ? auditLog : [],
    revocations: Array.isArray(revocations) ? revocations : [],
    policy: policyRaw || DEFAULT_POLICY,
  });
};

const schedulePersist = () => {
  secureStatePersistPromise = secureStatePersistPromise
    .catch(() => undefined)
    .then(async () => {
      if (!hasIndexedDb()) return;
      await writeStateToIndexedDb(secureStateCache);
    });
  return secureStatePersistPromise;
};

const ensureBootstrappedState = () => {
  if (secureStateInitialized) return;
  secureStateCache = loadLegacyState();
};

const readBindingMap = (): Record<string, PasskeyBindingRecord> => {
  ensureBootstrappedState();
  return secureStateCache.bindings;
};

const writeBindingMap = (map: Record<string, PasskeyBindingRecord>) => {
  secureStateCache.bindings = map;
  void schedulePersist();
};

const readAuditLog = (): PasskeyEventRecord[] => {
  ensureBootstrappedState();
  return secureStateCache.auditLog;
};

const writeAuditLog = (events: PasskeyEventRecord[]) => {
  secureStateCache.auditLog = events.slice(-PASSKEY_EVENT_LIMIT * 4);
  void schedulePersist();
};

const readRevocations = (): PasskeyRevocationRecord[] => {
  ensureBootstrappedState();
  return secureStateCache.revocations;
};

const writeRevocations = (items: PasskeyRevocationRecord[]) => {
  secureStateCache.revocations = items.slice(-PASSKEY_EVENT_LIMIT * 4);
  void schedulePersist();
};

const readPolicy = (): PasskeyPolicy => {
  ensureBootstrappedState();
  const parsed = secureStateCache.policy;
  return {
    maxBindingAgeDays: typeof parsed?.maxBindingAgeDays === 'number' ? parsed.maxBindingAgeDays : DEFAULT_POLICY.maxBindingAgeDays,
    requireRecoveryExportBeforeRotation: typeof parsed?.requireRecoveryExportBeforeRotation === 'boolean' ? parsed.requireRecoveryExportBeforeRotation : DEFAULT_POLICY.requireRecoveryExportBeforeRotation,
    blockRevokedCredentials: typeof parsed?.blockRevokedCredentials === 'boolean' ? parsed.blockRevokedCredentials : DEFAULT_POLICY.blockRevokedCredentials,
  };
};

const writePolicy = (policy: PasskeyPolicy) => {
  secureStateCache.policy = policy;
  void schedulePersist();
};

const getDeviceInfo = () => {
  const platform = typeof navigator !== 'undefined' ? (navigator.platform || 'unknown') : 'unknown';
  const locale = typeof navigator !== 'undefined' ? (navigator.language || 'en') : 'en';
  const userAgent = typeof navigator !== 'undefined' ? (navigator.userAgent || '') : '';
  const deviceLabel = `This device / ${platform}`;
  const fingerprintSource = JSON.stringify({ platform, locale, userAgent });
  let hash = 0;
  for (let i = 0; i < fingerprintSource.length; i += 1) {
    hash = ((hash << 5) - hash) + fingerprintSource.charCodeAt(i);
    hash |= 0;
  }
  const normalized = Math.abs(hash).toString(16).padStart(8, '0');
  return {
    deviceLabel,
    deviceFingerprint: normalized,
  };
};

const appendEvent = (
  map: Record<string, PasskeyBindingRecord>,
  key: string,
  event: PasskeyEventRecord
) => {
  if (map[key]) {
    map[key].eventLog = [...(map[key].eventLog || []), event].slice(-PASSKEY_EVENT_LIMIT);
  }
  writeAuditLog([...readAuditLog(), event]);
};

const migrateLegacyIfExists = (profileId?: string | null, dbName?: string): PasskeyBindingRecord | null => {
  const credentialId = localStorage.getItem(LEGACY_ID_KEY) || '';
  const encryptedPayload = localStorage.getItem(LEGACY_DATA_KEY) || '';
  const prfSalt = localStorage.getItem(LEGACY_SALT_KEY) || '';
  if (!credentialId || !encryptedPayload || !prfSalt) return null;

  const legacyMeta = safeParse<PasskeyBindingMeta>(localStorage.getItem(LEGACY_META_KEY));
  const now = new Date().toISOString();
  const record: PasskeyBindingRecord = {
    credentialId,
    encryptedPayload,
    prfSalt,
    meta: {
      createdAt: legacyMeta?.createdAt || now,
      lastUsedAt: legacyMeta?.lastUsedAt || now,
      version: 1,
      profileId: profileId || legacyMeta?.profileId || null,
      dbName: dbName || legacyMeta?.dbName || 'aegis_opfs_vault',
      ...getDeviceInfo(),
    },
    eventLog: [],
  };

  const map = readBindingMap();
  map[profileKey(profileId, dbName)] = record;
  appendEvent(map, profileKey(profileId, dbName), {
    at: now,
    type: 'legacy_migrated',
    profileId: record.meta.profileId,
    dbName: record.meta.dbName,
    credentialId: record.credentialId,
    deviceFingerprint: record.meta.deviceFingerprint,
    detail: 'Legacy passkey binding migrated into profile-scoped store.',
  });
  writeBindingMap(map);

  localStorage.removeItem(LEGACY_ID_KEY);
  localStorage.removeItem(LEGACY_DATA_KEY);
  localStorage.removeItem(LEGACY_SALT_KEY);
  localStorage.removeItem(LEGACY_META_KEY);

  return record;
};

export class PasskeyBindingService {
  static async initialize(): Promise<void> {
    if (secureStateInitialized) return;
    if (secureStateInitPromise) return secureStateInitPromise;

    secureStateInitPromise = (async () => {
      if (!hasIndexedDb()) {
        secureStateCache = loadLegacyState();
        secureStateInitialized = true;
        return;
      }

      try {
        const stored = await readStateFromIndexedDb();
        if (stored) {
          secureStateCache = stored;
        } else {
          secureStateCache = loadLegacyState();
          await writeStateToIndexedDb(secureStateCache);
        }
        clearLegacyStorageKeys();
      } catch {
        secureStateCache = loadLegacyState();
      }
      secureStateInitialized = true;
    })().finally(() => {
      secureStateInitPromise = null;
    });

    return secureStateInitPromise;
  }

  static async flush(): Promise<void> {
    await this.initialize();
    await schedulePersist();
  }

  static getPolicy(): PasskeyPolicy {
    return readPolicy();
  }

  static updatePolicy(nextPolicy: Partial<PasskeyPolicy>): PasskeyPolicy {
    const merged = {
      ...readPolicy(),
      ...nextPolicy,
    };
    writePolicy(merged);
    writeAuditLog([...readAuditLog(), {
      at: new Date().toISOString(),
      type: 'policy_updated',
      detail: JSON.stringify(merged),
    }]);
    return merged;
  }

  static getBinding(profileId?: string | null, dbName?: string): PasskeyBindingRecord | null {
    const key = profileKey(profileId, dbName);
    const map = readBindingMap();
    if (map[key]) return map[key];
    return migrateLegacyIfExists(profileId, dbName);
  }

  static saveBinding(profileId: string | null, dbName: string, record: PasskeyBindingRecord): void {
    const key = profileKey(profileId, dbName);
    const map = readBindingMap();
    const now = new Date().toISOString();
    const existing = map[key];
    const deviceInfo = getDeviceInfo();
    map[key] = {
      ...record,
      meta: {
        ...record.meta,
        createdAt: record.meta.createdAt || now,
        lastUsedAt: record.meta.lastUsedAt || now,
        profileId,
        dbName,
        deviceLabel: record.meta.deviceLabel || deviceInfo.deviceLabel,
        deviceFingerprint: record.meta.deviceFingerprint || deviceInfo.deviceFingerprint,
        rotatedAt: existing ? now : record.meta.rotatedAt,
        rotatedFromCredentialId: existing ? existing.credentialId : record.meta.rotatedFromCredentialId,
      },
      eventLog: [...(existing?.eventLog || []), ...(record.eventLog || [])].slice(-PASSKEY_EVENT_LIMIT),
    };
    appendEvent(map, key, {
      at: now,
      type: existing ? 'rotated' : 'bound',
      profileId,
      dbName,
      credentialId: record.credentialId,
      deviceFingerprint: map[key].meta.deviceFingerprint,
      detail: existing ? 'Passkey binding rotated on this device.' : 'Passkey binding created on this device.',
    });
    writeBindingMap(map);
  }

  static updateLastUsed(profileId?: string | null, dbName?: string): void {
    const key = profileKey(profileId, dbName);
    const map = readBindingMap();
    if (!map[key]) return;
    const now = new Date().toISOString();
    map[key].meta = {
      ...map[key].meta,
      lastUsedAt: now,
    };
    appendEvent(map, key, {
      at: now,
      type: 'used',
      profileId: map[key].meta.profileId,
      dbName: map[key].meta.dbName,
      credentialId: map[key].credentialId,
      deviceFingerprint: map[key].meta.deviceFingerprint,
      detail: 'Passkey used to unlock vault.',
    });
    writeBindingMap(map);
  }

  static revokeBinding(profileId?: string | null, dbName?: string, reason: string = 'manual_revoke'): boolean {
    const key = profileKey(profileId, dbName);
    const map = readBindingMap();
    if (!map[key]) return false;
    const record = map[key];
    const now = new Date().toISOString();
    const revocations = readRevocations();
    revocations.push({
      credentialId: record.credentialId,
      revokedAt: now,
      reason,
      profileId: record.meta.profileId,
      dbName: record.meta.dbName,
      deviceFingerprint: record.meta.deviceFingerprint,
    });
    writeRevocations(revocations);
    appendEvent(map, key, {
      at: now,
      type: 'revoked',
      profileId: record.meta.profileId,
      dbName: record.meta.dbName,
      credentialId: record.credentialId,
      deviceFingerprint: record.meta.deviceFingerprint,
      detail: reason,
    });
    delete map[key];
    writeBindingMap(map);
    return true;
  }

  static noteRecoveryExport(profileId?: string | null, dbName?: string): void {
    const key = profileKey(profileId, dbName);
    const map = readBindingMap();
    if (!map[key]) return;
    const now = new Date().toISOString();
    map[key].meta = {
      ...map[key].meta,
      recoveryLastExportedAt: now,
    };
    appendEvent(map, key, {
      at: now,
      type: 'recovery_exported',
      profileId: map[key].meta.profileId,
      dbName: map[key].meta.dbName,
      credentialId: map[key].credentialId,
      deviceFingerprint: map[key].meta.deviceFingerprint,
      detail: 'Encrypted recovery package exported.',
    });
    writeBindingMap(map);
  }

  static hasAnyBinding(): boolean {
    const map = readBindingMap();
    return Object.keys(map).length > 0;
  }

  static clearAllBindings(): void {
    secureStateCache = createDefaultState();
    clearLegacyStorageKeys();
    void clearStateInIndexedDb();
  }

  static listBindings(): Array<PasskeyBindingRecord & { bindingKey: string }> {
    const map = readBindingMap();
    return Object.entries(map)
      .map(([bindingKey, record]) => ({ bindingKey, ...record }))
      .sort((left, right) => Date.parse(right.meta.lastUsedAt || right.meta.createdAt) - Date.parse(left.meta.lastUsedAt || left.meta.createdAt));
  }

  static getEventLog(profileId?: string | null, dbName?: string): PasskeyEventRecord[] {
    if (typeof profileId !== 'undefined' || typeof dbName !== 'undefined') {
      const binding = this.getBinding(profileId, dbName);
      return [...(binding?.eventLog || [])].reverse();
    }
    return [...readAuditLog()].reverse();
  }

  static listRevocations(): PasskeyRevocationRecord[] {
    return [...readRevocations()].reverse();
  }

  static isCredentialRevoked(credentialId: string): boolean {
    return readPolicy().blockRevokedCredentials && readRevocations().some((item) => item.credentialId === credentialId);
  }

  static getPolicyViolations(binding: PasskeyBindingRecord | null): string[] {
    if (!binding) return [];
    const policy = readPolicy();
    const violations: string[] = [];
    if (policy.blockRevokedCredentials && this.isCredentialRevoked(binding.credentialId)) {
      violations.push('PASSKEY_REVOKED');
    }
    const createdAtMs = Date.parse(binding.meta.createdAt || '');
    if (Number.isFinite(createdAtMs)) {
      const ageDays = Math.floor((Date.now() - createdAtMs) / (1000 * 60 * 60 * 24));
      if (ageDays >= policy.maxBindingAgeDays) {
        violations.push('PASSKEY_ROTATION_REQUIRED');
      }
    }
    if (
      policy.requireRecoveryExportBeforeRotation &&
      binding.meta.rotatedFromCredentialId &&
      !binding.meta.recoveryLastExportedAt
    ) {
      violations.push('PASSKEY_RECOVERY_EXPORT_REQUIRED');
    }
    return violations;
  }

  static async exportRecoveryPackage(profileId: string | null, dbName: string, password: string): Promise<string> {
    const binding = this.getBinding(profileId, dbName);
    if (!binding) throw new Error('NO_PASSKEY_BINDING');

    const pkg: RecoveryPackage = {
      kind: 'aegis-passkey-recovery-v2',
      binding,
      revocations: readRevocations(),
      policy: readPolicy(),
    };
    const encrypted = await BackupService.encryptBackup([pkg], password);
    this.noteRecoveryExport(profileId, dbName);
    return encrypted;
  }

  static async importRecoveryPackage(
    encryptedPackage: string,
    password: string,
    expectedProfileId: string | null,
    expectedDbName: string
  ): Promise<void> {
    const payload = await BackupService.decryptBackup(encryptedPackage, password);
    if (!Array.isArray(payload) || payload.length === 0) throw new Error('INVALID_RECOVERY_PACKAGE');

    const pkg = payload[0] as RecoveryPackage;
    if (!pkg || pkg.kind !== 'aegis-passkey-recovery-v2' || !pkg.binding) {
      throw new Error('INVALID_RECOVERY_PACKAGE');
    }

    const meta = pkg.binding.meta || ({} as PasskeyBindingMeta);
    if (meta.profileId && meta.profileId !== expectedProfileId) {
      throw new Error('RECOVERY_PROFILE_MISMATCH');
    }
    if (meta.dbName && meta.dbName !== expectedDbName) {
      throw new Error('RECOVERY_DB_MISMATCH');
    }

    this.saveBinding(expectedProfileId, expectedDbName, {
      ...pkg.binding,
      meta: {
        ...pkg.binding.meta,
        profileId: expectedProfileId,
        dbName: expectedDbName,
        lastUsedAt: new Date().toISOString(),
        ...getDeviceInfo(),
      },
    });
    const key = profileKey(expectedProfileId, expectedDbName);
    const map = readBindingMap();
    if (Array.isArray(pkg.revocations)) {
      const merged = [...readRevocations(), ...pkg.revocations]
        .reduce<PasskeyRevocationRecord[]>((acc, item) => {
          if (!acc.some((existing) => existing.credentialId === item.credentialId && existing.revokedAt === item.revokedAt)) {
            acc.push(item);
          }
          return acc;
        }, []);
      writeRevocations(merged);
    }
    if (pkg.policy) {
      writePolicy({
        ...readPolicy(),
        ...pkg.policy,
      });
    }
    if (map[key]) {
      appendEvent(map, key, {
        at: new Date().toISOString(),
        type: 'recovery_imported',
        profileId: expectedProfileId,
        dbName: expectedDbName,
        credentialId: map[key].credentialId,
        deviceFingerprint: map[key].meta.deviceFingerprint,
        detail: 'Recovery package imported for active vault profile.',
      });
      writeBindingMap(map);
    }
  }

  /**
   * Yeni bir WebAuthn site passkey credential kaydini, mevcut bir VaultEntry'nin
   * site passkey veri modeline (metadata) baglar.
   */
  static bindSiteCredentialToEntry(entry: VaultEntry, credentialId: string, rpId: string): VaultEntry {
    const now = new Date().toISOString();
    return {
      ...entry,
      passkeyMetadata: {
        ...(entry.passkeyMetadata || {}),
        credential_id: credentialId,
        rp_id: rpId,
        mode: "site_passkey_active",
        created_at: entry.passkeyMetadata?.created_at || now,
        last_registration_at: now,
      },
    };
  }

  /**
   * Merges an external list of revocations into the local store.
   * Used by QR Sync and future encrypted sync to propagate revocation intent.
   */
  static mergeExternalRevocations(external: PasskeyRevocationRecord[]): number {
    const local = readRevocations();
    const map = new Map<string, PasskeyRevocationRecord>();

    // De-duplicate by credentialId (keep the one with latest revokedAt)
    [...local, ...external].forEach(rev => {
      const existing = map.get(rev.credentialId);
      if (!existing || Date.parse(rev.revokedAt) > Date.parse(existing.revokedAt)) {
        map.set(rev.credentialId, rev);
      }
    });

    const merged = Array.from(map.values());
    const addedCount = merged.length - local.length;

    if (addedCount > 0) {
      writeRevocations(merged);
    }

    return addedCount;
  }
}

// @ts-nocheck
import type {
  PasskeyBindingRecord,
  PasskeyEventRecord,
  PasskeyPolicy,
  PasskeyRevocationRecord,
} from "./PasskeyBindingService";
import type { PasskeyProgramMode } from "../config/passkey-program";
import type { VaultEntry } from "../vaultService";

export interface PasskeyInventorySiteEntry {
  id: number;
  title: string;
  rpId: string;
  displayName: string;
  mode: PasskeyProgramMode;
  riskFlags: Array<"missing_rp_id" | "missing_credential_id" | "future_mode">;
}

export interface PasskeyInventorySummary {
  totalBindings: number;
  revokedCount: number;
  recoveryExportedCount: number;
  rotationRequiredCount: number;
  activeDeviceCount: number;
  recentEventCount: number;
  status: "healthy" | "attention";
  actionKeys: string[];
  modeCounts: Record<PasskeyProgramMode, number>;
  riskCounts: {
    missing_rp_id: number;
    missing_credential_id: number;
    future_mode: number;
  };
  sitePasskeyCount: number;
  sitePasskeyAttentionCount: number;
  siteEntries: PasskeyInventorySiteEntry[];
  previewSiteEntries: PasskeyInventorySiteEntry[];
}

const DAY_MS = 1000 * 60 * 60 * 24;

export class PasskeyInventoryService {
  static buildSummary(input: {
    bindings: Array<PasskeyBindingRecord & { bindingKey: string }>;
    policy: PasskeyPolicy;
    revocations: PasskeyRevocationRecord[];
    eventLog: PasskeyEventRecord[];
    vaultEntries?: VaultEntry[];
  }): PasskeyInventorySummary {
    const bindings = input.bindings || [];
    const revocations = input.revocations || [];
    const eventLog = input.eventLog || [];
    const policy = input.policy;
    const vaultEntries = input.vaultEntries || [];

    const siteEntries: PasskeyInventorySiteEntry[] = vaultEntries
      .filter((entry) => entry.category === "Passkeys" || entry.passkeyMetadata)
      .map((entry) => {
        const mode = entry.passkeyMetadata?.mode || "site_passkey_mvp";
        const riskFlags: PasskeyInventorySiteEntry["riskFlags"] = [];
        if (!entry.passkeyMetadata?.rp_id) riskFlags.push("missing_rp_id");
        if (!entry.passkeyMetadata?.credential_id) riskFlags.push("missing_credential_id");
        if (mode === "site_passkey_future_rp") riskFlags.push("future_mode");
        return {
          id: entry.id,
          title: entry.title || "Untitled",
          rpId: entry.passkeyMetadata?.rp_id || "",
          displayName: entry.passkeyMetadata?.display_name || "",
          mode,
          riskFlags,
        };
      })
      .sort((left, right) => {
        if (left.riskFlags.length !== right.riskFlags.length) {
          return right.riskFlags.length - left.riskFlags.length;
        }
        return left.title.localeCompare(right.title);
      });

    const recoveryExportedCount = bindings.filter((binding) => binding.meta.recoveryLastExportedAt).length;
    const rotationRequiredCount = bindings.filter((binding) => {
      const createdAtMs = Date.parse(binding.meta.createdAt || "");
      if (!Number.isFinite(createdAtMs)) return false;
      const ageDays = Math.floor((Date.now() - createdAtMs) / DAY_MS);
      return ageDays >= policy.maxBindingAgeDays;
    }).length;
    const recentEventCount = eventLog.filter((event) => {
      const atMs = Date.parse(event.at || "");
      return Number.isFinite(atMs) && Date.now() - atMs <= (7 * DAY_MS);
    }).length;

    const actionKeys: string[] = [];
    if (rotationRequiredCount > 0) actionKeys.push("passkeyInventoryActionRotate");
    if (recoveryExportedCount < bindings.length) actionKeys.push("passkeyInventoryActionRecovery");
    if (revocations.length > 0) actionKeys.push("passkeyInventoryActionAudit");
    if (siteEntries.some((entry) => entry.riskFlags.length > 0)) actionKeys.push("passkeyInventoryActionReviewSiteEntries");
    const modeCounts: Record<PasskeyProgramMode, number> = {
      vault_unlock: bindings.length,
      site_passkey_mvp: siteEntries.filter((entry) => entry.mode === "site_passkey_mvp").length,
      site_passkey_active: siteEntries.filter((entry) => entry.mode === "site_passkey_active").length,
      site_passkey_future_rp: siteEntries.filter((entry) => entry.mode === "site_passkey_future_rp").length,
    };
    const riskCounts = {
      missing_rp_id: siteEntries.filter((entry) => entry.riskFlags.includes("missing_rp_id")).length,
      missing_credential_id: siteEntries.filter((entry) => entry.riskFlags.includes("missing_credential_id")).length,
      future_mode: siteEntries.filter((entry) => entry.riskFlags.includes("future_mode")).length,
    };
    const sitePasskeyAttentionCount = siteEntries.filter((entry) => entry.riskFlags.length > 0).length;
    const hasAttention =
      rotationRequiredCount > 0 ||
      recoveryExportedCount < bindings.length ||
      sitePasskeyAttentionCount > 0;

    return {
      totalBindings: bindings.length,
      revokedCount: revocations.length,
      recoveryExportedCount,
      rotationRequiredCount,
      activeDeviceCount: bindings.length,
      recentEventCount,
      status: hasAttention ? "attention" : "healthy",
      actionKeys,
      modeCounts,
      riskCounts,
      sitePasskeyCount: siteEntries.length,
      sitePasskeyAttentionCount,
      siteEntries,
      previewSiteEntries: siteEntries.slice(0, 6),
    };
  }

  /**
   * Basarili auth sonrasi passkey metadata guncellemesi yapar.
   */
  static updateMetadataAfterAuth(entry: VaultEntry, authenticatedAt: string): VaultEntry {
    if (!entry.passkeyMetadata) return entry;
    return {
      ...entry,
      passkeyMetadata: {
        ...entry.passkeyMetadata,
        last_auth_at: authenticatedAt,
        server_verified: true,
      },
    };
  }
}

// @ts-nocheck
import type { VaultEntry } from '../vaultService';
import { BackupService } from './BackupService';
import { toBufferSource } from './crypto-types';
import {
  AEGIS_APP_VERSION,
  AEGIS_QR_SYNC_FORMAT,
  AEGIS_QR_SYNC_PAIRING_FORMAT,
} from '../config/schema-registry';
import {
  SecureAppSettings,
  type QRTransferAuditEvent,
  type QRTransferLedgerRecord,
} from './SecureAppSettings';

const TRANSFER_CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const DEFAULT_EXPIRY_MS = 5 * 60 * 1000;
const DEFAULT_PAIRING_EXPIRY_MS = 10 * 60 * 1000;

export interface QRSyncPackage {
  format: typeof AEGIS_QR_SYNC_FORMAT;
  version: typeof AEGIS_APP_VERSION;
  sessionId: string;
  createdAt: string;
  expiresAt: string;
  entryCount: number;
  payload: string;
  protectionMode: 'transfer-code' | 'transfer-code+ecdh';
  senderPublicKey?: string;
  recipientKeyFingerprint?: string;
}

export interface QRSyncReceiverSession {
  format: typeof AEGIS_QR_SYNC_PAIRING_FORMAT;
  publicKey: string;
  privateKey: CryptoKey;
  createdAt: string;
  expiresAt: string;
  fingerprint: string;
}

export interface QRSyncCreateOptions {
  transferCode: string;
  expiresInMs?: number;
  recipientPublicKey?: string;
}

export interface QRSyncParseOptions {
  transferCode: string;
  receiverSession?: QRSyncReceiverSession | null;
}

export interface QRSyncCreateResult {
  rawPackage: string;
  packageInfo: QRSyncPackage;
}

export type QRSyncEntry = Pick<VaultEntry, 'title' | 'username' | 'pass' | 'website' | 'category' | 'tags' | 'passkeyMetadata'>;

type ConsumedPackageMap = Record<string, string>;
type TransferLedgerMap = Record<string, QRTransferLedgerRecord>;

const normalizeTransferCode = (code: string): string =>
  code.toUpperCase().replace(/[^A-Z0-9]/g, '');

const encodeBase64Url = (buffer: ArrayBuffer | Uint8Array): string => {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
};

const decodeBase64Url = (value: string): Uint8Array => {
  const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
  const padded = normalized + '='.repeat((4 - (normalized.length % 4 || 4)) % 4);
  return Uint8Array.from(atob(padded), (char) => char.charCodeAt(0));
};

const randomHex = (byteLength: number): string => {
  const bytes = window.crypto.getRandomValues(new Uint8Array(byteLength));
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, '0')).join('');
};

const isQRSyncEntry = (entry: unknown): entry is QRSyncEntry => {
  if (!entry || typeof entry !== 'object') return false;
  const candidate = entry as Record<string, unknown>;
  return (
    typeof candidate.title === 'string' &&
    typeof candidate.pass === 'string' &&
    (candidate.username === undefined || typeof candidate.username === 'string') &&
    (candidate.website === undefined || typeof candidate.website === 'string') &&
    (candidate.category === undefined || typeof candidate.category === 'string') &&
    (candidate.tags === undefined || Array.isArray(candidate.tags)) &&
    (candidate.passkeyMetadata === undefined || typeof candidate.passkeyMetadata === 'object')
  );
};

const parsePairingPublicKey = (value: string): string => {
  const trimmed = value.trim();
  if (trimmed.startsWith(`${AEGIS_QR_SYNC_PAIRING_FORMAT}:`)) {
    return trimmed.slice(`${AEGIS_QR_SYNC_PAIRING_FORMAT}:`.length);
  }
  return trimmed;
};

const auditId = () => randomHex(8);

const readConsumedPackages = (): ConsumedPackageMap => {
  return SecureAppSettings.getQrConsumedPackages();
};

const readTransferLedger = (): TransferLedgerMap => {
  return SecureAppSettings.getQrTransferLedger();
};

const persistTransferLedger = (ledger: TransferLedgerMap) => {
  SecureAppSettings.setQrTransferLedger(ledger);
};

const readTransferAudit = (): QRTransferAuditEvent[] => {
  return SecureAppSettings.getQrTransferAudit();
};

const persistTransferAudit = (events: QRTransferAuditEvent[]) => {
  SecureAppSettings.setQrTransferAudit(events);
};

const persistConsumedPackages = (map: ConsumedPackageMap) => {
  SecureAppSettings.setQrConsumedPackages(map);
};

const cleanupConsumedPackages = (map: ConsumedPackageMap): ConsumedPackageMap => {
  const now = Date.now();
  const next: ConsumedPackageMap = {};
  for (const [sessionId, consumedAt] of Object.entries(map)) {
    if (now - Date.parse(consumedAt) < DEFAULT_PAIRING_EXPIRY_MS * 3) {
      next[sessionId] = consumedAt;
    }
  }
  return next;
};

const cleanupTransferAudit = (events: QRTransferAuditEvent[]): QRTransferAuditEvent[] => {
  const maxEvents = 120;
  return events
    .slice()
    .sort((a, b) => Date.parse(b.at) - Date.parse(a.at))
    .slice(0, maxEvents);
};

const cleanupTransferLedger = (ledger: TransferLedgerMap): TransferLedgerMap => {
  const now = Date.now();
  const next: TransferLedgerMap = {};
  for (const [sessionId, record] of Object.entries(ledger)) {
    const expiry = Date.parse(record.expiresAt);
    const keepWindowMs = DEFAULT_PAIRING_EXPIRY_MS * 6;
    const shouldKeep = Number.isNaN(expiry) || now - expiry < keepWindowMs;
    if (shouldKeep) {
      next[sessionId] = { ...record };
    }
  }
  return next;
};

const persistAuditEvent = (event: Omit<QRTransferAuditEvent, 'id'>) => {
  const cleaned = cleanupTransferAudit(readTransferAudit());
  cleaned.unshift({
    id: auditId(),
    ...event,
  });
  persistTransferAudit(cleaned);
};

const setTransferLedgerRecord = (record: QRTransferLedgerRecord) => {
  const cleaned = cleanupTransferLedger(readTransferLedger());
  cleaned[record.sessionId] = { ...record };
  persistTransferLedger(cleaned);
};

const getTransferLedgerRecord = (sessionId: string): QRTransferLedgerRecord | null => {
  const cleaned = cleanupTransferLedger(readTransferLedger());
  persistTransferLedger(cleaned);
  return cleaned[sessionId] ? { ...cleaned[sessionId] } : null;
};

const markPackageConsumed = (sessionId: string) => {
  const cleaned = cleanupConsumedPackages(readConsumedPackages());
  cleaned[sessionId] = new Date().toISOString();
  persistConsumedPackages(cleaned);
  const existing = getTransferLedgerRecord(sessionId);
  if (existing) {
    setTransferLedgerRecord({
      ...existing,
      status: 'consumed',
      consumedAt: cleaned[sessionId],
    });
  }
};

const hasPackageBeenConsumed = (sessionId: string): boolean => {
  const cleaned = cleanupConsumedPackages(readConsumedPackages());
  persistConsumedPackages(cleaned);
  return Boolean(cleaned[sessionId]);
};

const isPackageRevoked = (sessionId: string): boolean => {
  const record = getTransferLedgerRecord(sessionId);
  return record?.status === 'revoked';
};

const generateEcdhKeyPair = async (): Promise<CryptoKeyPair> =>
  window.crypto.subtle.generateKey(
    { name: 'ECDH', namedCurve: 'P-256' },
    true,
    ['deriveBits']
  );

const exportPublicKey = async (publicKey: CryptoKey): Promise<string> => {
  const raw = await window.crypto.subtle.exportKey('raw', publicKey);
  return encodeBase64Url(raw);
};

const importPublicKey = async (publicKey: string): Promise<CryptoKey> =>
  window.crypto.subtle.importKey(
    'raw',
    toBufferSource(decodeBase64Url(parsePairingPublicKey(publicKey))),
    { name: 'ECDH', namedCurve: 'P-256' },
    false,
    []
  );

const deriveSharedSecret = async (privateKey: CryptoKey, peerPublicKey: string): Promise<Uint8Array> => {
  const imported = await importPublicKey(peerPublicKey);
  const bits = await window.crypto.subtle.deriveBits(
    { name: 'ECDH', public: imported },
    privateKey,
    256
  );
  return new Uint8Array(bits);
};

const sha256 = async (payload: Uint8Array): Promise<Uint8Array> => {
  const digest = await window.crypto.subtle.digest('SHA-256', toBufferSource(payload));
  return new Uint8Array(digest);
};

const concatBytes = (...segments: Uint8Array[]): Uint8Array => {
  const total = segments.reduce((sum, part) => sum + part.length, 0);
  const result = new Uint8Array(total);
  let offset = 0;
  for (const part of segments) {
    result.set(part, offset);
    offset += part.length;
  }
  return result;
};

const deriveBackupPassword = async (
  transferCode: string,
  sessionId: string,
  sharedSecret?: Uint8Array
): Promise<string> => {
  const encoder = new TextEncoder();
  const material = concatBytes(
    encoder.encode(normalizeTransferCode(transferCode)),
    encoder.encode(sessionId),
    sharedSecret ?? new Uint8Array()
  );
  const digest = await sha256(material);
  return encodeBase64Url(digest);
};

const fingerprintPublicKey = async (publicKey: string): Promise<string> => {
  const digest = await sha256(decodeBase64Url(parsePairingPublicKey(publicKey)));
  return Array.from(digest.slice(0, 8), (byte) => byte.toString(16).padStart(2, '0')).join('');
};

export class QRSyncService {
  static generateTransferCode(groupCount: number = 4, groupLength: number = 4): string {
    const bytes = window.crypto.getRandomValues(new Uint8Array(groupCount * groupLength));
    const chars = Array.from(bytes, (byte) => TRANSFER_CODE_ALPHABET[byte % TRANSFER_CODE_ALPHABET.length]);
    const groups: string[] = [];

    for (let i = 0; i < chars.length; i += groupLength) {
      groups.push(chars.slice(i, i + groupLength).join(''));
    }

    return groups.join('-');
  }

  static async createReceiverSession(expiresInMs: number = DEFAULT_PAIRING_EXPIRY_MS): Promise<QRSyncReceiverSession> {
    await SecureAppSettings.initialize();
    const keyPair = await generateEcdhKeyPair();
    const publicKey = await exportPublicKey(keyPair.publicKey);
    const session: QRSyncReceiverSession = {
      format: AEGIS_QR_SYNC_PAIRING_FORMAT,
      publicKey: `${AEGIS_QR_SYNC_PAIRING_FORMAT}:${publicKey}`,
      privateKey: keyPair.privateKey,
      createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + expiresInMs).toISOString(),
      fingerprint: await fingerprintPublicKey(publicKey),
    };
    persistAuditEvent({
      type: 'receiver_session_created',
      at: session.createdAt,
      detail: 'Receiver pairing session created for QR import.',
      metadata: {
        fingerprint: session.fingerprint,
      },
    });
    return session;
  }

  static async createPackage(entries: QRSyncEntry[], options: QRSyncCreateOptions | string): Promise<QRSyncCreateResult> {
    await SecureAppSettings.initialize();
    const normalizedOptions: QRSyncCreateOptions = typeof options === 'string' ? { transferCode: options } : options;
    const normalizedCode = normalizeTransferCode(normalizedOptions.transferCode);
    if (normalizedCode.length < 8) {
      throw new Error('QR_SYNC_TRANSFER_CODE_WEAK');
    }

    const sessionId = randomHex(16);
    const createdAt = new Date().toISOString();
    const expiresAt = new Date(Date.now() + (normalizedOptions.expiresInMs ?? DEFAULT_EXPIRY_MS)).toISOString();
    let protectionMode: QRSyncPackage['protectionMode'] = 'transfer-code';
    let senderPublicKey: string | undefined;
    let recipientKeyFingerprint: string | undefined;
    let sharedSecret: Uint8Array | undefined;

    if (normalizedOptions.recipientPublicKey?.trim()) {
      const senderKeyPair = await generateEcdhKeyPair();
      senderPublicKey = await exportPublicKey(senderKeyPair.publicKey);
      sharedSecret = await deriveSharedSecret(senderKeyPair.privateKey, normalizedOptions.recipientPublicKey);
      protectionMode = 'transfer-code+ecdh';
      recipientKeyFingerprint = await fingerprintPublicKey(normalizedOptions.recipientPublicKey);
    }

    const derivedPassword = await deriveBackupPassword(normalizedCode, sessionId, sharedSecret);
    const encryptedPayload = await BackupService.encryptBackup(entries, derivedPassword);
    const qrPackage: QRSyncPackage = {
      format: AEGIS_QR_SYNC_FORMAT,
      version: AEGIS_APP_VERSION,
      sessionId,
      createdAt,
      expiresAt,
      entryCount: entries.length,
      payload: encryptedPayload,
      protectionMode,
      senderPublicKey,
      recipientKeyFingerprint,
    };

    setTransferLedgerRecord({
      sessionId,
      createdAt,
      expiresAt,
      entryCount: entries.length,
      protectionMode,
      recipientFingerprint: recipientKeyFingerprint,
      status: 'created',
    });
    persistAuditEvent({
      sessionId,
      type: 'package_created',
      at: createdAt,
      detail: 'QR transfer package created.',
      metadata: {
        entryCount: entries.length,
        protectionMode,
        recipientFingerprint: recipientKeyFingerprint,
      },
    });

    return {
      rawPackage: JSON.stringify(qrPackage),
      packageInfo: qrPackage,
    };
  }

  static async parsePackage(rawPackage: string, options: QRSyncParseOptions | string): Promise<QRSyncEntry[]> {
    await SecureAppSettings.initialize();
    const normalizedOptions: QRSyncParseOptions = typeof options === 'string' ? { transferCode: options } : options;
    const normalizedCode = normalizeTransferCode(normalizedOptions.transferCode);
    if (normalizedCode.length < 8) {
      throw new Error('QR_SYNC_TRANSFER_CODE_REQUIRED');
    }

    let qrPackage: QRSyncPackage;
    try {
      qrPackage = JSON.parse(rawPackage) as QRSyncPackage;
    } catch {
      throw new Error('QR_SYNC_INVALID_PACKAGE');
    }

    if (
      qrPackage.format !== AEGIS_QR_SYNC_FORMAT ||
      typeof qrPackage.payload !== 'string' ||
      typeof qrPackage.sessionId !== 'string' ||
      typeof qrPackage.expiresAt !== 'string'
    ) {
      throw new Error('QR_SYNC_UNSUPPORTED_FORMAT');
    }

    if (Date.parse(qrPackage.expiresAt) <= Date.now()) {
      throw new Error('QR_SYNC_PACKAGE_EXPIRED');
    }

    if (hasPackageBeenConsumed(qrPackage.sessionId)) {
      persistAuditEvent({
        sessionId: qrPackage.sessionId,
        type: 'package_rejected',
        at: new Date().toISOString(),
        detail: 'Rejected QR import because the package was already consumed.',
        metadata: {
          reason: 'already_used',
        },
      });
      throw new Error('QR_SYNC_PACKAGE_ALREADY_USED');
    }

    if (isPackageRevoked(qrPackage.sessionId)) {
      persistAuditEvent({
        sessionId: qrPackage.sessionId,
        type: 'package_rejected',
        at: new Date().toISOString(),
        detail: 'Rejected QR import because the package was revoked.',
        metadata: {
          reason: 'revoked',
        },
      });
      throw new Error('QR_SYNC_PACKAGE_REVOKED');
    }

    let sharedSecret: Uint8Array | undefined;
    if (qrPackage.protectionMode === 'transfer-code+ecdh') {
      if (!normalizedOptions.receiverSession) {
        throw new Error('QR_SYNC_PAIRING_REQUIRED');
      }
      if (Date.parse(normalizedOptions.receiverSession.expiresAt) <= Date.now()) {
        throw new Error('QR_SYNC_PAIRING_EXPIRED');
      }
      const receiverPublicKey = parsePairingPublicKey(normalizedOptions.receiverSession.publicKey);
      if (qrPackage.recipientKeyFingerprint) {
        const receiverFingerprint = await fingerprintPublicKey(receiverPublicKey);
        if (receiverFingerprint !== qrPackage.recipientKeyFingerprint) {
          throw new Error('QR_SYNC_PAIRING_MISMATCH');
        }
      }
      if (!qrPackage.senderPublicKey) {
        throw new Error('QR_SYNC_PAIRING_REQUIRED');
      }
      sharedSecret = await deriveSharedSecret(normalizedOptions.receiverSession.privateKey, qrPackage.senderPublicKey);
    }

    const derivedPassword = await deriveBackupPassword(normalizedCode, qrPackage.sessionId, sharedSecret);
    const entries = await BackupService.decryptBackup<QRSyncEntry>(qrPackage.payload, derivedPassword);
    if (!Array.isArray(entries) || !entries.every(isQRSyncEntry)) {
      throw new Error('QR_SYNC_INVALID_PAYLOAD');
    }

    markPackageConsumed(qrPackage.sessionId);
    persistAuditEvent({
      sessionId: qrPackage.sessionId,
      type: 'package_consumed',
      at: new Date().toISOString(),
      detail: 'QR transfer package imported successfully.',
      metadata: {
        protectionMode: qrPackage.protectionMode,
        entryCount: qrPackage.entryCount,
      },
    });
    return entries;
  }

  static listTransferHistory(): QRTransferLedgerRecord[] {
    return Object.values(cleanupTransferLedger(readTransferLedger())).sort(
      (a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt)
    );
  }

  static listAuditEvents(): QRTransferAuditEvent[] {
    return cleanupTransferAudit(readTransferAudit());
  }

  static revokeTransfer(sessionId: string, reason: string = 'manual_revoke'): boolean {
    const existing = getTransferLedgerRecord(sessionId);
    if (!existing || existing.status !== 'created') {
      return false;
    }

    const revokedAt = new Date().toISOString();
    setTransferLedgerRecord({
      ...existing,
      status: 'revoked',
      revokedAt,
      revokeReason: reason,
    });
    persistAuditEvent({
      sessionId,
      type: 'package_revoked',
      at: revokedAt,
      detail: 'QR transfer package revoked before import.',
      metadata: {
        reason,
      },
    });
    return true;
  }
}

