const clearLegacyKeys = () => {
  Object.values(LEGACY_KEYS).forEach((key) => {
    try {
      localStorage.removeItem(key);
    } catch {
      // ignore
    }
  });
};

const schedulePersist = () => {
  persistPromise = persistPromise
    .catch(() => undefined)
    .then(async () => {
      if (!hasIndexedDb()) return;
      await writeStateToDb(stateCache);
    });
  return persistPromise;
};

const ensureBootstrapped = () => {
  if (initialized || bootstrapped) return;
  stateCache = loadLegacyState();
  bootstrapped = true;
};

const ensureMutableState = () => {
  ensureBootstrapped();
};

export class SecureAppSettings {
  static async initialize(): Promise<void> {
    if (initialized) return;
    if (initPromise) return initPromise;

    initPromise = (async () => {
      if (!hasIndexedDb()) {
        stateCache = loadLegacyState();
        bootstrapped = true;
        initialized = true;
        return;
      }

      try {
        const stored = await readStateFromDb();
        if (stored) {
          stateCache = stored;
        } else {
          stateCache = loadLegacyState();
          await writeStateToDb(stateCache);
        }
        bootstrapped = true;
        clearLegacyKeys();
      } catch {
        stateCache = loadLegacyState();
        bootstrapped = true;
      }

      initialized = true;
    })().finally(() => {
      initPromise = null;
    });

    return initPromise;
  }

