// @ts-nocheck
import type { VaultEntry } from "../vaultService";

export type SecurityCenterIssueType =
  | "missing_second_factor"
  | "passkey_ready"
  | "aging_credentials"
  | "sensitive_sharing"
  | "device_trust"
  | "local_risk_activity";

export interface SecurityCenterIssueSummary {
  type: SecurityCenterIssueType;
  count: number;
  severity: "low" | "medium" | "high";
  messageKey: string;
  actionKey: string;
}

export interface SecurityCenterTriageItem {
  issueType: SecurityCenterIssueType;
  itemId: number;
  title: string;
  severity: "low" | "medium" | "high";
  actionKey: string;
  detailKey: string;
  reviewKey: string;
  contextKey?: string;
  reviewedAt?: string;
  reviewExpired?: boolean;
}

export interface SecurityCenterSummary {
  score: number;
  riskLevel: "low" | "medium" | "high";
  metrics: {
    missingSecondFactor: number;
    passkeyReady: number;
    agingCredentials: number;
    sensitiveSharing: number;
  };
  issues: SecurityCenterIssueSummary[];
  triageItems: SecurityCenterTriageItem[];
  reviewedTriageItems: SecurityCenterTriageItem[];
  resolvedTriageItems: SecurityCenterTriageItem[];
}

const SIX_MONTHS_MS = 1000 * 60 * 60 * 24 * 180;
const REVIEW_REAPPEAR_MS = 1000 * 60 * 60 * 24 * 7;
const LOCAL_RISK_WINDOW_MS = 1000 * 60 * 60 * 24 * 7;

function isActiveEntry(entry: VaultEntry): boolean {
  return !entry.deletedAt;
}

function hasSecondFactor(entry: VaultEntry): boolean {
  return Boolean(entry.totp_secret || entry.totpSecret || entry.passkeyMetadata?.credential_id);
}

function isCredentialEntry(entry: VaultEntry): boolean {
  return Boolean(entry.pass && (entry.website || entry.username)) && entry.category !== "Passkeys";
}

function isPasskeyReady(entry: VaultEntry): boolean {
  if (!isCredentialEntry(entry)) return false;
  if (!entry.website) return false;
  return !entry.passkeyMetadata?.credential_id;
}

function isAgingCredential(entry: VaultEntry): boolean {
  if (!isCredentialEntry(entry) || !entry.updated_at) return false;
  const updatedAt = new Date(entry.updated_at).getTime();
  if (Number.isNaN(updatedAt)) return false;
  return Date.now() - updatedAt > SIX_MONTHS_MS;
}

function hasSensitiveSharingGap(entry: VaultEntry): boolean {
  return Boolean(
    entry.sharing?.some((assignment) => assignment.is_sensitive && !assignment.emergency_access)
  );
}

interface SecurityCenterDesktopPairing {
  extensionId: string;
  browserName?: string;
  riskLevel?: string;
  riskFlags?: string[];
}

interface SecurityCenterSyncAuditEvent {
  id?: string;
  type: string;
  source: string;
  at: string;
  detail?: string;
}

export interface SecurityCenterContext {
  desktopPairings?: SecurityCenterDesktopPairing[];
  syncAuditEvents?: SecurityCenterSyncAuditEvent[];
}

function isHighRiskPairing(pairing: SecurityCenterDesktopPairing): boolean {
  return Boolean(
    pairing.riskLevel === "high" ||
      pairing.riskLevel === "medium" ||
      (Array.isArray(pairing.riskFlags) && pairing.riskFlags.length > 0)
  );
}

function isRecentLocalRiskEvent(event: SecurityCenterSyncAuditEvent): boolean {
  if (
    event.source !== "backup_import" &&
    event.source !== "structured_import" &&
    event.source !== "canonical_restore" &&
    event.source !== "migration"
  ) {
    return false;
  }
  const eventTime = new Date(event.at).getTime();
  if (Number.isNaN(eventTime)) return false;
  return Date.now() - eventTime <= LOCAL_RISK_WINDOW_MS;
}

function getReviewMeta(reviewed: Record<string, string>, reviewKey: string) {
  const reviewedAt = reviewed[reviewKey];
  if (!reviewedAt) {
    return { reviewedAt: undefined, reviewExpired: false, isActive: false };
  }
  const reviewedTime = new Date(reviewedAt).getTime();
  if (Number.isNaN(reviewedTime)) {
    return { reviewedAt, reviewExpired: true, isActive: false };
  }
  const reviewExpired = Date.now() - reviewedTime > REVIEW_REAPPEAR_MS;
  return {
    reviewedAt,
    reviewExpired,
    isActive: !reviewExpired,
  };
}

function getSeverityForIssue(issueType: SecurityCenterIssueType): "low" | "medium" | "high" {
  if (issueType === "missing_second_factor" || issueType === "sensitive_sharing") return "high";
  return "medium";
}

function getActionForIssue(issueType: SecurityCenterIssueType): string {
  if (issueType === "missing_second_factor" || issueType === "passkey_ready") {
    return "securityCenterActionReviewPasskeys";
  }
  if (issueType === "sensitive_sharing") return "securityCenterActionReviewSharing";
  return "securityCenterActionReviewPasswords";
}

function getDetailKeyForIssue(issueType: SecurityCenterIssueType): string {
  if (issueType === "missing_second_factor") return "securityCenterTriageMissingSecondFactor";
  if (issueType === "passkey_ready") return "securityCenterTriagePasskeyReady";
  if (issueType === "aging_credentials") return "securityCenterTriageAgingCredential";
  return "securityCenterTriageSensitiveSharing";
}

function parseReviewKey(reviewKey: string): { issueType: SecurityCenterIssueType; itemId: number } | null {
  const [issueType, rawId] = reviewKey.split(":");
  const itemId = Number(rawId);
  if (
    (issueType !== "missing_second_factor" &&
      issueType !== "passkey_ready" &&
      issueType !== "aging_credentials" &&
      issueType !== "sensitive_sharing") ||
    Number.isNaN(itemId)
  ) {
    return null;
  }
  return { issueType, itemId };
}

export class SecurityCenterService {
  static buildSummary(
    entries: VaultEntry[],
    reviewed: Record<string, string> = {},
    context: SecurityCenterContext = {}
  ): SecurityCenterSummary {
    const activeEntries = entries.filter(isActiveEntry);
    const credentialEntries = activeEntries.filter(isCredentialEntry);
    const riskyDesktopPairings = (context.desktopPairings || []).filter(isHighRiskPairing);
    const recentLocalRiskEvents = (context.syncAuditEvents || []).filter(isRecentLocalRiskEvent);

    const missingSecondFactor = credentialEntries.filter((entry) => !hasSecondFactor(entry)).length;
    const passkeyReady = credentialEntries.filter(isPasskeyReady).length;
    const agingCredentials = credentialEntries.filter(isAgingCredential).length;
    const sensitiveSharing = activeEntries.filter(hasSensitiveSharingGap).length;

    const penalty =
      missingSecondFactor * 8 +
      passkeyReady * 4 +
      agingCredentials * 5 +
      sensitiveSharing * 10 +
      riskyDesktopPairings.length * 6 +
      recentLocalRiskEvents.length * 3;
    const score = Math.max(0, 100 - penalty);
    const riskLevel = score >= 80 ? "low" : score >= 55 ? "medium" : "high";

    const issues: SecurityCenterIssueSummary[] = [];
    const triageItems: SecurityCenterTriageItem[] = [];

    if (missingSecondFactor > 0) {
      issues.push({
        type: "missing_second_factor",
        count: missingSecondFactor,
        severity: "high",
        messageKey: "securityCenterIssueMissingSecondFactor",
        actionKey: "securityCenterActionReviewPasskeys",
      });
      credentialEntries
        .filter((entry) => !hasSecondFactor(entry))
        .slice(0, 6)
        .forEach((entry) => {
          triageItems.push({
            issueType: "missing_second_factor",
            itemId: entry.id,
            title: entry.title || "Untitled",
            severity: "high",
            actionKey: "securityCenterActionReviewPasskeys",
            detailKey: "securityCenterTriageMissingSecondFactor",
            reviewKey: `missing_second_factor:${entry.id}`,
          });
        });
    }

    if (passkeyReady > 0) {
      issues.push({
        type: "passkey_ready",
        count: passkeyReady,
        severity: "medium",
        messageKey: "securityCenterIssuePasskeyReady",
        actionKey: "securityCenterActionReviewPasskeys",
      });
      credentialEntries
        .filter(isPasskeyReady)
        .slice(0, 6)
        .forEach((entry) => {
          triageItems.push({
            issueType: "passkey_ready",
            itemId: entry.id,
            title: entry.title || "Untitled",
            severity: "medium",
            actionKey: "securityCenterActionReviewPasskeys",
            detailKey: "securityCenterTriagePasskeyReady",
            reviewKey: `passkey_ready:${entry.id}`,
          });
        });
    }

    if (agingCredentials > 0) {
      issues.push({
        type: "aging_credentials",
        count: agingCredentials,
        severity: "medium",
        messageKey: "securityCenterIssueAgingCredentials",
        actionKey: "securityCenterActionReviewPasswords",
      });
      credentialEntries
        .filter(isAgingCredential)
        .slice(0, 6)
        .forEach((entry) => {
          triageItems.push({
            issueType: "aging_credentials",
            itemId: entry.id,
            title: entry.title || "Untitled",
            severity: "medium",
            actionKey: "securityCenterActionReviewPasswords",
            detailKey: "securityCenterTriageAgingCredential",
            reviewKey: `aging_credentials:${entry.id}`,
          });
        });
    }

    if (sensitiveSharing > 0) {
      issues.push({
        type: "sensitive_sharing",
        count: sensitiveSharing,
        severity: "high",
        messageKey: "securityCenterIssueSensitiveSharing",
        actionKey: "securityCenterActionReviewSharing",
      });
      activeEntries
        .filter(hasSensitiveSharingGap)
        .slice(0, 6)
        .forEach((entry) => {
          triageItems.push({
            issueType: "sensitive_sharing",
            itemId: entry.id,
            title: entry.title || "Untitled",
            severity: "high",
            actionKey: "securityCenterActionReviewSharing",
            detailKey: "securityCenterTriageSensitiveSharing",
            reviewKey: `sensitive_sharing:${entry.id}`,
          });
        });
    }

    if (riskyDesktopPairings.length > 0) {
      issues.push({
        type: "device_trust",
        count: riskyDesktopPairings.length,
        severity: "high",
        messageKey: "securityCenterIssueDeviceTrust",
        actionKey: "securityCenterActionReviewDevices",
      });
      riskyDesktopPairings.slice(0, 4).forEach((pairing, index) => {
        triageItems.push({
          issueType: "device_trust",
          itemId: -1000 - index,
          title: pairing.browserName || "Desktop pairing",
          severity: "high",
          actionKey: "securityCenterActionReviewDevices",
          detailKey: "securityCenterTriageDeviceTrust",
          reviewKey: `device_trust:${pairing.extensionId || index}`,
          contextKey: pairing.extensionId,
        });
      });
    }

    if (recentLocalRiskEvents.length > 0) {
      issues.push({
        type: "local_risk_activity",
        count: recentLocalRiskEvents.length,
        severity: "medium",
        messageKey: "securityCenterIssueLocalRiskActivity",
        actionKey: "securityCenterActionReviewLocalRisk",
      });
      recentLocalRiskEvents.slice(0, 4).forEach((event, index) => {
        triageItems.push({
          issueType: "local_risk_activity",
          itemId: -2000 - index,
          title: event.detail || event.type,
          severity: "medium",
          actionKey: "securityCenterActionReviewLocalRisk",
          detailKey: "securityCenterTriageLocalRiskActivity",
          reviewKey: `local_risk_activity:${event.id || `${event.source}-${index}`}`,
          contextKey: event.source,
        });
      });
    }

    const reviewedTriageItems: SecurityCenterTriageItem[] = [];
    const resolvedTriageItems: SecurityCenterTriageItem[] = [];
    const filteredTriageItems = triageItems.filter((item) => {
      const reviewMeta = getReviewMeta(reviewed, item.reviewKey);
      if (!reviewMeta.reviewedAt) return true;
      if (reviewMeta.isActive) {
        reviewedTriageItems.push({
          ...item,
          reviewedAt: reviewMeta.reviewedAt,
        });
        return false;
      }
      item.reviewedAt = reviewMeta.reviewedAt;
      item.reviewExpired = reviewMeta.reviewExpired;
      return true;
    });

    filteredTriageItems.sort((left, right) => {
      const severityRank = { high: 0, medium: 1, low: 2 };
      if (severityRank[left.severity] !== severityRank[right.severity]) {
        return severityRank[left.severity] - severityRank[right.severity];
      }
      return left.title.localeCompare(right.title);
    });

    const activeReviewKeys = new Set(triageItems.map((item) => item.reviewKey));
    Object.entries(reviewed).forEach(([reviewKey, reviewedAt]) => {
      if (activeReviewKeys.has(reviewKey)) return;
      const parsed = parseReviewKey(reviewKey);
      if (!parsed) return;
      const entry = activeEntries.find((candidate) => candidate.id === parsed.itemId);
      resolvedTriageItems.push({
        issueType: parsed.issueType,
        itemId: parsed.itemId,
        title: entry?.title || "Untitled",
        severity: getSeverityForIssue(parsed.issueType),
        actionKey: getActionForIssue(parsed.issueType),
        detailKey: getDetailKeyForIssue(parsed.issueType),
        reviewKey,
        reviewedAt,
      });
    });

    return {
      score,
      riskLevel,
      metrics: {
        missingSecondFactor,
        passkeyReady,
        agingCredentials,
        sensitiveSharing,
      },
      issues,
      triageItems: filteredTriageItems,
      reviewedTriageItems: reviewedTriageItems.sort((left, right) =>
        right.reviewedAt!.localeCompare(left.reviewedAt!)
      ),
      resolvedTriageItems: resolvedTriageItems.sort((left, right) =>
        right.reviewedAt!.localeCompare(left.reviewedAt!)
      ),
    };
  }
}

// @ts-nocheck
import { SecureAppSettings, type SecurityModeProfile } from "./SecureAppSettings";

export interface SecurityModeDefinition {
  profile: SecurityModeProfile;
  allowPlaintextExport: boolean;
  allowQrSync: boolean;
  allowHibpNetwork: boolean;
  maxAutoLockMinutes: number;
  descriptionKey: string;
}

const SECURITY_MODE_DEFINITIONS: Record<SecurityModeProfile, SecurityModeDefinition> = {
  standard: {
    profile: "standard",
    allowPlaintextExport: true,
    allowQrSync: true,
    allowHibpNetwork: true,
    maxAutoLockMinutes: 30,
    descriptionKey: "securityModeStandardDesc",
  },
  strict: {
    profile: "strict",
    allowPlaintextExport: false,
    allowQrSync: true,
    allowHibpNetwork: true,
    maxAutoLockMinutes: 5,
    descriptionKey: "securityModeStrictDesc",
  },
  maximum: {
    profile: "maximum",
    allowPlaintextExport: false,
    allowQrSync: false,
    allowHibpNetwork: false,
    maxAutoLockMinutes: 1,
    descriptionKey: "securityModeMaximumDesc",
  },
};

export class SecurityModePolicy {
  static getProfile(): SecurityModeProfile {
    return SecureAppSettings.getSecurityModeProfile();
  }

  static setProfile(profile: SecurityModeProfile): void {
    SecureAppSettings.setSecurityModeProfile(profile);
  }

  static getDefinition(profile: SecurityModeProfile = this.getProfile()): SecurityModeDefinition {
    return SECURITY_MODE_DEFINITIONS[profile];
  }

  static listDefinitions(): SecurityModeDefinition[] {
    return [
      SECURITY_MODE_DEFINITIONS.standard,
      SECURITY_MODE_DEFINITIONS.strict,
      SECURITY_MODE_DEFINITIONS.maximum,
    ];
  }

  static isPlaintextExportAllowed(profile: SecurityModeProfile = this.getProfile()): boolean {
    return this.getDefinition(profile).allowPlaintextExport;
  }

  static isQrSyncAllowed(profile: SecurityModeProfile = this.getProfile()): boolean {
    return this.getDefinition(profile).allowQrSync;
  }

  static isHibpAllowed(profile: SecurityModeProfile = this.getProfile()): boolean {
    return this.getDefinition(profile).allowHibpNetwork;
  }

  static enforceAutoLock(value: number, profile: SecurityModeProfile = this.getProfile()): number {
    const { maxAutoLockMinutes } = this.getDefinition(profile);
    if (value <= 0) {
      return maxAutoLockMinutes;
    }
    return Math.min(value, maxAutoLockMinutes);
  }
}

// @ts-nocheck
import type {
  CanonicalSharedMember,
  CanonicalSharedMemberStatus,
  CanonicalSharedRole,
  CanonicalSharedSpace,
  CanonicalSharedSpaceKind,
} from './canonical-schema';
import { SecureAppSettings } from './SecureAppSettings';
import { SharingAuditService } from './SharingAuditService';
import { VaultSharingLinkService } from './VaultSharingLinkService';

type SharedSpaceInput = Partial<CanonicalSharedSpace>;
type SharedMemberInput = Partial<CanonicalSharedMember>;

const normalizeRole = (value?: string): CanonicalSharedRole => {
  if (value === 'owner' || value === 'admin' || value === 'editor' || value === 'viewer') {
    return value;
  }
  return 'viewer';
};

const normalizeStatus = (value?: string): CanonicalSharedMemberStatus => {
  if (value === 'active' || value === 'pending' || value === 'emergency_only') {
    return value;
  }
  return 'pending';
};

const normalizeKind = (value?: string): CanonicalSharedSpaceKind => {
  if (value === 'family' || value === 'team' || value === 'private') {
    return value;
  }
  return 'private';
};

const sanitizeMember = (input: SharedMemberInput): CanonicalSharedMember | null => {
  const name = (input.name || '').trim();
  const email = (input.email || '').trim();
  if (!name && !email) return null;

  return {
    id: input.id || crypto.randomUUID(),
    name,
    email,
    role: normalizeRole(input.role),
    status: normalizeStatus(input.status),
    device_label: (input.device_label || '').trim() || undefined,
    notes: (input.notes || '').trim() || undefined,
    last_verified_at: input.last_verified_at || new Date().toISOString(),
  };
};

const describeMember = (member: CanonicalSharedMember): string =>
  member.email || member.name || member.id;

export class SharedSpaceService {
  static listSpaces(): CanonicalSharedSpace[] {
    return SecureAppSettings.getSharedSpaces();
  }

  static saveSpace(input: SharedSpaceInput): CanonicalSharedSpace | null {
    const name = (input.name || '').trim();
    if (!name) return null;

    const now = new Date().toISOString();
    const nextSpace: CanonicalSharedSpace = {
      id: input.id || crypto.randomUUID(),
      name,
      kind: normalizeKind(input.kind),
      description: (input.description || '').trim(),
      default_role:
        normalizeRole(input.default_role) === 'owner'
          ? 'viewer'
          : (normalizeRole(input.default_role) as Exclude<CanonicalSharedRole, 'owner'>),
      allow_export: Boolean(input.allow_export),
      require_review: Boolean(input.require_review),
      created_at: input.created_at || now,
      updated_at: now,
      members: Array.isArray(input.members)
        ? input.members
            .map((member) => sanitizeMember(member))
            .filter((member): member is CanonicalSharedMember => Boolean(member))
        : [],
    };

    const spaces = SecureAppSettings.getSharedSpaces();
    const previousSpace = spaces.find((space) => space.id === nextSpace.id);
    const nextSpaces = spaces.some((space) => space.id === nextSpace.id)
      ? spaces.map((space) => (space.id === nextSpace.id ? nextSpace : space))
      : [...spaces, nextSpace];
    SecureAppSettings.setSharedSpaces(nextSpaces);
    SharingAuditService.recordEvent({
      type: 'space_saved',
      spaceId: nextSpace.id,
      detail: nextSpace.name,
      metadata: {
        memberCount: nextSpace.members.length,
        kind: nextSpace.kind,
      },
    });
    this.recordMemberLifecycleEvents(previousSpace, nextSpace);
    return nextSpace;
  }

  static deleteSpace(spaceId: string): boolean {
    const normalizedId = (spaceId || '').trim();
    if (!normalizedId) return false;

    const nextSpaces = SecureAppSettings
      .getSharedSpaces()
      .filter((space) => space.id !== normalizedId);
    SecureAppSettings.setSharedSpaces(nextSpaces);
    const removedAssignments = VaultSharingLinkService.removeAssignmentsForSpace(normalizedId);
    SharingAuditService.recordEvent({
      type: 'space_deleted',
      spaceId: normalizedId,
      metadata: {
        removedAssignments,
      },
    });
    return true;
  }

  static updateMemberStatus(
    spaceId: string,
    memberId: string,
    status: CanonicalSharedMemberStatus
  ): CanonicalSharedSpace | null {
    const space = SecureAppSettings.getSharedSpaces().find((item) => item.id === spaceId);
    if (!space) return null;

    return this.saveSpace({
      ...space,
      members: space.members.map((member) =>
        member.id === memberId
          ? {
              ...member,
              status,
              last_verified_at: new Date().toISOString(),
            }
          : member
      ),
    });
  }

  static removeMember(spaceId: string, memberId: string): CanonicalSharedSpace | null {
    const space = SecureAppSettings.getSharedSpaces().find((item) => item.id === spaceId);
    if (!space) return null;

    return this.saveSpace({
      ...space,
      members: space.members.filter((member) => member.id !== memberId),
    });
  }

  private static recordMemberLifecycleEvents(
    previousSpace: CanonicalSharedSpace | undefined,
    nextSpace: CanonicalSharedSpace
  ): void {
    const previousMembers = new Map((previousSpace?.members || []).map((member) => [member.id, member]));
    const nextMembers = new Map(nextSpace.members.map((member) => [member.id, member]));

    nextSpace.members.forEach((member) => {
      const previous = previousMembers.get(member.id);
      if (!previous) {
        SharingAuditService.recordEvent({
          type: 'member_invited',
          spaceId: nextSpace.id,
          detail: describeMember(member),
          metadata: {
            status: member.status,
            role: member.role,
          },
        });
        return;
      }

      if (previous.status !== member.status || previous.role !== member.role) {
        SharingAuditService.recordEvent({
          type: 'member_status_changed',
          spaceId: nextSpace.id,
          detail: describeMember(member),
          metadata: {
            previousStatus: previous.status,
            nextStatus: member.status,
            previousRole: previous.role,
            nextRole: member.role,
          },
        });
      }
    });

    (previousSpace?.members || []).forEach((member) => {
      if (nextMembers.has(member.id)) return;
      SharingAuditService.recordEvent({
        type: 'member_removed',
        spaceId: nextSpace.id,
        detail: describeMember(member),
        metadata: {
          status: member.status,
          role: member.role,
        },
      });
    });
  }
}

// @ts-nocheck
import { SecureAppSettings, type SharingAuditEvent } from './SecureAppSettings';
import type { SharingOverviewIssue } from './SharingOverviewService';

const SHARING_AUDIT_LIMIT = 60;
export type SharingAuditFilter = 'all' | 'spaces' | 'assignments' | 'reviews';
export type SharingAuditNavigationTarget =
  | { kind: 'entry'; entryId: number }
  | { kind: 'space'; spaceId: string }
  | null;

export class SharingAuditService {
  static listEvents(): SharingAuditEvent[] {
    return SecureAppSettings.getSharingAudit();
  }

  static filterEvents(
    events: SharingAuditEvent[],
    filter: SharingAuditFilter
  ): SharingAuditEvent[] {
    if (filter === 'all') return events;
    if (filter === 'spaces') {
      return events.filter(
        (event) =>
          event.type === 'space_saved' ||
          event.type === 'space_deleted' ||
          event.type === 'member_invited' ||
          event.type === 'member_status_changed' ||
          event.type === 'member_removed'
      );
    }
    if (filter === 'reviews') {
      return events.filter((event) => event.type === 'assignment_reviewed');
    }
    return events.filter(
      (event) => event.type === 'assignment_saved' || event.type === 'assignment_cleared'
    );
  }

  static getRelatedEventIdsForIssue(
    events: SharingAuditEvent[],
    issue: Pick<SharingOverviewIssue, 'itemId' | 'type'> | null
  ): string[] {
    if (!issue) return [];
    const entryId = String(issue.itemId);
    return events
      .filter((event) => {
        if (event.entryId !== entryId) return false;
        if (issue.type === 'review_required') return event.type === 'assignment_reviewed';
        if (issue.type === 'orphaned_space' || issue.type === 'no_members') {
          return event.type === 'assignment_saved' || event.type === 'assignment_cleared';
        }
        return true;
      })
      .map((event) => event.id);
  }

  static getSuggestedFilterForEvent(event: SharingAuditEvent): SharingAuditFilter {
    if (
      event.type === 'space_saved' ||
      event.type === 'space_deleted' ||
      event.type === 'member_invited' ||
      event.type === 'member_status_changed' ||
      event.type === 'member_removed'
    ) {
      return 'spaces';
    }
    if (event.type === 'assignment_reviewed') {
      return 'reviews';
    }
    return 'assignments';
  }

  static getNavigationTarget(event: SharingAuditEvent): SharingAuditNavigationTarget {
    const entryId = Number(event.entryId);
    if (Number.isFinite(entryId) && entryId > 0) {
      return { kind: 'entry', entryId };
    }

    const spaceId = (event.spaceId || '').trim();
    if (spaceId) {
      return { kind: 'space', spaceId };
    }

    return null;
  }

  static recordEvent(
    event: Omit<SharingAuditEvent, 'id' | 'at'> & { at?: string }
  ): SharingAuditEvent {
    const nextEvent: SharingAuditEvent = {
      id: crypto.randomUUID(),
      at: event.at || new Date().toISOString(),
      type: event.type,
      entryId: event.entryId,
      spaceId: event.spaceId,
      detail: event.detail,
      metadata: event.metadata ? { ...event.metadata } : undefined,
    };

    const current = SecureAppSettings.getSharingAudit();
    SecureAppSettings.setSharingAudit([...current, nextEvent].slice(-SHARING_AUDIT_LIMIT));
    return nextEvent;
  }
}

// @ts-nocheck
import type { VaultEntry } from '../vaultService';
import type { CanonicalSharingAssignment, CanonicalSharedSpace } from './canonical-schema';
import { VaultSharingLinkService } from './VaultSharingLinkService';

export type SharingOverviewSeverity = 'high' | 'medium';
export type SharingOverviewRiskLevel = 'critical' | 'high' | 'medium' | 'low';
export type SharingOverviewIssueType =
  | 'orphaned_space'
  | 'no_members'
  | 'review_required'
  | 'sensitive_without_emergency';

export interface SharingOverviewIssue {
  itemId: number;
  title: string;
  severity: SharingOverviewSeverity;
  type: SharingOverviewIssueType;
  messageKey: string;
}

export interface SharingOverviewSpaceSummary extends CanonicalSharedSpace {
  itemCount: number;
  activeMembers: number;
  pendingMembers: number;
}

export interface SharingOverviewReport {
  score: number;
  riskLevel: SharingOverviewRiskLevel;
  summary: {
    spaces: number;
    sharedItems: number;
    familySpaces: number;
    teamSpaces: number;
    pendingMembers: number;
    reviewRequiredItems: number;
  };
  actionKeys: string[];
  issues: SharingOverviewIssue[];
  spaces: SharingOverviewSpaceSummary[];
}

const REVIEW_THRESHOLD_MS = 90 * 24 * 60 * 60 * 1000;

const cloneSpaceSummary = (space: SharingOverviewSpaceSummary): SharingOverviewSpaceSummary => ({
  ...space,
  members: space.members.map((member) => ({ ...member })),
});

const getRiskLevel = (
  score: number,
  issues: SharingOverviewIssue[],
  pendingMembers: number
): SharingOverviewRiskLevel => {
  const highCount = issues.filter((issue) => issue.severity === 'high').length;
  const mediumCount = issues.filter((issue) => issue.severity === 'medium').length;

  if (score < 40 || highCount >= 2) return 'critical';
  if (highCount >= 1 || mediumCount >= 3) return 'high';
  if (score < 80 || mediumCount >= 1 || pendingMembers > 0) return 'medium';
  return 'low';
};

const getPrimaryAssignment = (
  entry: VaultEntry,
  assignmentsMap: Record<string, CanonicalSharingAssignment[]>
): CanonicalSharingAssignment | null => {
  const key = String(entry.id);
  if (Array.isArray(assignmentsMap[key]) && assignmentsMap[key].length > 0) {
    return assignmentsMap[key][0];
  }

  if (Array.isArray(entry.sharing) && entry.sharing.length > 0) {
    return entry.sharing[0];
  }

  return null;
};

export class SharingOverviewService {
  static buildReport(
    entries: VaultEntry[],
    options?: { now?: number }
  ): SharingOverviewReport {
    const now = options?.now ?? Date.now();
    const assignmentsMap = VaultSharingLinkService.getAssignmentsMap();
    const spaces = VaultSharingLinkService.getSharedSpaces();
    const issues: SharingOverviewIssue[] = [];
    let sharedItems = 0;
    let reviewRequiredItems = 0;
    let pendingMembers = 0;

    const spaceSummaries: SharingOverviewSpaceSummary[] = spaces.map((space) => {
      const activeMembers = space.members.filter((member) => member.status === 'active').length;
      const pending = space.members.filter((member) => member.status === 'pending').length;
      pendingMembers += pending;

      return {
        ...space,
        itemCount: 0,
        activeMembers,
        pendingMembers: pending,
      };
    });

    const spaceIndex = new Map(spaceSummaries.map((space) => [space.id, space]));

    entries.forEach((entry) => {
      const assignment = getPrimaryAssignment(entry, assignmentsMap);
      if (!assignment) return;

      sharedItems += 1;
      const space = spaceIndex.get(assignment.space_id);

      if (!space) {
        issues.push({
          itemId: entry.id,
          title: entry.title || 'Untitled',
          severity: 'high',
          type: 'orphaned_space',
          messageKey: 'sharingOverview.issue.orphanedSpace',
        });
        return;
      }

      space.itemCount += 1;

      if (space.members.length === 0) {
        issues.push({
          itemId: entry.id,
          title: entry.title || 'Untitled',
          severity: 'high',
          type: 'no_members',
          messageKey: 'sharingOverview.issue.noMembers',
        });
      }

      const reviewedAt = assignment.last_reviewed_at
        ? new Date(assignment.last_reviewed_at).getTime()
        : 0;
      const requiresReview =
        space.require_review && (!reviewedAt || now - reviewedAt > REVIEW_THRESHOLD_MS);

      if (requiresReview) {
        reviewRequiredItems += 1;
        issues.push({
          itemId: entry.id,
          title: entry.title || 'Untitled',
          severity: 'medium',
          type: 'review_required',
          messageKey: 'sharingOverview.issue.reviewRequired',
        });
      }

      if (assignment.is_sensitive && !assignment.emergency_access) {
        issues.push({
          itemId: entry.id,
          title: entry.title || 'Untitled',
          severity: 'medium',
          type: 'sensitive_without_emergency',
          messageKey: 'sharingOverview.issue.sensitiveWithoutEmergency',
        });
      }
    });

    const penalty =
      issues.filter((issue) => issue.severity === 'high').length * 12 +
      issues.filter((issue) => issue.severity === 'medium').length * 6 +
      pendingMembers * 2;
    const score = Math.max(0, 100 - penalty);

    const actionKeySet = new Set<string>();
    if (issues.some((issue) => issue.type === 'orphaned_space')) {
      actionKeySet.add('sharingOverview.action.fixOrphanedSpaces');
    }
    if (issues.some((issue) => issue.type === 'no_members')) {
      actionKeySet.add('sharingOverview.action.addMembers');
    }
    if (reviewRequiredItems > 0) {
      actionKeySet.add('sharingOverview.action.reviewAccess');
    }
    if (issues.some((issue) => issue.type === 'sensitive_without_emergency')) {
      actionKeySet.add('sharingOverview.action.enableEmergencyAccess');
    }
    if (actionKeySet.size === 0) {
      actionKeySet.add('sharingOverview.action.healthy');
    }

    return {
      score,
      riskLevel: getRiskLevel(score, issues, pendingMembers),
      summary: {
        spaces: spaces.length,
        sharedItems,
        familySpaces: spaces.filter((space) => space.kind === 'family').length,
        teamSpaces: spaces.filter((space) => space.kind === 'team').length,
        pendingMembers,
        reviewRequiredItems,
      },
      actionKeys: Array.from(actionKeySet),
      issues,
      spaces: spaceSummaries
        .map((space) => cloneSpaceSummary(space))
        .sort((a, b) => a.name.localeCompare(b.name)),
    };
  }
}

