import { toBufferSource } from './crypto-types';
import { bufferToBase64url, base64urlToBuffer } from './webAuthn';

/**
 * SyncCryptoService — Aegis 4.2 Faz 2 / Adim 2.1
 * 
 * E2E Encrypted senkronizasyon icin anahtar turetimi, 
 * sifreleme ve imzalama islemlerini yonetir.
 */

export interface SyncCryptoPackage {
  payload: string; // Base64url(AES-GCM-Encrypted)
  iv: string;      // Base64url(12-byte IV)
  hmac: string;    // Base64url(HMAC-SHA256)
  nonce: string;   // Unique session nonce
}

export class SyncCryptoService {
  /**
   * Sync Root Secret'tan Encryption ve Auth anahtarlarını türetir (HKDF).
   */
  static async deriveSubKeys(rootSecret: Uint8Array): Promise<{ encryptionKey: CryptoKey, authKey: CryptoKey }> {
    const baseKey = await window.crypto.subtle.importKey(
      'raw',
      toBufferSource(rootSecret),
      'HKDF',
      false,
      ['deriveKey']
    );

    const encryptionKey = await window.crypto.subtle.deriveKey(
      {
        name: 'HKDF',
        salt: new TextEncoder().encode('aegis_sync_v1_hkdf'),
        info: new TextEncoder().encode('encryption'),
        hash: 'SHA-256',
      },
      baseKey,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );

    const authKey = await window.crypto.subtle.deriveKey(
      {
        name: 'HKDF',
        salt: new TextEncoder().encode('aegis_sync_v1_hkdf'),
        info: new TextEncoder().encode('authentication'),
        hash: 'SHA-256',
      },
      baseKey,
      { name: 'HMAC', hash: 'SHA-256', length: 256 },
      false,
      ['sign', 'verify']
    );

    return { encryptionKey, authKey };
  }

  /**
   * Veriyi E2E şifreler ve imzalar.
   */
  static async encryptAndSign(
    payload: any,
    encryptionKey: CryptoKey,
    authKey: CryptoKey
  ): Promise<SyncCryptoPackage> {
    const iv = window.crypto.getRandomValues(new Uint8Array(12));
    const nonce = window.crypto.randomUUID();
    const encoded = new TextEncoder().encode(JSON.stringify({ payload, nonce }));

    const ciphertext = await window.crypto.subtle.encrypt(
      { name: 'AES-GCM', iv: toBufferSource(iv) },
      encryptionKey,
      toBufferSource(encoded)
    );

    const hmacSource = new Uint8Array(iv.length + ciphertext.byteLength);
    hmacSource.set(iv, 0);
    hmacSource.set(new Uint8Array(ciphertext), iv.length);

    const hmac = await window.crypto.subtle.sign(
      'HMAC',
      authKey,
      toBufferSource(hmacSource)
    );

    return {
      payload: bufferToBase64url(ciphertext),
      iv: bufferToBase64url(iv.buffer as ArrayBuffer),
      hmac: bufferToBase64url(hmac),
      nonce,
    };
  }

  /**
   * Şifreli paketi doğrular ve çözer.
   */
  static async verifyAndDecrypt<T = any>(
    pkg: SyncCryptoPackage,
    encryptionKey: CryptoKey,
    authKey: CryptoKey
  ): Promise<T | null> {
    try {
      const iv = new Uint8Array(base64urlToBuffer(pkg.iv));
      const ciphertext = new Uint8Array(base64urlToBuffer(pkg.payload));
      const hmac = new Uint8Array(base64urlToBuffer(pkg.hmac));

      const hmacSource = new Uint8Array(iv.length + ciphertext.byteLength);
      hmacSource.set(iv, 0);
      hmacSource.set(new Uint8Array(ciphertext), iv.length);

      const isValid = await window.crypto.subtle.verify(
        'HMAC',
        authKey,
        toBufferSource(hmac),
        toBufferSource(hmacSource)
      );

      if (!isValid) {
        console.error('[SyncCrypto] Invalid HMAC signature');
        return null;
      }

      const decrypted = await window.crypto.subtle.decrypt(
        { name: 'AES-GCM', iv: toBufferSource(iv) },
        encryptionKey,
        toBufferSource(ciphertext)
      );

      const decoded = JSON.parse(new TextDecoder().decode(decrypted));
      
      // Nonce check or session validation logic here...
      if (decoded.nonce !== pkg.nonce) {
         console.warn('[SyncCrypto] Nonce mismatch');
      }

      return decoded.payload as T;
    } catch (err) {
      console.error('[SyncCrypto] Decryption failed:', err);
      return null;
    }
  }
}

/**
 * SyncDeviceService — Aegis 4.2 Faz 2 / Adim 2.2
 * 
 * Cihaz kaydi, fingerprinting ve trust revocation islemlerini yonetir.
 */
// @ts-nocheck


export interface SyncDeviceFingerprint {
  id: string; // Unique hash or UUID
  label: string; // "My iPhone", "Windows PC"
  addedAt: string;
  lastSyncAt?: string;
  isCurrent: boolean;
  status: 'active' | 'revoked';
}

export class SyncDeviceService {
  private static STORAGE_KEY = 'aegis_sync_devices_v1';

  /**
   * Mevcut cihaz icin fingerprint üretir.
   */
  static getLocalFingerprint(): SyncDeviceFingerprint {
    const platform = typeof navigator !== 'undefined' ? (navigator.platform || 'unknown') : 'unknown';
    const userAgent = typeof navigator !== 'undefined' ? (navigator.userAgent || '') : '';
    
    // Simple deterministic hash for demo - In production, use hardware-backed UUID if possible
    const hashStr = `${platform}-${userAgent}`;
    let hash = 0;
    for (let i = 0; i < hashStr.length; i++) {
      hash = ((hash << 5) - hash) + hashStr.charCodeAt(i);
      hash |= 0;
    }
    const id = `dv-${Math.abs(hash).toString(16).padStart(8, '0')}`;

    return {
      id,
      label: `Aegis on ${platform}`,
      addedAt: new Date().toISOString(),
      isCurrent: true,
      status: 'active',
    };
  }

  /**
   * Kayıtlı cihazları getirir.
   */
  static async getDevices(): Promise<SyncDeviceFingerprint[]> {
    const raw = localStorage.getItem(this.STORAGE_KEY);
    if (!raw) {
      const current = this.getLocalFingerprint();
      return [current];
    }
    const list = JSON.parse(raw) as SyncDeviceFingerprint[];
    const local = this.getLocalFingerprint();
    
    return list.map(d => ({
      ...d,
      isCurrent: d.id === local.id
    }));
  }

  /**
   * Yeni cihaz ekler (Sync Root Secret paylasimi sonrasi).
   */
  static async addDevice(device: SyncDeviceFingerprint): Promise<void> {
    const devices = await this.getDevices();
    if (devices.find(d => d.id === device.id)) return;
    
    devices.push({ ...device, isCurrent: false });
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(devices));
  }

  /**
   * Bir cihazı kaldırır (Trust Revocation).
   */
  static async revokeDevice(deviceId: string): Promise<boolean> {
    const devices = await this.getDevices();
    const updated = devices.map(d => {
      if (d.id === deviceId) {
        return { ...d, status: 'revoked' as const };
      }
      return d;
    });

    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(updated));
    return true;
  }

  /**
   * Cihaz listesini temizler.
   */
  static clear(): void {
    localStorage.removeItem(this.STORAGE_KEY);
  }
}

/**
 * SyncEnvelope — Aegis 4.2 Faz 2 / Adim 2.1
 * 
 * Sunucuya gonderilen ve sunucudan alinan senkronizasyon paketinin 
 * zarf (envelope) yapisi. 
 */
// @ts-nocheck


export interface SyncEnvelope {
  version: string;
  sessionId: string;
  deviceId: string;
  timestamp: string;
  sequenceNumber: number;
  payload: string; // Base64url(AES-GCM-Encrypted)
  iv: string;      // Base64url(12-byte IV)
  hmac: string;    // Base64url(HMAC-SHA256)
  metadata?: {
      entryCount: number;
      vaultId?: string;
  };
}

export class SyncEnvelopeUtil {
  static create(
    payload: string,
    iv: string,
    hmac: string,
    deviceId: string,
    options: { sessionId: string, sequenceNumber: number, entryCount?: number }
  ): SyncEnvelope {
    return {
      version: "1.0",
      sessionId: options.sessionId,
      deviceId,
      timestamp: new Date().toISOString(),
      sequenceNumber: options.sequenceNumber,
      payload,
      iv,
      hmac,
      metadata: options.entryCount ? { entryCount: options.entryCount } : undefined,
    };
  }

  static validate(env: SyncEnvelope): boolean {
    if (!env.version || !env.sessionId || !env.deviceId || !env.payload || !env.iv || !env.hmac) {
      return false;
    }
    // Check version compatibility (SemVer or fixed string)
    if (env.version !== "1.0") return false;
    return true;
  }
}

