          onerror: null,
        };
        return {
          objectStore: () => ({
            get: () => {
              const request: Record<string, unknown> = {
                result: storedState,
                onsuccess: null,
                onerror: null,
              };
              queueMicrotask(() => {
                if (typeof request.onsuccess === 'function') {
                  request.onsuccess();
                }
                if (typeof tx.oncomplete === 'function') {
                  tx.oncomplete();
                }
              });
              return request;
            },
          }),
          get oncomplete() {
            return tx.oncomplete;
          },
          set oncomplete(value) {
            tx.oncomplete = value;
