/**
 * Aegis Vault - HIBP Password Breach Checker
 * 
 * Implements k-anonymity check against HaveIBeenPwned API and 
 * provides caching for subsequent lookups to simulate 'offline' mode.
 * 
 * Full offline mode (downloading 4GB hashes) can be supported by feeding 
 * a local OPFS SQLite instance.
 */
// @ts-nocheck


import { SecureAppSettings } from './SecureAppSettings';

interface BreachDatabase {
  hashes: Map<string, number>; // Local Cache: hash -> breach count
  lastUpdated: number;
}

export class OfflineBreachChecker {
  private db: BreachDatabase;

  constructor() {
    this.db = {
      hashes: new Map<string, number>(),
      lastUpdated: Date.now()
    };
  }

  /**
   * Tam offline kullanım için SQLite entegrasyon noktası.
   * Gelişmiş modüller (Electron vb.) veya OPFS SQLite ile entegre edilerek
   * 4GB'lık hash listesi local olarak tutulabilir.
   */
  async initializeLocalDatabase(): Promise<void> {
    // 1. Download HIBP pwned passwords list (veya Electron main/pre-packaged)
    // 2. Index into local SQLite
    // Şimdilik LocalStorage cache kullanarak basic offline simülasyonu yapıyoruz.
    try {
      await SecureAppSettings.initialize();
      const cached = SecureAppSettings.getHibpCache();
      if (cached?.hashes) {
        this.db.hashes = new Map(Object.entries(cached.hashes));
        this.db.lastUpdated = cached.lastUpdated || Date.now();
      }
    } catch {
      console.warn('[HIBP] Failed to load local cache');
    }
  }

  private saveLocalCache() {
    try {
      if (this.db.hashes.size > 5000) {
        // Cache çok büyürse temizle
        this.db.hashes.clear();
      }
      const data = {
        hashes: Object.fromEntries(this.db.hashes),
        lastUpdated: this.db.lastUpdated
      };
      SecureAppSettings.setHibpCache(data);
    } catch { /* ignore quota limitations */ }
  }

  private async sha1(text: string): Promise<string> {
    const data = new TextEncoder().encode(text);
    const hashBuffer = await crypto.subtle.digest('SHA-1', data);
    const hashArray = Array.from(new Uint8Array(hashBuffer));
    return hashArray.map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
  }

  /**
   * Şifrenin sızdırılıp sızdırılmadığını K-Anonymity modeliyle kontrol eder.
   * Parolanın hiçbir zaman tam hali sunucuya gitmez, sadece SHA-1 hashinin ilk 5 karakteri gider.
   * @param password Kontrol edilecek parola
   * @returns Sızdırılma sayısı (0 = temiz, null = api/network hatası)
   */
  async checkPassword(password: string): Promise<number | null> {
    if (!password) return 0;
    
    try {
      // 1. Hash the password (SHA-1 is required by HIBP API)
      const hash = await this.sha1(password);
      
      // 2. Local lookup first (Offline/Cache mode)
      if (this.db.hashes.has(hash)) {
        return this.db.hashes.get(hash)!;
      }
      
      // 3. Fallback: k-anonymity API call (Online supplement)
      const prefix = hash.substring(0, 5);
      const suffix = hash.substring(5);
      
      const response = await fetch(`https://api.pwnedpasswords.com/range/${prefix}`);
      if (!response.ok) {
        throw new Error(`HIBP API returned ${response.status}`);
      }
      
      const text = await response.text();
      const lines = text.split('\n');
      
      let pwnCount = 0;
      
      // 4. Parse results (k-anonymity)
      for (const line of lines) {
        const [responseSuffix, countRaw] = line.split(':');
        // Suffixleri localde karşılaştır
        if (responseSuffix && responseSuffix.trim() === suffix) {
          pwnCount = parseInt(countRaw.trim(), 10);
          break;
        }
      }
      
      // 5. Update local cache (Offline DB simulation)
      this.db.hashes.set(hash, pwnCount);
      this.saveLocalCache();
      
      return pwnCount;
    } catch (err) {
      console.error('[BreachCheck] Check failed:', err);
      return null; // Hata durumunda ağ kesintisi kabul ediyoruz (false negative önlemek için null dönmeli)
    }
  }
}

export const breachChecker = new OfflineBreachChecker();
// initialize locally
breachChecker.initializeLocalDatabase().catch(() => {});

// @ts-nocheck
import type { VaultEntry, VaultAttachmentMeta } from '../vaultService';
import type {
  CanonicalAttachment,
  CanonicalSharingAssignment,
  CanonicalSecretFields,
  CanonicalVaultRecord,
} from './canonical-schema';
import { normalizeCanonicalCategory } from './canonical-schema';

const toCanonicalCategory = (category?: string) => {
  const normalized = (category || '').trim().toLowerCase();
  if (normalized === 'general') return 'login' as const;
  if (normalized === 'cards') return 'card' as const;
  if (normalized === 'identities') return 'identity' as const;
  if (normalized === 'notes') return 'note' as const;
  if (normalized === 'wifi') return 'wifi' as const;
  if (normalized === 'passkeys') return 'passkey' as const;
  return normalizeCanonicalCategory(category);
};

const fromCanonicalCategory = (category?: CanonicalVaultRecord['category']): string => {
  switch (category) {
    case 'login':
      return 'General';
    case 'card':
      return 'Cards';
    case 'identity':
      return 'Identities';
    case 'note':
      return 'Notes';
    case 'wifi':
      return 'WiFi';
    case 'passkey':
      return 'Passkeys';
    default:
      return 'General';
  }
};

const mapAttachments = (attachments?: VaultAttachmentMeta[]): CanonicalAttachment[] => {
  if (!Array.isArray(attachments)) return [];
  return attachments.map((attachment) => ({
    id: attachment.id,
    name: attachment.name || '',
    mime_type: attachment.type || '',
    size: attachment.size || 0,
  }));
};

const buildSecretFields = (entry: VaultEntry): CanonicalSecretFields | undefined => {
  const secret: CanonicalSecretFields = {};

  if (entry.pass) {
    secret.password = entry.pass;
  }

  if (entry.notes) {
    secret.notes = entry.notes;
  }

  if (entry.totpSecret || entry.totp_secret) {
    secret.totp = {
      secret: entry.totpSecret || entry.totp_secret || '',
      issuer: entry.totp_issuer || undefined,
      algorithm: entry.totp_algorithm || undefined,
      digits: entry.totp_digits || undefined,
      period: entry.totp_period || undefined,
    };
  }

  if (!secret.password && !secret.notes && !secret.totp) {
    return undefined;
  }

  return secret;
};

const mapSharingAssignments = (
  assignments?: CanonicalSharingAssignment[]
): CanonicalSharingAssignment[] | undefined => {
  if (!Array.isArray(assignments) || assignments.length === 0) return undefined;
  return assignments.map((assignment) => ({ ...assignment }));
};

export const toCanonicalVaultRecord = (entry: VaultEntry): CanonicalVaultRecord => ({
  id: entry.id,
  title: entry.title || 'Untitled',
  username: entry.username || '',
  url: entry.website || '',
  category: toCanonicalCategory(entry.category),
  favorite: false,
  tags: Array.isArray(entry.tags) ? entry.tags : [],
  deleted_at: entry.deletedAt || null,
  created_at: undefined,
  updated_at: entry.updated_at || undefined,
  secret: buildSecretFields(entry),
  attachments: mapAttachments(entry.attachments),
  passkey: entry.passkeyMetadata ? { ...entry.passkeyMetadata } : null,
  sharing: mapSharingAssignments(entry.sharing),
});

export const toCanonicalVaultRecords = (entries: VaultEntry[]): CanonicalVaultRecord[] =>
  entries.map((entry) => toCanonicalVaultRecord(entry));

const fromCanonicalAttachments = (attachments?: CanonicalAttachment[]): VaultAttachmentMeta[] => {
  if (!Array.isArray(attachments)) return [];
  return attachments.map((attachment) => ({
    id: attachment.id,
    name: attachment.name,
    type: attachment.mime_type,
    size: attachment.size,
  }));
};

export const fromCanonicalVaultRecord = (record: CanonicalVaultRecord): Partial<VaultEntry> => ({
  id: typeof record.id === 'number' ? record.id : Date.now(),
  title: record.title || 'Untitled',
  username: record.username || '',
  website: record.url || '',
  category: fromCanonicalCategory(record.category),
  tags: Array.isArray(record.tags) ? record.tags : [],
  deletedAt: record.deleted_at || undefined,
  updated_at: record.updated_at || new Date().toISOString(),
  pass: record.secret?.password || '',
  notes: record.secret?.notes || undefined,
  totpSecret: record.secret?.totp?.secret || undefined,
  totp_issuer: record.secret?.totp?.issuer || undefined,
  totp_algorithm: record.secret?.totp?.algorithm || undefined,
  totp_digits: record.secret?.totp?.digits || undefined,
  totp_period: record.secret?.totp?.period || undefined,
  attachments: fromCanonicalAttachments(record.attachments),
  passkeyMetadata: record.passkey ? { ...record.passkey } : undefined,
  sharing: Array.isArray(record.sharing) ? record.sharing.map((assignment) => ({ ...assignment })) : undefined,
});

export const fromCanonicalVaultRecords = (records: CanonicalVaultRecord[]): Partial<VaultEntry>[] =>
  records.map((record) => fromCanonicalVaultRecord(record));

// @ts-nocheck
import type { VaultEntry } from '../vaultService';
import { BackupService } from './BackupService';
import { toCanonicalVaultRecords, fromCanonicalVaultRecords } from './canonical-adapters';
import type { CanonicalBackupPayload } from './BackupService';
import { createMigrationReport, type MigrationReport } from './migration-report';
import { SyncConflictResolutionService } from './SyncConflictResolutionService';
import { SyncAuditService } from './SyncAuditService';

export class CanonicalMigrationService {
  static async migrateLegacyBackupToCanonical(
    backupContent: string,
    currentPassword: string,
    nextPassword: string = currentPassword
  ): Promise<string> {
    const legacyEntries = await BackupService.decryptBackup<Partial<VaultEntry>>(backupContent, currentPassword);
    const canonicalRecords = toCanonicalVaultRecords(legacyEntries as VaultEntry[]);
    return BackupService.encryptCanonicalBackup(canonicalRecords, nextPassword);
  }

  static async restoreCanonicalBackupToVaultEntries(
    backupContent: string,
    password: string
  ): Promise<Partial<VaultEntry>[]> {
    const payload: CanonicalBackupPayload = await BackupService.decryptCanonicalBackup(backupContent, password);
    return fromCanonicalVaultRecords(payload.records);
  }

  static async restoreCanonicalBackupToVaultEntriesWithReport(
    backupContent: string,
    password: string,
    currentEntries: VaultEntry[] = []
  ): Promise<{ entries: Partial<VaultEntry>[]; report: MigrationReport }> {
    const payload: CanonicalBackupPayload = await BackupService.decryptCanonicalBackup(backupContent, password);
    const entries = fromCanonicalVaultRecords(payload.records);
    const conflictSummary = SyncConflictResolutionService.summarize(
      currentEntries,
      entries,
      'backup_import'
    );

    const result = {
      entries,
      report: createMigrationReport({
        source: 'canonical-backup',
        target: 'desktop-vault-entry',
        success: true,
        migratedRecords: entries.length,
        issues: [],
        metadata: {
          conflictSummary,
        },
      }),
    };

    this.recordRestoreReportToSyncAudit(result.report);
    return result;
  }

  static async migrateLegacyBackupToCanonicalWithReport(
    backupContent: string,
    currentPassword: string,
    nextPassword: string = currentPassword,
    currentEntries: VaultEntry[] = []
  ): Promise<{ backup: string; report: MigrationReport }> {
    const legacyEntries = await BackupService.decryptBackup<Partial<VaultEntry>>(backupContent, currentPassword);
    const canonicalRecords = toCanonicalVaultRecords(legacyEntries as VaultEntry[]);
    const backup = await BackupService.encryptCanonicalBackup(canonicalRecords, nextPassword);
    const conflictSummary = SyncConflictResolutionService.summarize(
      currentEntries,
      legacyEntries,
      'backup_import'
    );

    const result = {
      backup,
      report: createMigrationReport({
        source: 'legacy-desktop-backup',
        target: 'canonical-backup',
        success: true,
        migratedRecords: canonicalRecords.length,
        issues: [],
        metadata: {
          passwordRotated: currentPassword !== nextPassword,
          conflictSummary,
        },
      }),
    };

    this.recordMigrationReportToSyncAudit(result.report);
    return result;
  }

  static recordRestoreReportToSyncAudit(report: MigrationReport): void {
    const conflictSummary = report.metadata?.conflictSummary as
      | { duplicateCount?: number; exactMatchCount?: number }
      | undefined;

    SyncAuditService.recordEvent({
      type: 'canonical_restore_completed',
      source: 'canonical_restore',
      detail: 'Canonical restore report recorded',
      metadata: {
        migratedRecords: report.migratedRecords,
        duplicates: conflictSummary?.duplicateCount ?? 0,
        exact: conflictSummary?.exactMatchCount ?? 0,
      },
    });
  }

  static recordMigrationReportToSyncAudit(report: MigrationReport): void {
    const conflictSummary = report.metadata?.conflictSummary as
      | { duplicateCount?: number; exactMatchCount?: number }
      | undefined;

    SyncAuditService.recordEvent({
      type: 'migration_completed',
      source: 'migration',
      detail: 'Migration report recorded',
      metadata: {
        migratedRecords: report.migratedRecords,
        duplicates: conflictSummary?.duplicateCount ?? 0,
        exact: conflictSummary?.exactMatchCount ?? 0,
      },
    });
  }
}

