    expect(trashItems.length).toBe(1);

    await vaultService.restoreFromTrash(Number(entryId));
    all = await vaultService.getPasswords();
    expect(all.find(p => Number(p.id) === Number(entryId))?.deletedAt).toBeUndefined();

