    const raw = (entry.website || "").trim();
    if (!raw) return "";
    try {
      const withProtocol = /^https?:\/\//i.test(raw) ? raw : `https://${raw}`;
      return new URL(withProtocol).hostname.replace(/^www\./i, "");
    } catch {
      return raw.replace(/^https?:\/\//i, "").split("/")[0].replace(/^www\./i, "");
