    ];
    let removed = 0;
    for (const key of keys) {
      if (!key.startsWith('aegis_') && !key.startsWith('aegis:')) continue;
      const shouldKeep = keepPrefixes.some((prefix) => key === prefix || key.startsWith(prefix));
      if (!shouldKeep) {
        localStorage.removeItem(key);
        removed++;
